    extendEnv: true,
    stderr: "pipe",
    stdout: "pipe",
  });
  const [output, exitCode] = yield* Effect.all([
    Stream.mkString(Stream.decodeText(child.all)),
    child.exitCode,
  ]);
  const publishInvocations = (yield* fs.exists(publishCaptureDirectory))
