// ---------------------------------------------------------------------------
// The configuration factory: one call turns a Model and optional adaptation
// knobs into a bound, runnable reviewer. Every knob widens what goes INTO the
// review — guidance, extra read-only tools, execution bounds, ignore globs —
// and none weakens what leaves it: anchor validation, the findings bound, and
// publication-after-settlement are applied by the run path unconditionally.
// ---------------------------------------------------------------------------

/** Options shared by both reviewer shapes. */
export interface PrReviewSharedOptions {
  /**
   * Host-side and instruction-level findings bound, clamped to the CodeReview
   * schema cap of 20.
   */
  readonly maxFindings?: number | undefined;
  /**
   * Glob patterns (`**` crosses directories, `*`/`?` stay in one segment)
   * removed from the reviewer's observation surface entirely.
   */
  readonly ignore?: ReadonlyArray<string> | undefined;
  /** Map the model's verdict onto APPROVE/REQUEST_CHANGES instead of COMMENT. */
  readonly applyVerdict?: boolean | undefined;
  /** Run-level usage bounds; defaults to the shape's packaged limits. */
  readonly budget?: UsageBudgetLimits | undefined;
  /**
   * Human-readable descriptor of the bound model (provider, model id, effort)
   * rendered into the review footer and included in the fingerprint
   * signature, so changing the binding re-reviews instead of skipping.
   */
  readonly modelLabel?: string | undefined;
}

/** Options accepted by `PrReview.make` (the flat reviewer). */
export interface PrReviewOptions<
  Provider,
  ModelProvides,
  ModelRequires,
  Extra extends ReadonlyArray<Tool.Any>,
> extends PrReviewSharedOptions {
  /** The Effect AI Model to bind; its Layer requirements stay visible in `R`. */
  readonly model: Model.Model<Provider, LanguageModel.LanguageModel | ModelProvides, ModelRequires>;
  /** Domain guidance injected between the mission framing and the procedure. */
  readonly guidance?: ReviewGuidance | undefined;
  /** Full override of the flat reviewer's execution bounds. */
  readonly policy?: AgentPolicyInput | undefined;
  /**
   * Additional tools merged into the reviewer's toolkit. Every extra tool
   * must be annotated `ToolExecutionClass: "readonly"` — construction fails
   * otherwise — and its handler Layer is the caller's to provide, so the new
   * dependency stays visible in the run's `R`.
   */
  readonly extraTools?: Extra | undefined;
}

/** How one run should publish. */
export interface RunReviewOptions {
  /** Post the review to GitHub; `false` (default) stops after planning. */
  readonly post?: boolean | undefined;
  /** Workflow-run URL rendered into the review footer. */
  readonly runUrl?: string | undefined;
}

const EMPTY_TOOLS: ReadonlyArray<Tool.Any> = [];

const requireReadonly = (tools: ReadonlyArray<Tool.Any>): void => {
  for (const tool of tools) {
    const executionClass = getToolExecutionClass(tool);
    if (executionClass !== "readonly") {
      throw new Error(
        `PrReview.make: extra tool '${tool.name}' declares execution class '${executionClass}'. ` +
          `The packaged reviewer's tool surface is read-only; annotate the tool with ` +
          `ToolExecutionClass "readonly" or run it outside the reviewer.`,
      );
    }
  }
};

const provideIgnore = <A, E, R>(
  effect: Effect.Effect<A, E, R>,
  ignore: ReadonlyArray<string> | undefined,
) =>
  ignore !== undefined && ignore.length > 0
    ? effect.pipe(Effect.provide(ignoringPullRequestSourceLayer(ignore)))
    : effect;

/**
 * The changeset fingerprint of what this reviewer WOULD review right now:
 * the ignore-filtered changeset hashed with the prompt signature. Identical
 * fingerprints mean an identical review input surface — the basis for
 * skipping re-reviews after content-free head changes (base auto-merges,
 * equivalent rebases).
 */
const makeFingerprint = (
  signature: (mission: ReturnType<typeof buildReviewMission>) => string,
  ignore: ReadonlyArray<string> | undefined,
) =>
  provideIgnore(
    Effect.gen(function* () {
      const source = yield* PullRequestSource;
      const metadata = yield* source.metadata;
      const files = yield* source.changedFiles;
      return yield* computeChangesetFingerprint(
        files,
        signature(buildReviewMission(metadata, files)),
      );
    }),
    ignore,
  );

const makeProfileFingerprint = (
  signature: (mission: ReviewMission) => string,
  ignore: ReadonlyArray<string> | undefined,
) =>
  provideIgnore(
    Effect.gen(function* () {
      const source = yield* PullRequestSource;
      const metadata = yield* source.metadata;
      const files = yield* source.anchorFiles;
      return yield* computeProfileFingerprint(signature(buildProfileMission(metadata, files)));
    }),
    ignore,
  );

const makeReviewSnapshot = (ignore: ReadonlyArray<string> | undefined) =>
  provideIgnore(
    Effect.gen(function* () {
      const source = yield* PullRequestSource;
      return {
        metadata: yield* source.metadata,
        files: yield* source.anchorFiles,
      };
    }),
    ignore,
  );

/**
 * Build the flat reviewer: one bounded read-only agent over the whole
 * changeset. Returns the model-agnostic definition, the explicit binding, and
 * a `run` whose error and requirement channels stay fully inferred — the
 * pull-request source, the publisher, extra tool handlers, and the Model
 * Layer's requirements all remain visible to the caller.
 */
const make = <
  Provider,
  ModelProvides,
  ModelRequires,
  const Extra extends ReadonlyArray<Tool.Any> = readonly [],
>(
  options: PrReviewOptions<Provider, ModelProvides, ModelRequires, Extra>,
) => {
  // Safe when `extraTools` is omitted: the generic default fixes Extra to the
  // empty tuple, which is exactly what the fallback value is.
  const extraTools = options.extraTools ?? (EMPTY_TOOLS as Extra);
  requireReadonly(extraTools);

  const definition = Agent.define("pr-reviewer", {
    input: ReviewMission,
    output: CodeReview,
    instructions: makeReviewInstructions({
      guidance: options.guidance,
      maxFindings: options.maxFindings,
    }),
    toolkit: Toolkit.make(ListChangedFiles, ReadFileDiff, ReadFile, ...extraTools),
    policy: options.policy === undefined ? defaultReviewPolicy : AgentPolicy.make(options.policy),
    description:
      "Review one pull request read-only: list the changeset, read annotated diffs and head-file context, and return a structured, line-anchored code review.",
    metadata: { deploymentClass: "E", surface: "read-only" },
  });
  // `Agent.withModel` types the model through a conditional that stays
  // deferred inside this generic body, so the binding is built structurally —
  // the identical frozen `{ definition, model }` pair the runtime accepts.
  const binding = Object.freeze({ definition, model: options.model });

  // Everything that shapes this reviewer's output: the rendered instructions
  // (mission, guidance, findings bound, contract) plus the verdict mapping.
  const signature = (mission: ReviewMission): string =>
    [
      definition.instructions(mission),
      `applyVerdict=${String(options.applyVerdict ?? false)}`,
      ...(options.modelLabel === undefined ? [] : [`model=${options.modelLabel}`]),
    ].join("\u0000");
  const profileSignature = (mission: ReviewMission): string =>
    [
      "pr-review-profile-v1-flat",
      JSON.stringify(resolveReviewGuidance(options.guidance, mission)),
      JSON.stringify(options.policy ?? {}),
      JSON.stringify(extraTools.map((tool) => tool.name)),
      JSON.stringify(options.ignore ?? []),
      `maxFindings=${clampMaxFindings(options.maxFindings)}`,
      `applyVerdict=${String(options.applyVerdict ?? false)}`,
      ...(options.modelLabel === undefined ? [] : [`model=${options.modelLabel}`]),
    ].join("\u0000");

  const run = (runOptions: RunReviewOptions = {}) =>
    provideIgnore(
      executeReview(binding, {
        post: runOptions.post ?? false,
        applyVerdict: options.applyVerdict ?? false,
        limits: options.budget ?? reviewBudgetLimits,
        maxFindings: clampMaxFindings(options.maxFindings),
        signature,
        modelLabel: options.modelLabel,
        runUrl: runOptions.runUrl,
        usageScope: "run",
        reviewShape: "flat",
      }).pipe(Effect.provide(Layer.mergeAll(ReviewToolkitLayer, IdGenerator.layer)), Effect.scoped),
      options.ignore,
    );

  return {
    definition,
    binding,
    run,
    fingerprint: makeFingerprint(signature, options.ignore),
    profileFingerprint: makeProfileFingerprint(profileSignature, options.ignore),
    snapshot: makeReviewSnapshot(options.ignore),
    filterFiles: (files: ReadonlyArray<import("./diff.ts").ChangedFile>) => {
      const ignored = compileIgnoreGlobs(options.ignore ?? []);
      return files.filter((file) => !ignored(file.path));
    },
  } as const;
};

/** Options accepted by `PrReview.makeFanOut` (the delegating reviewer). */
export interface PrReviewFanOutOptions<
  Provider,
  ModelProvides,
  ModelRequires,
> extends PrReviewSharedOptions {
  /** The Effect AI Model bound to both the coordinator and its children. */
  readonly model: Model.Model<Provider, LanguageModel.LanguageModel | ModelProvides, ModelRequires>;
  /**
   * Static guidance injected into every child reviewer's instructions. The
   * coordinator's mission never crosses the delegation boundary, so
   * mission-dependent guidance cannot exist for children.
   */
  readonly guidance?: string | ReadonlyArray<string> | undefined;
}

/**
 * Build the fan-out reviewer: a coordinator that delegates bounded per-unit
 * file reviews to attached ephemeral children and merges their findings under
 * the same output contract and the same fail-closed publication path as the
 * flat reviewer. Child and coordinator execution bounds are packaged and not
 * configurable here — the delegation reservation mirrors the child policy,
 * and letting the two drift apart is a published-API hazard.
 */
const makeFanOut = <Provider, ModelProvides, ModelRequires>(
  options: PrReviewFanOutOptions<Provider, ModelProvides, ModelRequires>,
) => {
  const suite = makeFanOutReviewSuite({
    guidance: options.guidance,
    maxFindings: options.maxFindings,
  });
  // Structural bindings for the same reason as in `make` above.
  const binding = Object.freeze({ definition: suite.parent, model: options.model });
  const childBinding = Object.freeze({ definition: suite.child, model: options.model });

  // The coordinator's rendered instructions (mission, guidance, findings
  // bound, contract) plus the review-shaping options they do not carry: the
  // child guidance, the host knobs, and the model binding descriptor.
  const guidanceLines =
    options.guidance === undefined
      ? []
      : typeof options.guidance === "string"
        ? [options.guidance]
        : options.guidance;
  const signature = (mission: ReviewMission): string =>
    [
      suite.parent.instructions(mission),
      `childGuidance=${JSON.stringify(guidanceLines)}`,
      `applyVerdict=${String(options.applyVerdict ?? false)}`,
      ...(options.modelLabel === undefined ? [] : [`model=${options.modelLabel}`]),
    ].join(" ");
  const profileSignature = (_mission: ReviewMission): string =>
    [
      "pr-review-profile-v1-fan-out",
      JSON.stringify(guidanceLines),
      JSON.stringify(options.ignore ?? []),
      `maxFindings=${clampMaxFindings(options.maxFindings)}`,
      `applyVerdict=${String(options.applyVerdict ?? false)}`,
      ...(options.modelLabel === undefined ? [] : [`model=${options.modelLabel}`]),
    ].join("\u0000");
  const delegationLayer = fanOutHandlersLayerFor(suite.delegation)(childBinding).pipe(
    Layer.provide(
      Layer.mergeAll(FileReviewToolkitLayer, SubagentReservationsMemoryLive, IdGenerator.layer),
    ),
  );

  const run = (runOptions: RunReviewOptions = {}) =>
    provideIgnore(
      executeReview(binding, {
        post: runOptions.post ?? false,
        applyVerdict: options.applyVerdict ?? false,
        limits: options.budget ?? fanOutReviewBudgetLimits,
        maxFindings: clampMaxFindings(options.maxFindings),
        signature,
        modelLabel: options.modelLabel,
        runUrl: runOptions.runUrl,
        usageScope: "coordinator",
        reviewShape: "fan-out",
      }).pipe(
        Effect.provide(
          Layer.mergeAll(FanOutCoordinatorToolkitLayer, delegationLayer, IdGenerator.layer),
        ),
        Effect.scoped,
      ),
      options.ignore,
    );

  return {
    definition: suite.parent,
    binding,
    childBinding,
    run,
    fingerprint: makeFingerprint(signature, options.ignore),
    profileFingerprint: makeProfileFingerprint(profileSignature, options.ignore),
    snapshot: makeReviewSnapshot(options.ignore),
    filterFiles: (files: ReadonlyArray<import("./diff.ts").ChangedFile>) => {
      const ignored = compileIgnoreGlobs(options.ignore ?? []);
      return files.filter((file) => !ignored(file.path));
    },
  } as const;
};

/**
 * The packaged pull-request reviewer factory.
 *
 * - `make` — one flat reviewer over the whole changeset.
 * - `makeFanOut` — a coordinator delegating bounded per-unit child reviews.
 */
export const PrReview = { make, makeFanOut } as const;

import { Effect, Layer, Ref, Schema, Stream } from "effect";
import { LanguageModel, Model, type Response } from "effect/unstable/ai";

import { FileReviewReport } from "./fan-out.ts";
import { CodeReview } from "./review-agent.ts";
import { makePromptKeyedModel, scriptedFinalParts, scriptedToolTurn } from "./scripted.ts";

// ---------------------------------------------------------------------------
// Deterministic offline models for the fan-out reviewer: prompt-keyed
// scripted models for BOTH the coordinator and the file-reviewer children.
// Both key every decision on committed history in the prompt (tool-call ids
// and briefed unit ids), never on call order, so concurrent children and
// replays stay honest.
// ---------------------------------------------------------------------------

export const OFFLINE_UNITS_CALL_ID = "units-1";

/** The delegation Tool Call id the scripted coordinator uses for one unit. */
export const offlineUnitCallId = (unitId: string): string => `delegate-${unitId}`;

/** The diff Tool Call id the scripted child uses for one unit. */
export const offlineChildDiffCallId = (unitId: string): string => `fanout-diff-${unitId}`;

/** One scripted delegation the offline coordinator declares. */
export interface OfflineUnitCall {
  readonly unitId: string;
  readonly paths: ReadonlyArray<string>;
}

/**
 * Build the offline scripted coordinator model. Turn 1 lists the review
 * units, Turn 2 declares one delegation Tool Call per scripted unit in one
 * batch, Turn 3 returns the scripted merged review JSON. Decisions key on
 * tool-call ids already committed to the prompt.
 */
export const makeOfflineFanOutCoordinatorModel = (script: {
  readonly unitCalls: ReadonlyArray<OfflineUnitCall>;
  readonly review: CodeReview;
}) => {
  const firstUnitCallId = offlineUnitCallId(script.unitCalls[0]?.unitId ?? "unit-none");
  return makePromptKeyedModel("pr-fanout-coordinator-offline", (promptJson) => {
    if (promptJson.includes(firstUnitCallId)) {
      return scriptedFinalParts(JSON.stringify(Schema.encodeSync(CodeReview)(script.review)));
    }
    if (promptJson.includes(OFFLINE_UNITS_CALL_ID)) {
      return scriptedToolTurn(
        ...script.unitCalls.map(
          (unit): Response.StreamPartEncoded => ({
            type: "tool-call",
            id: offlineUnitCallId(unit.unitId),
            name: "delegate_file_review",
            params: { unitId: unit.unitId, paths: unit.paths },
            providerExecuted: false,
          }),
        ),
      );
    }
    return scriptedToolTurn({
      type: "tool-call",
      id: OFFLINE_UNITS_CALL_ID,
      name: "list_review_units",
      params: { scope: "all" },
      providerExecuted: false,
    });
  });
};

/** How one scripted child behaves for its briefed unit. */
export type OfflineUnitOutcome =
  /** Read one diff, then return the scripted report. */
  | { readonly _tag: "findings"; readonly report: FileReviewReport }
  /** Read one diff, then return non-JSON — the child fails typed (AgentOutputError). */
  | { readonly _tag: "malformed-output" }
  /**
   * Declare more Tool Calls than the child's AgentPolicy allows in one turn —
   * none executes and the child fails typed (AgentPolicyError "tool-calls",
   * the reviewer's deliberate `onExhaustion: "fail"` pin).
   */
  | { readonly _tag: "budget-runaway"; readonly declaredCalls: number };

export interface OfflineUnitScript {
  readonly unitId: string;
  /** The one file the scripted child reads the diff of. */
  readonly diffPath: string;
  readonly outcome: OfflineUnitOutcome;
}

/**
 * Build the offline scripted file-reviewer model shared by every delegated
 * child. Each child Run builds the Model Layer inside its own scope; the
 * script entry is selected by the briefed unitId present in the child's OWN
 * prompt, and the turn is selected by whether that unit's diff Tool Call id
 * is already committed there — content-keyed on both axes, so concurrent
 * children never interfere. First-turn child prompts are recorded for
 * context-isolation assertions.
 */
export const makeOfflineFileReviewerModel = (scripts: ReadonlyArray<OfflineUnitScript>) =>
  Effect.gen(function* () {
    const calls = yield* Ref.make(0);
    const prompts = yield* Ref.make<ReadonlyArray<string>>([]);
    const decide = (promptJson: string): ReadonlyArray<Response.StreamPartEncoded> | undefined => {
      const script = scripts.find((candidate) => promptJson.includes(candidate.unitId));
      if (script === undefined) return undefined;
      switch (script.outcome._tag) {
        case "budget-runaway": {
          return scriptedToolTurn(
            ...Array.from(
              { length: script.outcome.declaredCalls },
              (_, index): Response.StreamPartEncoded => ({
                type: "tool-call",
                id: `runaway-${script.unitId}-${index + 1}`,
                name: "read_file_diff",
                params: { path: script.diffPath },
                providerExecuted: false,
              }),
            ),
          );
        }
        case "malformed-output":
        case "findings": {
          if (promptJson.includes(offlineChildDiffCallId(script.unitId))) {
            return scriptedFinalParts(
              script.outcome._tag === "findings"
                ? JSON.stringify(Schema.encodeSync(FileReviewReport)(script.outcome.report))
                : "this is not the JSON you are looking for",
            );
          }
          return scriptedToolTurn({
            type: "tool-call",
            id: offlineChildDiffCallId(script.unitId),
            name: "read_file_diff",
            params: { path: script.diffPath },
            providerExecuted: false,
          });
        }
      }
    };
    const model = Model.make(
      "scripted",
      "pr-fanout-file-reviewer-offline",
      Layer.effect(
        LanguageModel.LanguageModel,
        LanguageModel.make({
          generateText: () => Effect.succeed([]),
          streamText: (request) =>
            Stream.unwrap(
              Effect.gen(function* () {
                yield* Ref.update(calls, (value) => value + 1);
                const promptJson = JSON.stringify(request.prompt);
                yield* Ref.update(prompts, (previous) => [...previous, promptJson]);
                const parts = decide(promptJson);
                if (parts === undefined) {
                  return yield* Effect.die(
                    new Error("The child prompt names no scripted review unit"),
                  );
                }
                return Stream.fromIterable(parts);
              }),
            ),
        }),
      ),
    );
    return { model, calls: Ref.get(calls), prompts: Ref.get(prompts) };
  });

import { Effect, Schema } from "effect";
import {
  Agent,
  AgentPolicy,
  Subagent,
  SubagentPolicy,
  SubagentRuntime,
  ToolExecutionClass,
  ToolResultBounds,
  type RuntimeBinding,
} from "effect-agent";
import { Tool, Toolkit } from "effect/unstable/ai";

import { ChangedPath } from "./diff.ts";
import {
  clampMaxFindings,
  CodeReview,
  MAX_CONCERNS,
  MAX_WALKTHROUGH_SUMMARY_CHARS,
  ReadFile,
  ReadFileDiff,
  readFileDiffHandler,
  readFileHandler,
  REVIEW_TOOL_RESULT_MAX_BYTES,
  ReviewConcern,
  ReviewFinding,
  ReviewMission,
  WalkthroughEntry,
} from "./review-agent.ts";
import {
  MAX_REVIEW_UNITS,
  MAX_UNIT_FILES,
  planReviewUnits,
  ReviewUnitId,
  ReviewUnitPlan,
} from "./review-units.ts";
import { PullRequestSource, PullRequestSourceFailure } from "./source.ts";

// ---------------------------------------------------------------------------
// The fan-out reviewer: the same review contract as the flat reviewer, but
// the diff reading happens in bounded delegated children (S1 attached
// ephemeral delegation) so no single context window has to hold every diff.
// A coordinator lists the changeset as deterministic review units, delegates
// one `delegate_file_review` call per unit, then merges the children's
// bounded findings into one `CodeReview`. Publication and anchor validation
// are unchanged: child output is untrusted input like everything else and
// crosses to the host only through the same fail-closed planPublication path.
// ---------------------------------------------------------------------------

/** One child returns at most this many findings; the merge caps the total. */
export const MAX_CHILD_FINDINGS = 8;

/** One child returns at most this many non-anchored concerns. */
export const MAX_CHILD_CONCERNS = 3;

/**
 * One mandatory diff read plus one bounded context read for every path in a
 * maximum-size unit. Keep the child and delegation reservation aligned.
 */
export const MAX_FILE_REVIEW_TOOL_CALLS = MAX_UNIT_FILES * 2;

// ---------------------------------------------------------------------------
// The child: a file reviewer over one unit. Its toolkit is intentionally
// smaller than the flat reviewer's — diff and head-file reads only, no
// changeset listing — so a child can never roam beyond its briefed unit
// despite its observation surface being the whole changeset port.
// ---------------------------------------------------------------------------

export const FileReviewToolkit = Toolkit.make(ReadFileDiff, ReadFile);

export const FileReviewToolkitLayer = FileReviewToolkit.toLayer({
  read_file_diff: readFileDiffHandler,
  read_file: readFileHandler,
});

const UnitPaths = Schema.Array(ChangedPath)
  .check(Schema.isMinLength(1))
  .check(Schema.isMaxLength(MAX_UNIT_FILES));

/** The child Agent input: one briefed unit of the changeset. */
export class FileReviewBrief extends Schema.Class<FileReviewBrief>(
  "@effect-agent/pr-review/FileReviewBrief",
)({
  unitId: ReviewUnitId,
  paths: UnitPaths,
  focus: Schema.NonEmptyString.check(Schema.isMaxLength(200)),
}) {}

/** The child Agent output: the briefed unit's bounded findings and concerns. */
export class FileReviewReport extends Schema.Class<FileReviewReport>(
  "@effect-agent/pr-review/FileReviewReport",
)({
  unitId: ReviewUnitId,
  findings: Schema.Array(ReviewFinding).check(Schema.isMaxLength(MAX_CHILD_FINDINGS)),
  /** Unit-scoped concerns with no diff line to anchor to. */
  concerns: Schema.optionalKey(
    Schema.Array(ReviewConcern).check(Schema.isMaxLength(MAX_CHILD_CONCERNS)),
  ),
  /** One-sentence per-file change summaries for the merged walkthrough. */
  fileSummaries: Schema.optionalKey(
    Schema.Array(WalkthroughEntry).check(Schema.isMaxLength(MAX_UNIT_FILES)),
  ),
}) {}

/**
 * Guidance for delegated children must be static: child instructions are a
 * pure function of the brief, and the coordinator's mission never crosses the
 * delegation boundary (context isolation), so mission-dependent guidance
 * cannot be resolved for a child.
 */
export interface FanOutInstructionOptions {
  readonly guidance?: string | ReadonlyArray<string> | undefined;
}

const staticGuidanceLines = (
  guidance: string | ReadonlyArray<string> | undefined,
): ReadonlyArray<string> => {
  if (guidance === undefined) return [];
  const lines = typeof guidance === "string" ? [guidance] : guidance;
  return lines.filter((line) => line.length > 0);
};

/** Build the child file-reviewer instructions with optional static guidance. */
export const makeFileReviewerInstructions =
  (options: FanOutInstructionOptions = {}) =>
  (brief: FileReviewBrief): string =>
    [
      `You are a code reviewer for one unit of a pull request: unit ${brief.unitId}, covering exactly these changed files: ${brief.paths.join(", ")}. Focus: ${brief.focus}.`,
      ...staticGuidanceLines(options.guidance),
      "Work in this order:",
      "1. Call read_file_diff for every file in your unit. A normal diff marks new-version anchors as R<number>; only those numbers are valid startLine/endLine values. When GitHub omitted a diff, the tool may return bounded base/head content marked B/H instead. Review that content, but report its defects as non-anchored concerns because B/H lines cannot anchor GitHub comments. Never anchor a finding to a removed (-), B, or H line.",
      "2. Call read_file when you need surrounding context the diff does not show. ONLY files in the changeset are readable: a request for any other path (an import, a neighbor, a config) returns a failed result — do not retry it; reason from the diff instead and note the gap in your report when it matters.",
      "3. Review for real defects first: correctness, security, concurrency, resource leaks, error handling, API misuse. Style nits are least important. Do not praise; do not restate the diff.",
      "When the diff adds or changes a test, check that it can actually fail: a test that would still pass with the bug present is theatre, not coverage. The usual tell is a loose assertion standing where an exact one belongs — >= or a truthiness check over an expected value, or a snapshot that absorbs whatever it is handed.",
      "Drop bloat-shaped findings before reporting: defensive checks for cases that cannot happen, abstractions used once, comments restating obvious code, tests asserting tautologies, just-in-case guards. A finding must be sound, correct, and worth acting on; prefer an explicit keep over an invented finding.",
      `4. For every file in your unit, write one factual sentence (<= ${MAX_WALKTHROUGH_SUMMARY_CHARS} chars) describing what changed in that file — for a reader scanning the pull request, never a line-by-line restatement.`,
      `5. Then return ONLY a JSON object — no Markdown fences, no prose before or after — exactly this shape: {"unitId": ${JSON.stringify(brief.unitId)}, "findings": [{"path": <string, a file in your unit>, "startLine": <integer, an R-marked new-file line>, "endLine": <integer, >= startLine, same file, R-marked>, "severity": <"blocking" | "important" | "nit">, "category": <OPTIONAL: "correctness" | "security" | "concurrency" | "performance" | "resources" | "error-handling" | "testing" | "maintainability" | "style" | "docs">, "title": <string, <= 120 chars>, "body": <string, why it matters and what to do>, "suggestion": <string, OPTIONAL: replacement text for exactly lines startLine..endLine, ready to commit>}], "concerns": <array, OPTIONAL: [{"severity": <"blocking" | "important" | "nit">, "title": <string, <= 120 chars>, "body": <string>}], only for concerns about YOUR unit's files with no valid line anchor (a missing cleanup, a coverage gap the diff implies, sequencing the diff leaves open) — never duplicate a finding here>, "fileSummaries": <array, OPTIONAL: [{"path": <string, a file in your unit>, "summary": <string, the step-4 sentence>}], one entry per file in your unit>}.`,
      `Report at most ${MAX_CHILD_FINDINGS} findings and at most ${MAX_CHILD_CONCERNS} concerns; prefer the most important ones. An empty findings array is a valid report. Never report on files outside your unit. Line anchors you invent will be discarded, so copy R-numbers from read_file_diff output.`,
    ].join("\n");

export const fileReviewerInstructions = makeFileReviewerInstructions();

/** The default per-unit child execution bounds. */
export const defaultFileReviewerPolicy = AgentPolicy.make({
  maxTurns: 8,
  maxToolCalls: MAX_FILE_REVIEW_TOOL_CALLS,
  maxDuration: "6 minutes",
  toolConcurrency: 2,
  // Same rationale as the flat reviewer's bound: read refusals are
  // model-visible results, and one parallel batch of out-of-unit probes must
  // not kill the child before it has seen a single refusal.
  repeatedFailureLimit: 12,
  tokenBudget: 200_000,
  // Bound one live prompt independently from cumulative usage. The engine
  // prunes old diff/file results before paying for a summary.
  contextTokenLimit: 150_000,
  toolResultBounds: ToolResultBounds.make({ maxBytes: REVIEW_TOOL_RESULT_MAX_BYTES }),
  // Typed exhaustion, deliberately NOT the final-answer soft landing: a
  // review is a coverage claim, and a child whose reads were rejected could
  // still emit schema-valid findings — laundering budget exhaustion into
  // "reviewed". Until host-owned evidence proves every mandatory
  // read_file_diff completed, an exhausted child fails typed and its unit
  // stays honestly unreviewed (containment turns that into result data
  // without failing the run).
  onExhaustion: "fail",
});

// ---------------------------------------------------------------------------
// The delegation: one Effect AI Tool per review unit, with explicit
// projections and finite bounds (SUB-009). `projectResult` is the
// declassification boundary — the parent sees the child's bounded findings,
// never its transcript or the diffs it read.
// ---------------------------------------------------------------------------

/** The model-decoded delegation parameters: which unit to review. */
export class FileReviewRequest extends Schema.Class<FileReviewRequest>(
  "@effect-agent/pr-review/FileReviewRequest",
)({
  unitId: ReviewUnitId,
  paths: UnitPaths,
}) {}

/** The bounded parent-visible result of one delegated unit review. */
export class FileReviewUnitResult extends Schema.Class<FileReviewUnitResult>(
  "@effect-agent/pr-review/FileReviewUnitResult",
)({
  unitId: ReviewUnitId,
  findings: Schema.Array(ReviewFinding).check(Schema.isMaxLength(MAX_CHILD_FINDINGS)),
  /** Unit-scoped concerns with no diff line to anchor to. */
  concerns: Schema.optionalKey(
    Schema.Array(ReviewConcern).check(Schema.isMaxLength(MAX_CHILD_CONCERNS)),
  ),
  /** One-sentence per-file change summaries for the merged walkthrough. */
  fileSummaries: Schema.optionalKey(
    Schema.Array(WalkthroughEntry).check(Schema.isMaxLength(MAX_UNIT_FILES)),
  ),
}) {}

/**
 * One unit's review failed: the child Run ended in a typed failure (policy
 * bound, output violation, model fault). The marker is bounded and carries no
 * child transcript content beyond the failure tag and message.
 */
export class FileReviewUnitFailed extends Schema.TaggedError<FileReviewUnitFailed>()(
  "FileReviewUnitFailed",
  {
    childErrorTag: Schema.NonEmptyString.check(Schema.isMaxLength(256)),
    message: Schema.String.check(Schema.isMaxLength(400)),
  },
) {}

/**
 * Finite per-invocation bounds (SUB-009), aligned with the child's own
 * AgentPolicy: the child's policy is the limit that trips typed; the
 * reservation mirrors it so parent-side accounting stays honest.
 */
export const fileReviewPolicy = SubagentPolicy.make({
  maxChildren: MAX_REVIEW_UNITS,
  maxConcurrency: 3,
  maxTurns: 8,
  maxToolCalls: MAX_FILE_REVIEW_TOOL_CALLS,
  maxDuration: "6 minutes",
});

const delegationDescription =
  "Delegate the review of one planned unit to a bounded file-reviewer child and return its line-anchored findings. Call it exactly once per unit from list_review_units; never retry a failed unit.";

/**
 * Total mapping from every expected child Run failure to the declared unit
 * failure (SUB-028): the tag plus a bounded message, nothing else crosses.
 */
export const mapFileReviewChildFailure = (failure: {
  readonly _tag: string;
  readonly message?: string;
}): FileReviewUnitFailed =>
  FileReviewUnitFailed.make({
    childErrorTag: failure._tag,
    message: (failure.message ?? "").slice(0, 400),
  });

// ---------------------------------------------------------------------------
// The coordinator's own tool: the deterministic unit plan over the changeset.
// Grouping is host code (review-units.ts), not model prose, so fan-out shape
// and budget honesty stay pinnable in tests.
// ---------------------------------------------------------------------------

export class ListReviewUnitsQuery extends Schema.Class<ListReviewUnitsQuery>(
  "@effect-agent/pr-review/ListReviewUnitsQuery",
)({
  /** Explicit constant keeps the zero-choice operation compatible with strict provider schemas. */
  scope: Schema.Literal("all"),
}) {}

export const ListReviewUnits = Tool.make("list_review_units", {
  description:
    "List this pull request's changeset grouped into bounded review units (size-budgeted, directory-affine), plus the files no unit can cover.",
  parameters: ListReviewUnitsQuery,
  success: ReviewUnitPlan,
  failure: PullRequestSourceFailure,
  failureMode: "error",
  dependencies: [PullRequestSource],
}).annotate(ToolExecutionClass, "readonly");

export const FanOutCoordinatorToolkit = Toolkit.make(ListReviewUnits);

export const FanOutCoordinatorToolkitLayer = FanOutCoordinatorToolkit.toLayer({
  list_review_units: () =>
    Effect.gen(function* () {
      const source = yield* PullRequestSource;
      const files = yield* source.changedFiles;
      const metadata = yield* source.metadata;
      return planReviewUnits(files, { totalChangedFiles: metadata.totalChangedFiles });
    }),
});

// ---------------------------------------------------------------------------
// The coordinator Agent Definition: same mission input and CodeReview output
// contract as the flat reviewer, so planPublication and anchor validation
// apply unchanged.
// ---------------------------------------------------------------------------

/**
 * Build the coordinator's instructions. The same consumer guidance the
 * children receive is injected between the mission framing and the procedure
 * so the merged summary and verdict are shaped by the same review profile,
 * and the configured findings bound reaches the merge step instead of only
 * the host-side trim.
 */
export const makeFanOutReviewInstructions =
  (options: FanOutInstructionOptions & { readonly maxFindings?: number | undefined } = {}) =>
  (mission: ReviewMission): string => {
    const maxFindings = clampMaxFindings(options.maxFindings);
    return [
      `You coordinate the review of pull request #${mission.number} ("${mission.title}") in ${mission.repository}, merging ${mission.headRef} into ${mission.baseRef}. It changes ${mission.changedFileCount} file(s).`,
      mission.body.length > 0
        ? `Author description:\n${mission.body}`
        : "The author provided no description.",
      ...staticGuidanceLines(options.guidance),
      "Work in this order:",
      "1. Call list_review_units once to get the planned review units.",
      "2. Call delegate_file_review EXACTLY once per unit, passing each unit's unitId and paths verbatim. Prefer declaring all delegation calls in one batch. Never review files yourself and never invent units.",
      '3. A delegation result with "_tag" is a FAILED unit. Never retry it; instead your summary MUST name it honestly, e.g. "unit-002 unreviewed: AgentPolicyError". The plan\'s undiffablePaths and unassignedPaths must also be named as not reviewed when present.',
      `4. Merge the successful units' findings: drop duplicates sharing the same path and line range keeping the most severe, rank blocking > important > nit, and keep at most ${maxFindings} findings. Drop bloat-shaped findings during the merge — defensive checks for cases that cannot happen, abstractions used once, comments restating obvious code, tests asserting tautologies; children bias toward recommending changes, and a finding must be sound, correct, and worth acting on to survive.`,
      `5. Merge the units' concerns the same way: drop duplicates keeping the most severe, and keep at most ${MAX_CONCERNS}.`,
      "6. Merge the units' fileSummaries into one walkthrough: copy each entry verbatim, one entry per file, dropping duplicate paths.",
      '7. Then return ONLY a JSON object — no Markdown fences, no prose before or after — exactly this shape: {"summary": <string, 1-3 paragraphs of overall assessment, including every unreviewed unit or file>, "verdict": <"approve" | "comment" | "request-changes">, "findings": [{"path": <string>, "startLine": <integer>, "endLine": <integer>, "severity": <"blocking" | "important" | "nit">, "category": <string, OPTIONAL>, "title": <string, <= 120 chars>, "body": <string>, "suggestion": <string, OPTIONAL>}], "concerns": <array, OPTIONAL: [{"severity": <"blocking" | "important" | "nit">, "title": <string, <= 120 chars>, "body": <string>}], the merged unit concerns>, "walkthrough": <array, OPTIONAL: [{"path": <string>, "summary": <string>}], the merged fileSummaries>}. Copy findings (including "category" and "suggestion" when present), concerns, and walkthrough entries verbatim from the delegation results; never invent or edit anchors.',
      'Use verdict "request-changes" only when at least one finding or concern is "blocking". An empty findings array with verdict "approve" is a valid review when every unit succeeded and found nothing.',
    ].join("\n");
  };

export const fanOutReviewInstructions = makeFanOutReviewInstructions();

/** The default fan-out coordinator execution bounds. */
export const defaultFanOutPolicy = AgentPolicy.make({
  maxTurns: 6,
  maxToolCalls: 1 + MAX_REVIEW_UNITS,
  maxDuration: "15 minutes",
  toolConcurrency: 3,
  // Contained unit failures (SUB-033) are ordinary successful Tool results,
  // so they no longer fold into the repeated-failure counter; the default
  // bound suffices.
  repeatedFailureLimit: 3,
  tokenBudget: 300_000,
  // Child reports can amplify the merge prompt; compact before the provider's
  // 200k-class window becomes the failure boundary.
  contextTokenLimit: 150_000,
  // Budget soft landing (RUN-018): an exhausted coordinator merges what it
  // has into one best-effort review instead of discarding every child report.
  onExhaustion: "final-answer",
});

/** Everything one fan-out configuration is made of, built as one unit so the
 * delegation always targets exactly the child definition that will run. */
export interface FanOutReviewSuite {
  readonly child: ReturnType<typeof makeFileReviewerDefinition>;
  readonly parent: ReturnType<typeof makeFanOutReviewerDefinition>;
  readonly delegation: ReturnType<typeof makeFileReviewDelegation>;
}

const makeFileReviewerDefinition = (options: FanOutInstructionOptions = {}) =>
  Agent.define("pr-file-reviewer", {
    input: FileReviewBrief,
    output: FileReviewReport,
    instructions: makeFileReviewerInstructions(options),
    toolkit: FileReviewToolkit,
    policy: defaultFileReviewerPolicy,
    description:
      "Review one bounded unit of a pull request's changeset read-only and return line-anchored findings for exactly those files.",
    metadata: { deploymentClass: "E", surface: "read-only" },
  });

/** Options for one coherent fan-out suite: shared guidance plus the merge bound. */
export interface FanOutSuiteOptions extends FanOutInstructionOptions {
  readonly maxFindings?: number | undefined;
}

const makeFileReviewDelegation = (child: ReturnType<typeof makeFileReviewerDefinition>) =>
  Subagent.define("delegate_file_review", {
    description: delegationDescription,
    target: child,
    parameters: FileReviewRequest,
    success: FileReviewUnitResult,
    failure: FileReviewUnitFailed,
    // First-party containment (SUB-033): a failed unit is model-visible
    // result data instead of a parent-Run-fatal error, so the coordinator
    // reports it honestly and keeps reviewing the other units. This retires
    // the former same-name shadow-Tool workaround (FRICTION #7).
    failureMode: "return",
    prepareInput: (request) =>
      Effect.succeed(
        FileReviewBrief.make({
          unitId: request.unitId,
          paths: request.paths,
          focus: "defects-first: correctness, security, concurrency, resources, error handling",
        }),
      ),
    // The explicit declassification boundary (SUB-015): exactly the bounded
    // findings and concerns cross to the parent. Whether findings may anchor
    // anywhere is decided host-side by planPublication against the real diff.
    projectResult: (report) =>
      Effect.succeed(
        FileReviewUnitResult.make({
          unitId: report.unitId,
          findings: report.findings,
          ...(report.concerns !== undefined ? { concerns: report.concerns } : {}),
          ...(report.fileSummaries !== undefined ? { fileSummaries: report.fileSummaries } : {}),
        }),
      ),
    policy: fileReviewPolicy,
  });

/**
 * The coordinator-facing delegation Tool: the delegation's own first-party
 * contained Tool plus the read-only execution class (the delegated child's
 * whole tool surface is read-only). Effect AI resolves handlers by Tool name,
 * so `SubagentRuntime.layer`'s handler serves this annotated copy unchanged.
 */
const delegationToolFor = (delegation: ReturnType<typeof makeFileReviewDelegation>) =>
  delegation.tool.annotate(ToolExecutionClass, "readonly");

const makeFanOutReviewerDefinition = (
  options: FanOutSuiteOptions,
  delegation: ReturnType<typeof makeFileReviewDelegation>,
) =>
  Agent.define("pr-fanout-reviewer", {
    input: ReviewMission,
    output: CodeReview,
    instructions: makeFanOutReviewInstructions(options),
    toolkit: Toolkit.make(ListReviewUnits, delegationToolFor(delegation)),
    policy: defaultFanOutPolicy,
    description:
      "Coordinate one pull-request review by fanning bounded per-unit file reviews out to delegated children and merging their findings into one structured review.",
    metadata: { deploymentClass: "E", surface: "read-only", delegation: "S1-attached" },
  });

/** Build one coherent fan-out suite: child, coordinator, and delegation. */
export const makeFanOutReviewSuite = (options: FanOutSuiteOptions = {}): FanOutReviewSuite => {
  const child = makeFileReviewerDefinition({ guidance: options.guidance });
  const delegation = makeFileReviewDelegation(child);
  return {
    child,
    parent: makeFanOutReviewerDefinition(options, delegation),
    delegation,
  };
};

const defaultSuite = makeFanOutReviewSuite();

/** The default child Agent Definition. */
export const FileReviewer = defaultSuite.child;

/** The default coordinator Agent Definition. */
export const FanOutReviewer = defaultSuite.parent;

/** The default delegation over the default child. */
export const fileReviewDelegation = defaultSuite.delegation;

/** The default coordinator-facing delegation Tool (first-party contained mode). */
export const DelegateFileReview = delegationToolFor(fileReviewDelegation);

/** The default coordinator Toolkit. */
export const FanOutReviewToolkit = FanOutReviewer.toolkit;

/**
 * The contained failure family the delegation can surface as result data
 * (SUB-033), derived from the delegation itself so the coverage decoder can
 * never diverge from what the runtime actually contains.
 */
export const FileReviewDelegationFailure = fileReviewDelegation.containedFailure;

/** Runtime wiring: one delegation plus one explicit child Binding. */
export const fanOutHandlersLayerFor =
  (delegation: ReturnType<typeof makeFileReviewDelegation>) =>
  <Provider, ModelProvides, ModelRequires>(
    childBinding: RuntimeBinding<
      typeof FileReviewBrief,
      typeof FileReviewReport,
      ReturnType<typeof makeFileReviewerInstructions>,
      Toolkit.Tools<typeof FileReviewToolkit>,
      Provider,
      ModelProvides,
      ModelRequires
    >,
  ) =>
    SubagentRuntime.layer(delegation, childBinding, {
      mapChildFailure: mapFileReviewChildFailure,
    });

/** Runtime wiring over the default delegation, mirroring the leaf example. */
export const fanOutHandlersLayer = fanOutHandlersLayerFor(fileReviewDelegation);

import { Effect } from "effect";

import type { ChangedFile } from "./diff.ts";

// ---------------------------------------------------------------------------
// Changeset fingerprinting: dedupe re-reviews of an UNCHANGED effective diff.
// Repositories that auto-merge the base branch into open pull requests fire
// `synchronize` on every base update; the head SHA moves but the three-dot
// changeset the reviewer reads is byte-identical. The fingerprint hashes the
// (ignore-filtered) changeset together with a prompt signature — everything
// that shapes the review — so a rebase with no content change skips, while a
// real change, a conflict resolution, or a guidance change reviews again.
//
// The reviewer is deployment class E and owns no storage: the fingerprint is
// embedded in the posted review body as an invisible HTML comment, so the
// published review itself is the deduplication state.
// ---------------------------------------------------------------------------

const MARKER_PREFIX = "<!-- effect-agent-pr-review fingerprint=sha256:";
const MARKER_SUFFIX = " -->";
const MARKER_PATTERN = /<!-- effect-agent-pr-review fingerprint=sha256:([0-9a-f]{64}) -->/g;

/** Render the invisible review-body marker for one fingerprint. */
export const renderFingerprintMarker = (fingerprint: string): string =>
  `${MARKER_PREFIX}${fingerprint}${MARKER_SUFFIX}`;

/** The rendered marker length is fixed; publication reserves room for it. */
export const FINGERPRINT_MARKER_LENGTH = renderFingerprintMarker("0".repeat(64)).length;

/** Extract the last fingerprint marker in one review body, if any. */
export const extractFingerprint = (body: string): string | undefined => {
  let last: string | undefined;
  for (const match of body.matchAll(MARKER_PATTERN)) {
    last = match[1];
  }
  return last;
};

/** WebCrypto SHA-256; unavailable crypto is a defect, not an expected failure. */
const sha256Hex = (text: string): Effect.Effect<string> =>
  Effect.promise(async () => {
    const digest = await globalThis.crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
    return Array.from(new Uint8Array(digest))
      .map((byte) => byte.toString(16).padStart(2, "0"))
      .join("");
  });

const FIELD = "\u0000";
const RECORD = "\u0001";
const SECTION = "\u0002";

/**
 * Canonical changeset encoding: sorted by path so provider ordering never
 * matters, with every review-relevant field of every file.
 */
const canonicalChangeset = (files: ReadonlyArray<ChangedFile>): string =>
  files
    .map(
      (file) =>
        `${file.path}${FIELD}${file.status}${FIELD}${String(file.additions)}${FIELD}${String(file.deletions)}${FIELD}${file.patch ?? ""}${FIELD}${file.reviewBaseContent ?? ""}${FIELD}${file.reviewHeadContent ?? ""}`,
    )
    .sort()
    .join(RECORD);

/**
 * Fingerprint one review's complete input surface: the (already
 * ignore-filtered) changeset plus the caller's prompt signature — the
 * rendered instructions and any review-shaping options the instructions do
 * not carry.
 */
export const computeChangesetFingerprint = (
  files: ReadonlyArray<ChangedFile>,
  signature: string,
): Effect.Effect<string> => sha256Hex(`${canonicalChangeset(files)}${SECTION}${signature}`);

import { DateTime, Effect, Layer, Option, Ref, Schema } from "effect";

import { ChangedFile } from "./diff.ts";
import {
  PriorReviewLookupFailure,
  PriorReviews,
  PublishedReview,
  ReviewPublisher,
} from "./github.ts";
import type { ReviewPublicationPlan } from "./render.ts";
import type { ReviewHeadComparison, ReviewState } from "./review-state.ts";
import {
  MAX_CHANGED_FILES,
  MAX_FILE_CHARS,
  normalizeRepoRelativePath,
  PullRequestMetadata,
  PullRequestSource,
  ReviewInputViolation,
} from "./source.ts";

// ---------------------------------------------------------------------------
// Deterministic in-memory adapters for both ports: a fixture pull request
// serving the PullRequestSource, and a collecting ReviewPublisher recording
// every plan. Tests, dry runs, and live smokes run against these with no
// network and no credentials.
// ---------------------------------------------------------------------------

/** One fixture file: its changeset entry plus optional head content. */
export class FixtureFile extends Schema.Class<FixtureFile>("@effect-agent/pr-review/FixtureFile")({
  file: ChangedFile,
  baseContent: Schema.optionalKey(Schema.String.check(Schema.isMaxLength(MAX_FILE_CHARS))),
  headContent: Schema.optionalKey(Schema.String.check(Schema.isMaxLength(MAX_FILE_CHARS))),
}) {}

/** A complete in-memory pull request for tests, dry runs, and live smokes. */
export class FixturePullRequest extends Schema.Class<FixturePullRequest>(
  "@effect-agent/pr-review/FixturePullRequest",
)({
  metadata: PullRequestMetadata,
  files: Schema.Array(FixtureFile).check(Schema.isMaxLength(MAX_CHANGED_FILES)),
}) {}

const requireChanged = (
  fixture: FixturePullRequest,
  path: string,
): Effect.Effect<FixtureFile, ReviewInputViolation> => {
  const entry = fixture.files.find((candidate) => candidate.file.path === path);
  return entry === undefined
    ? Effect.fail(
        ReviewInputViolation.make({
          input: path,
          reason: "Path is not part of this pull request's changeset.",
        }),
      )
    : Effect.succeed(entry);
};

/** Deterministic `PullRequestSource` over one fixture pull request. */
export const fixturePullRequestSourceLayer = (
  fixture: FixturePullRequest,
): Layer.Layer<PullRequestSource> => {
  const files = fixture.files.map((entry) =>
    entry.file.patch !== undefined
      ? entry.file
      : ChangedFile.make({
          ...entry.file,
          ...(entry.baseContent === undefined ? {} : { reviewBaseContent: entry.baseContent }),
          ...(entry.headContent === undefined ? {} : { reviewHeadContent: entry.headContent }),
        }),
  );
  return Layer.succeed(PullRequestSource)(
    PullRequestSource.of({
      metadata: Effect.succeed(fixture.metadata),
      changedFiles: Effect.succeed(files),
      anchorFiles: Effect.succeed(files),
      readFile: (path) =>
        Effect.gen(function* () {
          const relative = yield* normalizeRepoRelativePath(path);
          const entry = yield* requireChanged(fixture, relative);
          if (entry.headContent === undefined) {
            return yield* ReviewInputViolation.make({
              input: relative,
              reason: "No head content is available for this file.",
            });
          }
          return entry.headContent;
        }),
    }),
  );
};

/** In-memory publisher: records every plan and mints a deterministic receipt. */
export const collectingReviewPublisherLayer = (
  published: Ref.Ref<ReadonlyArray<ReviewPublicationPlan>>,
): Layer.Layer<ReviewPublisher> =>
  Layer.succeed(ReviewPublisher)(
    ReviewPublisher.of({
      publish: (plan) =>
        Ref.update(published, (plans) => [...plans, plan]).pipe(
          Effect.flatMap(() => Ref.get(published)),
          Effect.map((plans) =>
            PublishedReview.make({
              reviewId: plans.length,
              url: `memory://review/${plans.length}`,
              event: plan.event,
              inlineComments: plan.comments.length,
              authorNodeId: "BOT_memory-reviewer",
              submittedAt: DateTime.makeUnsafe(
                `2026-01-01T00:00:${String(plans.length).padStart(2, "0")}Z`,
              ),
            }),
          ),
        ),
    }),
  );

/** Static `PriorReviews` service for tests: fixed history and comparisons. */
export const staticPriorReviews = (
  fingerprint: Option.Option<string>,
  options: {
    readonly state?: Option.Option<ReviewState> | undefined;
    readonly comparison?: ReviewHeadComparison | undefined;
  } = {},
): PriorReviews["Service"] =>
  PriorReviews.of({
    latestFingerprint: Effect.succeed(fingerprint),
    latestState: Effect.succeed(options.state ?? Option.none()),
    compareHeads: () =>
      options.comparison === undefined
        ? Effect.fail(PriorReviewLookupFailure.make({ reason: "no fixture comparison" }))
        : Effect.succeed(options.comparison),
  });

/** Layer form for consumers whose Effect explicitly requires `PriorReviews`. */
export const staticPriorReviewsLayer = (
  fingerprint: Option.Option<string>,
  options: {
    readonly state?: Option.Option<ReviewState> | undefined;
    readonly comparison?: ReviewHeadComparison | undefined;
  } = {},
): Layer.Layer<PriorReviews> =>
  Layer.succeed(PriorReviews)(staticPriorReviews(fingerprint, options));

import { Config, Effect, FileSystem, Layer, Option, Schema } from "effect";
import type { HttpClient } from "effect/unstable/http";

import type { PriorReviews, ReviewPublisher } from "./github.ts";
import {
  DEFAULT_GITHUB_REVIEW_AUTHOR_LOGIN,
  GitHubReviewTarget,
  gitHubPriorReviewsLayer,
  gitHubPullRequestSourceLayer,
  gitHubReviewPublisherLayer,
  gitHubReviewRetirementHostLayer,
} from "./github.ts";
import type { ReviewProgressReporter } from "./progress.ts";
import { gitHubReviewProgressLayer } from "./progress.ts";
import type { ReviewRetirementHost } from "./retirement.ts";
import type { PullRequestSource } from "./source.ts";

// ---------------------------------------------------------------------------
// GitHub Actions environment resolution: which pull request to review, from
// explicit values first and the standard Actions environment second
// (GITHUB_REPOSITORY, GITHUB_EVENT_PATH, GITHUB_API_URL, GITHUB_TOKEN).
// Platform-free: FileSystem and Config are Effect services supplied by the
// host entrypoint.
// ---------------------------------------------------------------------------

/** The pull request could not be resolved from options or the environment. */
export class ReviewTargetUnresolved extends Schema.TaggedError<ReviewTargetUnresolved>()(
  "ReviewTargetUnresolved",
  {
    reason: Schema.String,
  },
) {
  override get message() {
    return this.reason;
  }
}

/** The slice of a GitHub Actions event payload this package understands. */
export const GitHubEventWire = Schema.Struct({
  pull_request: Schema.optionalKey(
    Schema.Struct({
      number: Schema.Int,
      draft: Schema.optionalKey(Schema.Boolean),
    }),
  ),
  repository: Schema.optionalKey(Schema.Struct({ full_name: Schema.String })),
});
export type GitHubEventWire = typeof GitHubEventWire.Type;

const decodeEvent = Schema.decodeUnknownEffect(Schema.fromJsonString(GitHubEventWire));

/** Read and decode the GITHUB_EVENT_PATH payload, or none outside Actions. */
export const readGitHubEvent = Effect.fn("readGitHubEvent")(function* () {
  const eventPath = yield* Config.string("GITHUB_EVENT_PATH").pipe(Config.withDefault(""));
  if (eventPath === "") return Option.none<GitHubEventWire>();
  const fs = yield* FileSystem.FileSystem;
  const raw = yield* fs
    .readFileString(eventPath)
    .pipe(
      Effect.mapError((error) =>
        ReviewTargetUnresolved.make({ reason: `Cannot read event payload: ${error.message}` }),
      ),
    );
  const event = yield* decodeEvent(raw).pipe(
    Effect.mapError((error) =>
      ReviewTargetUnresolved.make({ reason: `Cannot decode event payload: ${error.message}` }),
    ),
  );
  return Option.some(event);
});

export interface ResolvedReviewTarget {
  readonly repository: string;
  readonly number: number;
}

/**
 * Resolve the review target: explicit values win, then GITHUB_REPOSITORY and
 * the pull_request event payload. Fails typed when no target can be named.
 */
export const resolveReviewTarget = Effect.fn("resolveReviewTarget")(function* (options: {
  readonly repository?: string | undefined;
  readonly number?: number | undefined;
}) {
  let repository = options.repository ?? "";
  if (repository === "") {
    repository = yield* Config.string("GITHUB_REPOSITORY").pipe(Config.withDefault(""));
  }
  let number = options.number;
  if (number === undefined || repository === "") {
    const event = yield* readGitHubEvent();
    if (Option.isSome(event)) {
      number ??= event.value.pull_request?.number;
      if (repository === "") repository = event.value.repository?.full_name ?? "";
    }
  }
  if (repository === "" || number === undefined) {
    return yield* ReviewTargetUnresolved.make({
      reason:
        "No pull request to review: pass an explicit repository and number, or run inside a GitHub Actions pull_request event.",
    });
  }
  return { repository, number } satisfies ResolvedReviewTarget;
});

/**
 * Build the GitHub source and publisher Layers for one resolved target,
 * reading GITHUB_API_URL, GITHUB_TOKEN, and PR_REVIEW_AUTHOR_LOGIN from
 * configuration. The returned Layer is the complete GitHub side of a review
 * run.
 */
export const gitHubReviewLayers = (
  target: ResolvedReviewTarget,
): Layer.Layer<
  | PullRequestSource
  | ReviewPublisher
  | PriorReviews
  | ReviewRetirementHost
  | ReviewProgressReporter,
  Config.ConfigError,
  HttpClient.HttpClient
> =>
  Layer.unwrap(
    Effect.gen(function* () {
      const apiUrl = yield* Config.string("GITHUB_API_URL").pipe(
        Config.withDefault("https://api.github.com"),
      );
      const graphqlUrl = yield* Config.string("GITHUB_GRAPHQL_URL").pipe(
        Config.withDefault(
          apiUrl === "https://api.github.com"
            ? "https://api.github.com/graphql"
            : apiUrl.replace(/\/api\/v3$/, "/api/graphql"),
        ),
      );
      const token = yield* Config.option(Config.redacted("GITHUB_TOKEN"));
      const reviewAuthorLogin = yield* Config.nonEmptyString("PR_REVIEW_AUTHOR_LOGIN").pipe(
        Config.withDefault(DEFAULT_GITHUB_REVIEW_AUTHOR_LOGIN),
      );
      const targetLayer = GitHubReviewTarget.layer({
        apiUrl,
        graphqlUrl,
        repository: target.repository,
        number: target.number,
        token,
        reviewAuthorLogin,
      });
      return Layer.mergeAll(
        gitHubPullRequestSourceLayer.pipe(Layer.provide(targetLayer)),
        gitHubReviewPublisherLayer.pipe(Layer.provide(targetLayer)),
        gitHubPriorReviewsLayer.pipe(Layer.provide(targetLayer)),
        gitHubReviewRetirementHostLayer.pipe(Layer.provide(targetLayer)),
        gitHubReviewProgressLayer.pipe(Layer.provide(targetLayer)),
      );
    }),
  );

