      headContent: "export const value = 2;",
    }),
  ],
});
const important = ReviewFinding.make({
  path: "src/value.ts",
  startLine: 1,
  endLine: 1,
  severity: "important",
  category: "correctness",
  title: "The exported value is still wrong",
  body: "This public constant must be 3.",
  suggestion: "export const value = 3;",
