import {
  AgentBindingResolver,
  DurableAgentRuntime,
  SubmissionLedger,
  type DurableBindingFailure,
  type DurableWorkerFailure,
  type RecoveryReport,
  type SubmissionSnapshot,
} from "@effect-agent/session";
import {
  Clock,
  Context,
  Effect,
  Layer,
  Option,
  Random,
  Ref,
  Schema,
  Semaphore,
  Stream,
} from "effect";

import { ConversationObjectIdentity, DurableObjectContext } from "./bindings.ts";
import { CloudflareDurableRuntimeConfig } from "./config.ts";

/**
 * The single multiplexed Durable Object alarm (decision D-P6-2). A Durable Object has ONE
 * alarm slot; every cadence the Node host ran on fibers (wake scan, lease expiry, settlement
 * and abort re-checks, retry backoff) multiplexes into one idempotent maintenance pass, and
 * the slot always holds the EARLIEST deadline any caller asked for.
 *
 * The alarm invariant (plan §1.4): every committed actionable mutation carries a newer durable
 * maintenance generation and a committed alarm. Stable externally-driven waits may be
 * nonterminal without retaining an alarm; their resolving mutation advances the generation and
 * restores the alarm atomically.
 */

/** The Durable Object alarm API failed; surfaces on host entry points as a typed refusal. */
export class DurableAlarmError extends Schema.TaggedError<DurableAlarmError>()(
  "DurableAlarmError",
  {
    operation: Schema.String,
    message: Schema.String,
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

const alarmFailure =
  (operation: string) =>
  (cause: unknown): DurableAlarmError =>
    DurableAlarmError.make({
      operation,
      message: cause instanceof Error ? cause.message : String(cause),
      cause,
    });

/** `ctx.storage` alarm slot as an Effect service; storage is truth, never a memory field. */
export class DurableAlarmService extends Context.Service<
  DurableAlarmService,
  {
    /** The scheduled deadline in epoch milliseconds, if any. */
    readonly scheduled: Effect.Effect<Option.Option<number>, DurableAlarmError>;
    /** Replace the slot with this deadline. */
    readonly scheduleAt: (epochMillis: number) => Effect.Effect<void, DurableAlarmError>;
    /** Keep the EARLIER of the existing deadline and this one (the multiplexing rule). */
    readonly ensureScheduledBy: (epochMillis: number) => Effect.Effect<void, DurableAlarmError>;
    /**
     * Arm an immediate alarm (the durable, coalescing local wake) — DEFERRED while a
     * maintenance pass is executing. Workerd cancels an in-flight alarm handler when a new
     * EARLIER deadline is written during its execution (`requestScheduledAlarm`), and the
     * maintenance pass runs INSIDE the alarm handler: an immediate wake landing mid-pass
     * (a routed port mutation, a sibling's `wake()`, the coordinator's own local notify)
     * would kill the running Attempt — manufacturing an ownership loss no real eviction
     * caused, and routing open uncertain-class Tool Calls into spurious Unknown Outcomes.
     * Deferral is contract-safe: wakes are droppable hints, every mutating entry point
     * pre-arms BEFORE its first durable mutation (the alarm invariant never rests on this
     * call). The pass's durable generation check observes any racing mutation, so the
     * in-memory hint does not need to be flushed after a stable wait is acknowledged.
     */
    readonly scheduleNow: Effect.Effect<void, DurableAlarmError>;
    /**
     * Run one maintenance pass with wake deferral (see `scheduleNow`). Calls made while `body`
     * executes are droppable promptness hints; correctness rests on the durable generation.
     */
    readonly withWakesDeferred: <A, E, R>(body: Effect.Effect<A, E, R>) => Effect.Effect<A, E, R>;
    /** Clear the slot; correctness-sensitive clears live in maintenance generation transactions. */
    readonly cancel: Effect.Effect<void, DurableAlarmError>;
  }
>()("@effect-agent/platform-cloudflare/DurableAlarmService") {
  static readonly layer: Layer.Layer<DurableAlarmService, never, DurableObjectContext> =
    Layer.effect(DurableAlarmService)(
      Effect.gen(function* () {
        const { ctx } = yield* DurableObjectContext;
        /**
         * In-memory pass bookkeeping — a pure CACHE, never state: a fresh incarnation has no
         * running pass, and a deferred wake lost to eviction was only ever a promptness hint
         * on top of the already-committed pre-armed alarm.
         */
        const runningPasses = yield* Ref.make(0);
        const scheduled = Effect.tryPromise({
          try: () => ctx.storage.getAlarm(),
          catch: alarmFailure("get alarm"),
        }).pipe(
          Effect.map((deadline) =>
            deadline === null ? Option.none<number>() : Option.some(deadline),
          ),
        );
        const scheduleAt = (epochMillis: number) =>
          Effect.tryPromise({
            try: () => ctx.storage.setAlarm(epochMillis),
            catch: alarmFailure("set alarm"),
          });
        const ensureScheduledBy = (epochMillis: number) =>
          scheduled.pipe(
            Effect.flatMap((existing) =>
              Option.isSome(existing) && existing.value <= epochMillis
                ? Effect.void
                : scheduleAt(epochMillis),
            ),
          );
        const armNow = Clock.currentTimeMillis.pipe(
          Effect.flatMap((now) => ensureScheduledBy(now)),
        );
        const scheduleNow = Ref.get(runningPasses).pipe(
          Effect.flatMap((passes) => (passes > 0 ? Effect.void : armNow)),
        );
        const withWakesDeferred = <A, E, R>(body: Effect.Effect<A, E, R>): Effect.Effect<A, E, R> =>
          Ref.update(runningPasses, (passes) => passes + 1).pipe(
            Effect.andThen(body),
            Effect.ensuring(Ref.update(runningPasses, (passes) => passes - 1)),
          );
        const cancel = Effect.tryPromise({
          try: () => ctx.storage.deleteAlarm(),
          catch: alarmFailure("delete alarm"),
        });
        return DurableAlarmService.of({
          scheduled,
          scheduleAt,
          ensureScheduledBy,
          scheduleNow,
          withWakesDeferred,
          cancel,
        });
      }),
    );
}

/** What one maintenance pass did — auditable evidence mirroring `NodeDurableHost`'s report. */
export class MaintenancePassReport extends Schema.Class<MaintenancePassReport>(
  "@effect-agent/platform-cloudflare/MaintenancePassReport",
)({
  /** `caught-up` is generation-only; `actionable` ran recovery and one bounded drain. */
  phase: Schema.Literals(["caught-up", "actionable"]),
  /** Recovery decisions executed (or deferred) BEFORE any new claim in this pass. */
  recovered: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  /** Settlements the drain pass finalized. */
  settled: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  /** Submissions still nonterminal after the pass (suspended/unknown lanes stay honest). */
  nonterminal: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  /** `rearmed` for dirty/autonomous work, `cleared` for stable waits or settlement. */
  alarm: Schema.Literals(["rearmed", "cleared"]),
}) {}

/** Fault boundaries around every maintenance-owned durable mutation. */
export type ConversationMaintenanceFailpointLocation =
  | "maintenance:dirty:before"
  | "maintenance:dirty:after"
  | "maintenance:mutation:armed"
  | "maintenance:mutation:finished"
  | "maintenance:ensure:before"
  | "maintenance:ensure:after"
  | "maintenance:begin:before"
  | "maintenance:begin:after"
  | "maintenance:finish:before"
  | "maintenance:finish:after";

export type ConversationMaintenanceFailpointHandler = (
  location: ConversationMaintenanceFailpointLocation,
) => Effect.Effect<void>;

/** Test-only fault authority; production uses the inert layer. */
export class ConversationMaintenanceFailpoint extends Context.Service<
  ConversationMaintenanceFailpoint,
  {
    readonly hit: ConversationMaintenanceFailpointHandler;
  }
>()("@effect-agent/platform-cloudflare/ConversationMaintenanceFailpoint") {
  static readonly layer = Layer.succeed(this)({ hit: () => Effect.void });
}

const MaintenanceGeneration = Schema.BigIntFromString.check(
  Schema.isGreaterThanOrEqualToBigInt(0n),
);

/** Versioned, platform-private maintenance state stored through Durable Object KV. */
class ConversationMaintenanceState extends Schema.Class<ConversationMaintenanceState>(
  "@effect-agent/platform-cloudflare/ConversationMaintenanceState",
)({
  schemaVersion: Schema.Literal(1),
  dirty: MaintenanceGeneration,
  processed: MaintenanceGeneration,
  nonterminal: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
}) {}

const MAINTENANCE_STATE_KEY = "effect-agent:conversation-maintenance:v1";
const decodeMaintenanceState = Schema.decodeUnknownSync(ConversationMaintenanceState);
const encodeMaintenanceState = Schema.encodeSync(ConversationMaintenanceState);

const initialMaintenanceState = (): ConversationMaintenanceState =>
  ConversationMaintenanceState.make({
    schemaVersion: 1,
    // Bootstrap Objects created by the pre-generation release without scanning the ledger in
    // the constructor. One useful pass classifies and acknowledges any existing obligation.
    dirty: 1n,
    processed: 0n,
    nonterminal: 0,
  });

const readMaintenanceState = async (
  transaction: DurableObjectTransaction,
): Promise<{ readonly state: ConversationMaintenanceState; readonly initialized: boolean }> => {
  const encoded = await transaction.get(MAINTENANCE_STATE_KEY);
  return encoded === undefined
    ? { state: initialMaintenanceState(), initialized: false }
    : { state: decodeMaintenanceState(encoded), initialized: true };
};

const ensureTransactionAlarmBy = async (
  transaction: DurableObjectTransaction,
  deadline: number,
): Promise<void> => {
  const scheduled = await transaction.getAlarm();
  if (scheduled === null || scheduled > deadline) {
    await transaction.setAlarm(deadline);
  }
};

const stableExternalWait = (
  snapshot: SubmissionSnapshot,
  reports: ReadonlyMap<string, RecoveryReport>,
): boolean => {
  switch (snapshot.state) {
    case "suspended":
    case "unknown":
    case "joined":
      return true;
    case "admitted":
      return reports.get(snapshot.submissionId)?.decision._tag === "AwaitParentEstablishment";
    case "input-applied":
    case "joining":
    case "ready":
    case "running":
    case "settled":
    case "terminalizing":
      return false;
  }
};

export type MaintenancePassFailure =
  | DurableWorkerFailure
  | DurableBindingFailure
  | DurableAlarmError;

/**
 * Incremental, quiescent maintenance over a durable dirty/processed generation (issue #93).
 *
 * `pass` = generation snapshot/pre-arm → recovery → bounded drain → generation acknowledgement:
 *
 * 1. One storage transaction reads dirty/processed and re-arms before work. A caught-up forced
 *    alarm takes an O(1) path without recovery, ledger scans, or canonical-history reads.
 * 2. Recovery still strictly precedes a new claim, and one bounded drain advances the lane.
 * 3. The final transaction acknowledges only the generation observed at pass start. A racing
 *    mutation therefore remains `dirty > processed` and retains its atomically-established alarm.
 * 4. Stable external waits acknowledge and clear. Autonomous retry, indeterminate, and lease
 *    recovery states leave their generation dirty and retain bounded backoff rearming.
 */
export class ConversationMaintenance extends Context.Service<
  ConversationMaintenance,
  {
    /** One idempotent maintenance pass; failures propagate so workerd retries the alarm. */
    readonly pass: Effect.Effect<MaintenancePassReport, MaintenancePassFailure>;
    /**
     * Constructor gate: initialize/inspect only the O(1) maintenance record and ensure a dirty
     * generation has an alarm. It never scans the ledger or canonical history.
     */
    readonly ensureAlarm: Effect.Effect<void, MaintenancePassFailure>;
    /**
     * Serialize the pre-arm boundary with pass acknowledgement, advance the durable dirty
     * generation and arm the alarm in one transaction BEFORE running the caller's mutation.
     * A pass cannot acknowledge while that mutation remains in flight.
     */
    readonly withMutation: <A, E, R>(
      body: Effect.Effect<A, E, R>,
    ) => Effect.Effect<A, E | DurableAlarmError, R>;
  }
>()("@effect-agent/platform-cloudflare/ConversationMaintenance") {
  static readonly layer: Layer.Layer<
    ConversationMaintenance,
    never,
    | DurableAgentRuntime
    | AgentBindingResolver
    | SubmissionLedger
    | DurableAlarmService
    | ConversationMaintenanceFailpoint
    | CloudflareDurableRuntimeConfig
    | ConversationObjectIdentity
    | DurableObjectContext
  > = Layer.effect(ConversationMaintenance)(
    Effect.gen(function* () {
      const runtime = yield* DurableAgentRuntime;
      const resolver = yield* AgentBindingResolver;
      const ledger = yield* SubmissionLedger;
      const alarm = yield* DurableAlarmService;
      const config = yield* CloudflareDurableRuntimeConfig;
      const identity = yield* ConversationObjectIdentity;
      const { ctx } = yield* DurableObjectContext;
      const failpoint = yield* ConversationMaintenanceFailpoint;

      /**
       * Consecutive no-progress passes — an in-memory CACHE, not state: a fresh incarnation
       * restarts at zero and merely re-arms sooner than a long-lived one would have.
       */
      const stalls = yield* Ref.make(0);
      /**
       * Incarnation-local mutation count guarded with the generation transactions below. It is
       * deliberately not durable: after eviction every begun mutation has stopped, while its
       * pre-armed dirty generation remains durable for recovery. The short gate never spans the
       * caller's mutation or cross-Object I/O.
       */
      const activeMutations = yield* Ref.make(0);
      const generationGate = yield* Semaphore.make(1);
      // At-least-once deliveries are idempotent, but overlapping pass bodies could otherwise
      // acknowledge state while a sibling pass is still mutating it. Port/RPC mutations do not
      // take this permit, so cross-Object I/O cannot deadlock the maintenance serialization.
      const maintenancePassGate = yield* Semaphore.make(1);
      const minimumAlarmDelay = Math.max(1, Math.ceil(config.alarmBackoffBase / 2));

      const runTransaction = <A>(
        operation: string,
        transaction: () => Promise<A>,
      ): Effect.Effect<A, DurableAlarmError> =>
        Effect.tryPromise({
          try: transaction,
          catch: alarmFailure(operation),
        });

      const beginMutation = Effect.fn("ConversationMaintenance.beginMutation")(function* () {
        yield* failpoint.hit("maintenance:dirty:before");
        const now = yield* Clock.currentTimeMillis;
        yield* runTransaction("advance maintenance generation", () =>
          ctx.storage.transaction(async (transaction) => {
            const { state } = await readMaintenanceState(transaction);
            const next = ConversationMaintenanceState.make({
              ...state,
              dirty: state.dirty + 1n,
            });
            await transaction.put(MAINTENANCE_STATE_KEY, encodeMaintenanceState(next));
            // The earliest configured retry bounds a newly actionable mutation without relying
            // on its best-effort immediate wake hint.
            await ensureTransactionAlarmBy(transaction, now + minimumAlarmDelay);
          }),
        );
        yield* failpoint.hit("maintenance:dirty:after");
        yield* Ref.update(activeMutations, (active) => active + 1);
      });

      const endMutation = generationGate.withPermit(
        Ref.update(activeMutations, (active) => Math.max(0, active - 1)),
      );

      const withMutation = <A, E, R>(
        body: Effect.Effect<A, E, R>,
      ): Effect.Effect<A, E | DurableAlarmError, R> =>
        Effect.acquireUseRelease(
          generationGate.withPermit(beginMutation()),
          () =>
            failpoint.hit("maintenance:mutation:armed").pipe(
              Effect.andThen(body),
              Effect.tap(() => failpoint.hit("maintenance:mutation:finished")),
            ),
          () => endMutation,
        );

      const ensureAlarm = Effect.fn("ConversationMaintenance.ensureAlarm")(function* () {
        yield* failpoint.hit("maintenance:ensure:before");
        const now = yield* Clock.currentTimeMillis;
        yield* runTransaction("ensure maintenance alarm", () =>
          ctx.storage.transaction(async (transaction) => {
            const { state, initialized } = await readMaintenanceState(transaction);
            if (!initialized) {
              await transaction.put(MAINTENANCE_STATE_KEY, encodeMaintenanceState(state));
            }
            if (state.dirty > state.processed) {
              await ensureTransactionAlarmBy(transaction, now + config.wakeScanInterval);
            }
          }),
        );
        yield* failpoint.hit("maintenance:ensure:after");
      });

      const beginPass = Effect.fn("ConversationMaintenance.beginPass")(function* () {
        yield* failpoint.hit("maintenance:begin:before");
        const now = yield* Clock.currentTimeMillis;
        const result = yield* runTransaction("begin maintenance pass", () =>
          ctx.storage.transaction(async (transaction) => {
            const { state, initialized } = await readMaintenanceState(transaction);
            if (!initialized) {
              await transaction.put(MAINTENANCE_STATE_KEY, encodeMaintenanceState(state));
            }
            if (state.processed >= state.dirty) {
              await transaction.deleteAlarm();
              return { _tag: "CaughtUp" as const, nonterminal: state.nonterminal };
            }
            // Pre-arm the earliest retry before recovery. A successful finish may move this slot
            // LATER to its bounded backoff, which does not cancel the running handler.
            await ensureTransactionAlarmBy(transaction, now + minimumAlarmDelay);
            return { _tag: "Actionable" as const, generation: state.dirty };
          }),
        );
        yield* failpoint.hit("maintenance:begin:after");
        return result;
      });

      const rearmDelay = Effect.fn("ConversationMaintenance.rearmDelay")(function* (
        progressed: boolean,
      ) {
        const priorStalls = yield* Ref.getAndUpdate(stalls, (count) =>
          progressed ? 0 : count + 1,
        );
        if (progressed) return config.alarmBackoffBase;
        const exponent = Math.min(priorStalls, 30);
        const backoff = Math.min(config.alarmBackoffCap, config.alarmBackoffBase * 2 ** exponent);
        const jitter = yield* Random.next;
        // Full jitter over [backoff/2, backoff]: desynchronizes retry storms without ever
        // waiting longer than the deterministic bound.
        const jittered = Math.ceil(backoff / 2 + (backoff / 2) * jitter);
        return Math.min(jittered, config.wakeScanInterval);
      });

      const pass = Effect.fn("ConversationMaintenance.pass")(function* (): Effect.fn.Return<
        MaintenancePassReport,
        MaintenancePassFailure
      > {
        const annotate = (report: MaintenancePassReport) =>
          Effect.annotateCurrentSpan({
            phase: report.phase,
            recovered: report.recovered,
            settled: report.settled,
            nonterminal: report.nonterminal,
            alarm: report.alarm,
          }).pipe(Effect.as(report));

        const started = yield* generationGate.withPermit(
          Effect.gen(function* () {
            const activeAtStart = yield* Ref.get(activeMutations);
            const generation = yield* beginPass();
            return { ...generation, activeAtStart };
          }),
        );
        if (started._tag === "CaughtUp") {
          return yield* annotate(
            MaintenancePassReport.make({
              phase: "caught-up",
              recovered: 0,
              settled: 0,
              nonterminal: started.nonterminal,
              alarm: "cleared",
            }),
          );
        }
        // Step 2 — reconciliation strictly precedes new work in this pass (exit gate).
        const recovered: ReadonlyArray<RecoveryReport> = yield* runtime.runRecovery;
        // Step 3 — one bounded drain pass over this Object's own lane.
        const settlements = yield* runtime
          .processConversationResolved(identity.conversationId)
          .pipe(Effect.provideService(AgentBindingResolver, resolver));
        // Observe residual state before acknowledging this exact pass-start generation.
        const remaining = yield* Stream.runCollect(ledger.scanNonterminal);
        const reports = new Map(recovered.map((report) => [report.submissionId, report]));
        const autonomous = remaining.some((snapshot) => !stableExternalWait(snapshot, reports));
        const progressed =
          settlements.length > 0 || recovered.some((report) => report.disposition === "repaired");
        const delay = autonomous ? yield* rearmDelay(progressed) : 0;
        const now = yield* Clock.currentTimeMillis;
        yield* failpoint.hit("maintenance:finish:before");
        const alarmDisposition = yield* generationGate.withPermit(
          Effect.gen(function* () {
            const active = yield* Ref.get(activeMutations);
            return yield* runTransaction("finish maintenance pass", () =>
              ctx.storage.transaction(async (transaction) => {
                const { state } = await readMaintenanceState(transaction);
                // Autonomous work and in-flight mutations intentionally leave the observed
                // generation dirty. Otherwise acknowledge only the pass-start generation.
                const processed =
                  autonomous || started.activeAtStart > 0 || active > 0
                    ? state.processed
                    : state.processed > started.generation
                      ? state.processed
                      : started.generation;
                const next = ConversationMaintenanceState.make({
                  ...state,
                  processed,
                  nonterminal: remaining.length,
                });
                await transaction.put(MAINTENANCE_STATE_KEY, encodeMaintenanceState(next));
                if (autonomous) {
                  // Replace the crash-fallback slot with this pass's bounded backoff. The target
                  // is never earlier than the begin-pass fallback, so workerd does not cancel
                  // this running alarm handler before its report/span can complete.
                  await transaction.setAlarm(now + delay);
                  return "rearmed" as const;
                }
                if (started.activeAtStart > 0 || active > 0 || next.dirty > next.processed) {
                  // A mutation overlapped this pass's observation window or raced
                  // acknowledgement. It stays dirty and its pre-armed bounded alarm survives;
                  // unseen effects are never acknowledged. Do not accelerate that future alarm
                  // from inside the current handler: workerd cancels a running handler when it
                  // writes an earlier slot.
                  await ensureTransactionAlarmBy(transaction, now + config.wakeScanInterval);
                  return "rearmed" as const;
                }
                await transaction.deleteAlarm();
                return "cleared" as const;
              }),
            );
          }),
        );
        yield* failpoint.hit("maintenance:finish:after");
        if (alarmDisposition === "cleared") {
          yield* Ref.set(stalls, 0);
        }
        return yield* annotate(
          MaintenancePassReport.make({
            phase: "actionable",
            recovered: recovered.length,
            settled: settlements.length,
            nonterminal: remaining.length,
            alarm: alarmDisposition,
          }),
        );
      });

      return ConversationMaintenance.of({
        // A mid-pass immediate hint is droppable; durable dirty state decides the final alarm.
        pass: alarm.withWakesDeferred(maintenancePassGate.withPermit(pass())),
        ensureAlarm: ensureAlarm(),
        withMutation,
      });
    }),
  );
}

import type { ConversationId } from "@effect-agent/core";
import type { ProducerId } from "@effect-agent/session";
import { Context, Effect, Layer, Schema } from "effect";

/**
 * Cloudflare platform bindings as Effect services (DEPLOY-010: "Cloudflare platform bindings
 * are supplied as Effect services/Layers"). Application code never reads `env` or touches a
 * `DurableObjectState` directly — the Conversation Object class constructs these Layers once
 * per incarnation and everything downstream consumes the services.
 */

/** A Cloudflare platform binding was missing or carried the wrong shape (DEPLOY-003/010). */
export class CloudflareBindingError extends Schema.TaggedError<CloudflareBindingError>()(
  "CloudflareBindingError",
  {
    binding: Schema.String,
    message: Schema.String,
  },
) {}

/**
 * The RPC surface one Conversation Durable Object exposes to Workers and to sibling
 * Conversation Objects. `makeConversationObjectClass` implements it; the Worker-side client
 * and the cross-Object transport call it through `DurableObjectNamespace` stubs. Every
 * `encoded` value is a Schema-encoded envelope (`client.ts` wire schemas for host entry
 * points, `@effect-agent/storage-cloudflare` port envelopes for `portCall`), so the RPC
 * boundary carries only structured-cloneable JSON.
 */
export interface ConversationObjectRpc extends Rpc.DurableObjectBranded {
  /** Admission-limits gate + `DurableAgentRuntime.submit`; answers a `SubmitResponse`. */
  submitEncoded(encoded: unknown): Promise<unknown>;
  /** Wake-hinted, poll-guaranteed settlement wait; answers an `AwaitSettlementResponse`. */
  awaitSettlementEncoded(encoded: unknown): Promise<unknown>;
  /** One bounded page of canonical records; answers an `ObservePageResponse`. */
  observePage(encoded: unknown): Promise<unknown>;
  /** Durable abort intent; answers an `AbortResponse`. */
  abortEncoded(encoded: unknown): Promise<unknown>;
  /** Durable approval decision (plan §2.6); answers a `ResolveApprovalResponse`. */
  resolveApprovalEncoded(encoded: unknown): Promise<unknown>;
  /** Authorized DUR-017 Unknown-Outcome resolution; answers a `ResolveUnknownResponse`. */
  resolveUnknownEncoded(encoded: unknown): Promise<unknown>;
  /** Owner-side cross-Object port endpoint (WP2 envelopes, executed on LOCAL facets). */
  portCall(encoded: unknown): Promise<unknown>;
  /** Droppable liveness hint from another Object: arms an immediate alarm. */
  wake(): Promise<void>;
}

/**
 * The `DurableObjectNamespace` binding that addresses Conversation Objects. The Object
 * identity rule is `namespace.idFromName(conversationId)` (plan §1.2): Conversation IDs are
 * globally unique, so the mapping is total and deterministic and no directory service exists.
 */
export class ConversationObjectNamespace extends Context.Service<
  ConversationObjectNamespace,
  {
    readonly namespace: DurableObjectNamespace<ConversationObjectRpc>;
  }
>()("@effect-agent/platform-cloudflare/ConversationObjectNamespace") {
  static layer(
    namespace: DurableObjectNamespace<ConversationObjectRpc>,
  ): Layer.Layer<ConversationObjectNamespace> {
    return Layer.succeed(ConversationObjectNamespace)({ namespace });
  }
}

/**
 * Narrow one `env` member to a `DurableObjectNamespace`. `env` is an untyped platform value,
 * and a namespace binding is a host object no Schema can decode, so this is the documented
 * narrowest-boundary check (structural probe for the namespace surface the transport uses);
 * a missing or misshaped binding fails typed before any Layer is built.
 */
export const conversationNamespaceFromEnv = (
  env: unknown,
  binding: string,
): Effect.Effect<DurableObjectNamespace<ConversationObjectRpc>, CloudflareBindingError> =>
  Effect.suspend(() => {
    if (typeof env !== "object" || env === null) {
      return Effect.fail(
        CloudflareBindingError.make({
          binding,
          message: "The Worker environment is not an object; no bindings are available.",
        }),
      );
    }
    const candidate: unknown = (env as Record<string, unknown>)[binding];
    if (
      typeof candidate === "object" &&
      candidate !== null &&
      "idFromName" in candidate &&
      typeof candidate.idFromName === "function" &&
      "get" in candidate &&
      typeof candidate.get === "function"
    ) {
      // The structural probe above is the entire runtime contract this package relies on;
      // the assertion records that `idFromName`/`get` name a DurableObjectNamespace.
      return Effect.succeed(candidate as DurableObjectNamespace<ConversationObjectRpc>);
    }
    return Effect.fail(
      CloudflareBindingError.make({
        binding,
        message:
          `env.${binding} is not a DurableObjectNamespace binding; declare the Conversation ` +
          "Object class under this binding in the Worker configuration.",
      }),
    );
  });

/** `ConversationObjectNamespace` built from the untyped Worker `env` (fails typed). */
export const conversationNamespaceLayer = (
  env: unknown,
  binding: string,
): Layer.Layer<ConversationObjectNamespace, CloudflareBindingError> =>
  Layer.effect(ConversationObjectNamespace)(
    Effect.map(conversationNamespaceFromEnv(env, binding), (namespace) => ({ namespace })),
  );

/**
 * The live Durable Object execution context of THIS incarnation. Only Layer construction and
 * the alarm service consume it; important state never lives on it (`ctx.storage` is truth,
 * everything in memory is a cache — deployment spec §11).
 */
export class DurableObjectContext extends Context.Service<
  DurableObjectContext,
  {
    readonly ctx: DurableObjectState;
    readonly env: unknown;
  }
>()("@effect-agent/platform-cloudflare/DurableObjectContext") {
  static layer(ctx: DurableObjectState, env: unknown): Layer.Layer<DurableObjectContext> {
    return Layer.succeed(DurableObjectContext)({ ctx, env });
  }
}

/**
 * The Conversation identity this Object serializes and the producer identity its Attempts
 * write with (`{producerPrefix}:{conversationId}`, plan §1.4). Derived once per incarnation
 * from `ctx.id.name` — the Object identity rule guarantees the name IS the Conversation ID.
 */
export class ConversationObjectIdentity extends Context.Service<
  ConversationObjectIdentity,
  {
    readonly conversationId: ConversationId;
    readonly producerId: ProducerId;
  }
>()("@effect-agent/platform-cloudflare/ConversationObjectIdentity") {}

import { AgentId, AgentInputError, type ConversationId } from "@effect-agent/core";
import {
  AbortCommand,
  AbortIntent,
  AdmissionConflict,
  AppendConflict,
  ApprovalConflict,
  ApprovalDecisionCommand,
  ApprovalDecisionIntent,
  CanonicalRecordEnvelope,
  CanonicalSequence,
  ConversationNotMaterialized,
  ConversationStoreError,
  DefinitionDigests,
  DigestError,
  DurableRuntimeFailpointError,
  FenceRejected,
  IdempotencyKey,
  JoinedToHost,
  LedgerError,
  PersistedJson,
  Principal,
  Receipt,
  Settlement,
  SettlementConflict,
  UnknownResolutionCommand,
  UnknownResolutionConflict,
  UnknownResolutionIntent,
  type DurableSubmitAgent,
  type DurableSubmitOptions,
} from "@effect-agent/session";
import { Context, Effect, Layer, Schema } from "effect";

import { DurableAlarmError } from "./alarm.ts";
import { ConversationObjectNamespace, type ConversationObjectRpc } from "./bindings.ts";
import { AdmissionLimitExceeded } from "./config.ts";

/**
 * The Worker↔Conversation-Object host protocol (plan §1.4): Schema envelopes for the host
 * entry points (`submitEncoded`, `awaitSettlementEncoded`, `observePage`, `abortEncoded`,
 * `resolveApprovalEncoded`, `resolveUnknownEncoded`) plus the Worker-side client that speaks
 * it. Mirrors the WP2 port protocol: requests and responses are closed Schema unions, typed
 * failures travel as their own tagged classes and RE-DECODE to identical tags on the caller
 * (error-tag fidelity), and protocol anomalies are answered typed instead of thrown.
 */

/** Ceiling for host protocol diagnostic strings. */
const MAX_HOST_DIAGNOSTIC_LENGTH = 4_096;

const BoundedDiagnostic = Schema.String.check(Schema.isMaxLength(MAX_HOST_DIAGNOSTIC_LENGTH));

/** Truncate a diagnostic string to the host protocol's bounded length. */
export const boundHostDiagnostic = (value: string): string =>
  value.length > MAX_HOST_DIAGNOSTIC_LENGTH
    ? `${value.slice(0, MAX_HOST_DIAGNOSTIC_LENGTH - 3)}...`
    : value;

/**
 * The envelope itself could not be honored: the Object could not decode the request, or a
 * response could not be encoded/decoded. Never carries operation semantics.
 */
export class HostProtocolError extends Schema.TaggedError<HostProtocolError>()(
  "HostProtocolError",
  {
    message: BoundedDiagnostic,
  },
) {}

/** The Worker-side stub call itself failed (RPC rejection, overload, eviction mid-call). */
export class ConversationClientError extends Schema.TaggedError<ConversationClientError>()(
  "ConversationClientError",
  {
    conversationId: Schema.String,
    message: Schema.String,
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

// ---------------------------------------------------------------------------
// Requests
// ---------------------------------------------------------------------------

/**
 * One durable submission, input ALREADY encoded by the caller through the Agent Binding's
 * input schema (the Worker bundles the same Agent definitions as the Object, so schema
 * validation happens client-side; the resolved Binding re-validates at claim time). The
 * Conversation identity is deliberately absent — the addressed Object IS the lane.
 */
export class SubmitRequest extends Schema.Class<SubmitRequest>(
  "@effect-agent/platform-cloudflare/SubmitRequest",
)({
  agentId: AgentId,
  principal: Principal,
  idempotencyKey: IdempotencyKey,
  definitions: DefinitionDigests,
  inputPayload: PersistedJson,
}) {}

/** One bounded page of canonical records after an optional sequence. */
export class ObservePageRequest extends Schema.Class<ObservePageRequest>(
  "@effect-agent/platform-cloudflare/ObservePageRequest",
)({
  afterSequence: Schema.optionalKey(CanonicalSequence),
  limit: Schema.Int.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(1_024)),
}) {}

// ---------------------------------------------------------------------------
// Responses
// ---------------------------------------------------------------------------

/**
 * Every typed failure a host entry point can produce, plus the protocol's own errors. Same
 * closed-union discipline as the WP2 `PortFailure`: members re-decode to the SAME tagged
 * classes on the Worker side; `cause` chains travel as Schema defects without instance
 * fidelity (plan §2.8).
 */
export const HostFailure = Schema.Union([
  AgentInputError,
  DigestError,
  AdmissionConflict,
  SettlementConflict,
  ApprovalConflict,
  UnknownResolutionConflict,
  JoinedToHost,
  LedgerError,
  ConversationStoreError,
  ConversationNotMaterialized,
  AppendConflict,
  FenceRejected,
  DurableRuntimeFailpointError,
  AdmissionLimitExceeded,
  DurableAlarmError,
  HostProtocolError,
]);
export type HostFailure = typeof HostFailure.Type;

export class SubmitSucceeded extends Schema.TaggedClass<SubmitSucceeded>(
  "@effect-agent/platform-cloudflare/SubmitSucceeded",
)("SubmitSucceeded", {
  receipt: Receipt,
}) {}

export class SettlementReached extends Schema.TaggedClass<SettlementReached>(
  "@effect-agent/platform-cloudflare/SettlementReached",
)("SettlementReached", {
  settlement: Settlement,
}) {}

export class ObservedPage extends Schema.TaggedClass<ObservedPage>(
  "@effect-agent/platform-cloudflare/ObservedPage",
)("ObservedPage", {
  records: Schema.Array(CanonicalRecordEnvelope).check(Schema.isMaxLength(1_024)),
}) {}

export class AbortRecorded extends Schema.TaggedClass<AbortRecorded>(
  "@effect-agent/platform-cloudflare/AbortRecorded",
)("AbortRecorded", {
  intent: AbortIntent,
}) {}

export class ApprovalRecorded extends Schema.TaggedClass<ApprovalRecorded>(
  "@effect-agent/platform-cloudflare/ApprovalRecorded",
)("ApprovalRecorded", {
  intent: ApprovalDecisionIntent,
}) {}

export class UnknownResolutionRecorded extends Schema.TaggedClass<UnknownResolutionRecorded>(
  "@effect-agent/platform-cloudflare/UnknownResolutionRecorded",
)("UnknownResolutionRecorded", {
  intent: UnknownResolutionIntent,
}) {}

/** The entry point failed TYPED on the Object; the failure re-decodes verbatim. */
export class HostFailed extends Schema.TaggedClass<HostFailed>(
  "@effect-agent/platform-cloudflare/HostFailed",
)("HostFailed", {
  failure: HostFailure,
}) {}

/** The uniform answer of one host entry point. Callers narrow by the tag their call implies. */
export const HostResponse = Schema.Union([
  SubmitSucceeded,
  SettlementReached,
  ObservedPage,
  AbortRecorded,
  ApprovalRecorded,
  UnknownResolutionRecorded,
  HostFailed,
]);
export type HostResponse = typeof HostResponse.Type;

// ---------------------------------------------------------------------------
// Codecs (shared by the Object endpoints and the Worker client)
// ---------------------------------------------------------------------------

export const decodeSubmitRequest = Schema.decodeUnknownEffect(SubmitRequest);
export const encodeSubmitRequest = Schema.encodeEffect(SubmitRequest);
export const decodeReceipt = Schema.decodeUnknownEffect(Receipt);
export const encodeReceipt = Schema.encodeEffect(Receipt);
export const decodeObservePageRequest = Schema.decodeUnknownEffect(ObservePageRequest);
export const encodeObservePageRequest = Schema.encodeEffect(ObservePageRequest);
export const decodeAbortCommand = Schema.decodeUnknownEffect(AbortCommand);
export const encodeAbortCommand = Schema.encodeEffect(AbortCommand);
export const decodeApprovalDecisionCommand = Schema.decodeUnknownEffect(ApprovalDecisionCommand);
export const encodeApprovalDecisionCommand = Schema.encodeEffect(ApprovalDecisionCommand);
export const decodeUnknownResolutionCommand = Schema.decodeUnknownEffect(UnknownResolutionCommand);
export const encodeUnknownResolutionCommand = Schema.encodeEffect(UnknownResolutionCommand);
export const encodeHostResponse = Schema.encodeEffect(HostResponse);
export const decodeHostResponse = Schema.decodeUnknownEffect(HostResponse);

// ---------------------------------------------------------------------------
// Worker-side client
// ---------------------------------------------------------------------------

/** Failure surface of `CloudflareConversationClient.submit`. */
export type ClientSubmitFailure =
  | AgentInputError
  | DigestError
  | AdmissionConflict
  | LedgerError
  | ConversationStoreError
  | ConversationNotMaterialized
  | AppendConflict
  | FenceRejected
  | DurableRuntimeFailpointError
  | AdmissionLimitExceeded
  | DurableAlarmError
  | HostProtocolError
  | ConversationClientError;

export type ClientAwaitFailure =
  | LedgerError
  | SettlementConflict
  | HostProtocolError
  | ConversationClientError;

export type ClientObserveFailure =
  | ConversationStoreError
  | ConversationNotMaterialized
  | HostProtocolError
  | ConversationClientError;

export type ClientAbortFailure =
  | LedgerError
  | SettlementConflict
  | JoinedToHost
  | DurableRuntimeFailpointError
  | DurableAlarmError
  | HostProtocolError
  | ConversationClientError;

export type ClientApprovalFailure =
  | LedgerError
  | SettlementConflict
  | ApprovalConflict
  | DurableAlarmError
  | HostProtocolError
  | ConversationClientError;

export type ClientUnknownFailure =
  | LedgerError
  | SettlementConflict
  | UnknownResolutionConflict
  | JoinedToHost
  | DurableRuntimeFailpointError
  | DurableAlarmError
  | HostProtocolError
  | ConversationClientError;

const SUBMIT_FAILURE_TAGS: ReadonlySet<string> = new Set([
  "AgentInputError",
  "DigestError",
  "AdmissionConflict",
  "LedgerError",
  "ConversationStoreError",
  "ConversationNotMaterialized",
  "AppendConflict",
  "FenceRejected",
  "DurableRuntimeFailpointError",
  "AdmissionLimitExceeded",
  "DurableAlarmError",
  "HostProtocolError",
]);
const AWAIT_FAILURE_TAGS: ReadonlySet<string> = new Set([
  "LedgerError",
  "SettlementConflict",
  "HostProtocolError",
]);
const OBSERVE_FAILURE_TAGS: ReadonlySet<string> = new Set([
  "ConversationStoreError",
  "ConversationNotMaterialized",
  "HostProtocolError",
]);
const ABORT_FAILURE_TAGS: ReadonlySet<string> = new Set([
  "LedgerError",
  "SettlementConflict",
  "JoinedToHost",
  "DurableRuntimeFailpointError",
  "DurableAlarmError",
  "HostProtocolError",
]);
const APPROVAL_FAILURE_TAGS: ReadonlySet<string> = new Set([
  "LedgerError",
  "SettlementConflict",
  "ApprovalConflict",
  "DurableAlarmError",
  "HostProtocolError",
]);
const UNKNOWN_FAILURE_TAGS: ReadonlySet<string> = new Set([
  "LedgerError",
  "SettlementConflict",
  "UnknownResolutionConflict",
  "JoinedToHost",
  "DurableRuntimeFailpointError",
  "DurableAlarmError",
  "HostProtocolError",
]);

const outOfContract = (
  conversationId: string,
  operation: string,
  observed: string,
): ConversationClientError =>
  ConversationClientError.make({
    conversationId,
    message: boundHostDiagnostic(
      `The Conversation Object answered ${operation} with the out-of-contract ${observed}.`,
    ),
  });

/**
 * Narrow one decoded `HostFailed.failure` to the operation's declared failure family; an
 * out-of-contract tag folds into `ConversationClientError` instead of being erased or
 * re-thrown raw (the WP2 discipline). The predicate is the single documented narrowing over
 * the closed `HostFailure` union.
 */
const narrowFailure =
  <Failure extends HostFailure>(tags: ReadonlySet<string>) =>
  (failure: HostFailure): failure is Failure =>
    tags.has(failure._tag);

/** Worker-side client over the Conversation Object namespace (DEPLOY-010). */
export class CloudflareConversationClient extends Context.Service<
  CloudflareConversationClient,
  {
    /** Encode the input client-side, then durably submit to the owning Object. */
    readonly submit: <InputSchema extends Schema.Top>(
      agent: DurableSubmitAgent<InputSchema>,
      input: InputSchema["Type"],
      options: DurableSubmitOptions,
    ) => Effect.Effect<Receipt, ClientSubmitFailure, InputSchema["EncodingServices"]>;
    /** Wake-hinted, poll-guaranteed settlement wait executed inside the owning Object. */
    readonly awaitSettlement: (receipt: Receipt) => Effect.Effect<Settlement, ClientAwaitFailure>;
    /** One bounded page of canonical records. */
    readonly readPage: (
      conversationId: ConversationId,
      options?: {
        readonly afterSequence?: CanonicalSequence | undefined;
        readonly limit?: number | undefined;
      },
    ) => Effect.Effect<ReadonlyArray<CanonicalRecordEnvelope>, ClientObserveFailure>;
    /**
     * Every canonical record up to the CURRENT committed tail, via repeated pages. A
     * snapshot read, not a live observation — callers wanting liveness re-read after
     * `awaitSettlement`.
     */
    readonly readAll: (
      conversationId: ConversationId,
    ) => Effect.Effect<ReadonlyArray<CanonicalRecordEnvelope>, ClientObserveFailure>;
    /**
     * Submission-addressed operations take the owning Conversation explicitly (from the
     * Receipt): minted Submission identities stay OPAQUE outside the storage adapter that
     * minted them (D-P6-5), so the client never parses one to find the lane.
     */
    readonly abort: (
      conversationId: ConversationId,
      command: AbortCommand,
    ) => Effect.Effect<AbortIntent, ClientAbortFailure>;
    readonly resolveApproval: (
      conversationId: ConversationId,
      command: ApprovalDecisionCommand,
    ) => Effect.Effect<ApprovalDecisionIntent, ClientApprovalFailure>;
    readonly resolveUnknown: (
      conversationId: ConversationId,
      command: UnknownResolutionCommand,
    ) => Effect.Effect<UnknownResolutionIntent, ClientUnknownFailure>;
  }
>()("@effect-agent/platform-cloudflare/CloudflareConversationClient") {
  static readonly layer: Layer.Layer<
    CloudflareConversationClient,
    never,
    ConversationObjectNamespace
  > = Layer.effect(CloudflareConversationClient)(
    Effect.gen(function* () {
      const { namespace } = yield* ConversationObjectNamespace;

      const call = (
        conversationId: string,
        operation: string,
        invoke: (stub: DurableObjectStub<ConversationObjectRpc>) => Promise<unknown>,
      ): Effect.Effect<HostResponse, ConversationClientError | HostProtocolError> =>
        Effect.tryPromise({
          try: () => invoke(namespace.get(namespace.idFromName(conversationId))),
          catch: (cause) =>
            ConversationClientError.make({
              conversationId,
              message: boundHostDiagnostic(
                `${operation} did not reach the Conversation Object: ${
                  cause instanceof Error ? cause.message : String(cause)
                }`,
              ),
              cause,
            }),
        }).pipe(
          Effect.flatMap((raw) =>
            decodeHostResponse(raw).pipe(
              Effect.mapError(
                (error): HostProtocolError =>
                  HostProtocolError.make({
                    message: boundHostDiagnostic(
                      `The ${operation} answer could not be decoded: ${error.message}`,
                    ),
                  }),
              ),
            ),
          ),
          Effect.withSpan("CloudflareConversationClient.call", {
            attributes: { conversationId, operation },
          }),
        );

      const expect = <
        Result extends Exclude<HostResponse, HostFailed>,
        Failure extends HostFailure,
      >(
        conversationId: string,
        operation: string,
        resultTag: Result["_tag"],
        tags: ReadonlySet<string>,
      ) => {
        const isExpected = narrowFailure<Failure>(tags);
        return (
          response: HostResponse,
        ): Effect.Effect<Result, Failure | ConversationClientError> => {
          if (response._tag === "HostFailed") {
            const failure = response.failure;
            return isExpected(failure)
              ? Effect.fail(failure)
              : Effect.fail(outOfContract(conversationId, operation, `failure ${failure._tag}`));
          }
          if (response._tag !== resultTag) {
            return Effect.fail(outOfContract(conversationId, operation, `result ${response._tag}`));
          }
          return Effect.succeed(response as Result);
        };
      };

      const readPage = (
        conversationId: ConversationId,
        options?: {
          readonly afterSequence?: CanonicalSequence | undefined;
          readonly limit?: number | undefined;
        },
      ) =>
        Effect.gen(function* () {
          const request = ObservePageRequest.make({
            ...(options?.afterSequence === undefined
              ? {}
              : { afterSequence: options.afterSequence }),
            limit: options?.limit ?? 256,
          });
          const encoded = yield* encodeObservePageRequest(request).pipe(
            Effect.mapError((error) =>
              HostProtocolError.make({
                message: boundHostDiagnostic(`observePage request encode failed: ${error.message}`),
              }),
            ),
          );
          const response = yield* call(conversationId, "observePage", (stub) =>
            stub.observePage(encoded),
          );
          const page = yield* expect<ObservedPage, ClientObserveFailure & HostFailure>(
            conversationId,
            "observePage",
            "ObservedPage",
            OBSERVE_FAILURE_TAGS,
          )(response);
          return page.records;
        });

      return CloudflareConversationClient.of({
        submit: <InputSchema extends Schema.Top>(
          agent: DurableSubmitAgent<InputSchema>,
          input: InputSchema["Type"],
          options: DurableSubmitOptions,
        ) =>
          Effect.gen(function* () {
            // Client-side half of `DurableAgentRuntime.submit`'s input boundary: encode
            // through the Agent's input schema and prove the canonical persistence bounds.
            const encodedInput = yield* Schema.encodeEffect(agent.definition.input)(input).pipe(
              Effect.mapError((cause) =>
                AgentInputError.make({ message: `Unable to encode Agent input: ${cause.message}` }),
              ),
            );
            const inputPayload = yield* Schema.decodeUnknownEffect(PersistedJson)(
              encodedInput,
            ).pipe(
              Effect.mapError(() =>
                AgentInputError.make({
                  message: "Agent input does not satisfy the canonical persistence bounds",
                }),
              ),
            );
            const request = SubmitRequest.make({
              agentId: agent.definition.id,
              principal: options.principal,
              idempotencyKey: options.idempotencyKey,
              definitions: options.definitions,
              inputPayload,
            });
            const encoded = yield* encodeSubmitRequest(request).pipe(
              Effect.mapError((error) =>
                HostProtocolError.make({
                  message: boundHostDiagnostic(`submit request encode failed: ${error.message}`),
                }),
              ),
            );
            const response = yield* call(options.conversationId, "submit", (stub) =>
              stub.submitEncoded(encoded),
            );
            const succeeded = yield* expect<SubmitSucceeded, ClientSubmitFailure & HostFailure>(
              options.conversationId,
              "submit",
              "SubmitSucceeded",
              SUBMIT_FAILURE_TAGS,
            )(response);
            return succeeded.receipt;
          }),

        awaitSettlement: (receipt) =>
          Effect.gen(function* () {
            const encoded = yield* encodeReceipt(receipt).pipe(
              Effect.mapError((error) =>
                HostProtocolError.make({
                  message: boundHostDiagnostic(`receipt encode failed: ${error.message}`),
                }),
              ),
            );
            const response = yield* call(receipt.conversationId, "awaitSettlement", (stub) =>
              stub.awaitSettlementEncoded(encoded),
            );
            const settled = yield* expect<SettlementReached, ClientAwaitFailure & HostFailure>(
              receipt.conversationId,
              "awaitSettlement",
              "SettlementReached",
              AWAIT_FAILURE_TAGS,
            )(response);
            return settled.settlement;
          }),

        readPage,

        readAll: (conversationId) =>
          Effect.gen(function* () {
            const all: Array<CanonicalRecordEnvelope> = [];
            let after: CanonicalSequence | undefined;
            for (;;) {
              const page = yield* readPage(conversationId, { afterSequence: after, limit: 1_024 });
              all.push(...page);
              const last = page.at(-1);
              if (page.length < 1_024 || last === undefined) return all;
              after = last.sequence;
            }
          }),

        abort: (conversationId, command) =>
          Effect.gen(function* () {
            const encoded = yield* encodeAbortCommand(command).pipe(
              Effect.mapError((error) =>
                HostProtocolError.make({
                  message: boundHostDiagnostic(`abort command encode failed: ${error.message}`),
                }),
              ),
            );
            const response = yield* call(conversationId, "abort", (stub) =>
              stub.abortEncoded(encoded),
            );
            const recorded = yield* expect<AbortRecorded, ClientAbortFailure & HostFailure>(
              conversationId,
              "abort",
              "AbortRecorded",
              ABORT_FAILURE_TAGS,
            )(response);
            return recorded.intent;
          }),

        resolveApproval: (conversationId, command) =>
          Effect.gen(function* () {
            const encoded = yield* encodeApprovalDecisionCommand(command).pipe(
              Effect.mapError((error) =>
                HostProtocolError.make({
                  message: boundHostDiagnostic(`approval command encode failed: ${error.message}`),
                }),
              ),
            );
            const response = yield* call(conversationId, "resolveApproval", (stub) =>
              stub.resolveApprovalEncoded(encoded),
            );
            const recorded = yield* expect<ApprovalRecorded, ClientApprovalFailure & HostFailure>(
              conversationId,
              "resolveApproval",
              "ApprovalRecorded",
              APPROVAL_FAILURE_TAGS,
            )(response);
            return recorded.intent;
          }),

        resolveUnknown: (conversationId, command) =>
          Effect.gen(function* () {
            const encoded = yield* encodeUnknownResolutionCommand(command).pipe(
              Effect.mapError((error) =>
                HostProtocolError.make({
                  message: boundHostDiagnostic(
                    `resolution command encode failed: ${error.message}`,
                  ),
                }),
              ),
            );
            const response = yield* call(conversationId, "resolveUnknown", (stub) =>
              stub.resolveUnknownEncoded(encoded),
            );
            const recorded = yield* expect<
              UnknownResolutionRecorded,
              ClientUnknownFailure & HostFailure
            >(
              conversationId,
              "resolveUnknown",
              "UnknownResolutionRecorded",
              UNKNOWN_FAILURE_TAGS,
            )(response);
            return recorded.intent;
          }),
      });
    }),
  );
}

import {
  CodeExecutionHost,
  CodeExecutionResourceUse,
  CodeExecutionResult,
  CodeExecutionTimeoutError,
  CodeExecutor,
  CodeExecutorStartError,
  CodeExecutorTerminatedError,
  CodeExecutorUnsupportedError,
  CodeExecutionProtocolError,
  CodeHostCall,
  CodeHostCallLimitError,
  CodeHostCallResult,
  CodeOutputLimitError,
  CodeProgramFailedError,
  CodeSourceError,
  SandboxImplementation,
  type CodeExecutorExecute,
  type CodeExecutionRequest,
} from "@effect-agent/sandbox";
import { WorkerEntrypoint } from "cloudflare:workers";
import { Cause, Duration, Effect, Exit, Fiber, Layer, Option, Schema } from "effect";

/**
 * The Cloudflare Dynamic Worker `CodeExecutor` adapter (C4 of ADR-0017;
 * DEPLOY-011). Each pass loads one fresh Worker through the Worker Loader
 * with `globalOutbound: null`, so generated code has no ambient network,
 * bindings, or secrets; its only authority is the pass-scoped host stub that
 * routes back to `CodeModeHostEntrypoint` and, from there, into the pass's
 * `CodeExecutionHost` service. Platform CPU limits stop synchronous runaway
 * programs; the executor-owned wall-clock deadline interrupts asynchronously
 * suspended passes. Deployment class `E` only: the adapter records no
 * persistent state and a later pass may run in a completely different
 * isolate.
 */
export const dynamicWorkerImplementation = SandboxImplementation.make({
  isolation: "isolated",
  identity: "cloudflare-dynamic-worker",
});

/** The narrow host stub the dynamic worker receives (Workers RPC). */
export interface CodeModeHostStub {
  readonly call: (passId: string, hostCall: unknown) => Promise<unknown>;
}

interface RegisteredPass {
  readonly dispatch: (hostCall: unknown) => Promise<unknown>;
}

/**
 * Live passes by identity. Entries are Scope-managed: registered when a pass
 * opens and removed by its finalizer, so a stale harness (or a forged
 * `passId`) cannot reach any host authority.
 */
const passRegistry = new Map<string, RegisteredPass>();

/**
 * The host-side RPC target for dynamic workers. The application exposes it
 * from its Worker entry (`export { CodeModeHostEntrypoint }`) and hands the
 * adapter a same-instance stub — `ctx.exports.CodeModeHostEntrypoint()` in
 * production (a self service binding may reach a different instance and must
 * not be used there); tests bind it through Miniflare's `kCurrentWorker`.
 */
export class CodeModeHostEntrypoint extends WorkerEntrypoint {
  async call(passId: unknown, hostCall: unknown): Promise<unknown> {
    const pass = passRegistry.get(String(passId));
    if (pass === undefined) {
      throw new Error("Unknown Code Mode pass");
    }
    return pass.dispatch(hostCall);
  }
}

/**
 * The fixed harness loaded as the dynamic worker's main module. The generated
 * source becomes `program.mjs` (`export default (<expression>);`) — a module,
 * never `eval`. The harness installs namespace globals and a bounded console,
 * imports the program, invokes it exactly once, and returns one envelope the
 * host validates through Effect Schema.
 */
const HARNESS_MODULE = String.raw`
import { WorkerEntrypoint } from "cloudflare:workers";
import programDefault from "./program.js";

const encoder = new TextEncoder();
const utf8 = (text) => encoder.encode(text).byteLength;
const safeText = (value) => {
  try {
    if (value instanceof Error) return (value.name + ": " + value.message).slice(0, 4000);
    if (typeof value === "string") return value.slice(0, 4000);
    const encoded = JSON.stringify(value);
    return (encoded === undefined ? String(value) : encoded).slice(0, 4000);
  } catch {
    return "[unserializable value]";
  }
};
const safeJson = (value) => {
  try {
    const encoded = JSON.stringify(value);
    if (encoded !== undefined && encoded.length <= 4000) return JSON.parse(encoded);
  } catch {}
  return safeText(value);
};

export default class CodeModeHarness extends WorkerEntrypoint {
  async run() {
    const config = JSON.parse(this.env.CODE_MODE_PASS);
    const host = this.env.CODE_MODE_HOST;
    const limits = config.limits;
    const logs = [];
    let logBytes = 0;
    let fatal;
    const boundedLogs = () => logs.slice(0, 4096);
    const write = (...values) => {
      const joined = values.map(safeText).join(" ");
      const line = joined.length > 16000 ? joined.slice(0, 15999) + "…" : joined;
      const bytes = utf8(line);
      if (logs.length >= 4096 || logBytes + bytes > limits.maxLogBytes) {
        fatal = fatal ?? { _tag: "log-limit", observed: logBytes + bytes, logs: boundedLogs() };
        throw new Error("code-mode log limit exceeded");
      }
      logs.push(line);
      logBytes += bytes;
    };
    globalThis.console = { log: write, info: write, warn: write, error: write, debug: write };

    let hostCalls = 0;
    const makeMethod = (namespace, method) => async (argument) => {
      hostCalls += 1;
      if (hostCalls > limits.maxHostCalls) {
        fatal = fatal ?? { _tag: "host-call-limit", logs: boundedLogs() };
        throw new Error("code-mode host-call limit exceeded");
      }
      let argText;
      try {
        argText = JSON.stringify(argument);
      } catch {}
      if (argText === undefined || utf8(argText) > limits.maxHostCallArgumentBytes) {
        fatal = fatal ?? {
          _tag: "argument-limit",
          observed: argText === undefined ? 0 : utf8(argText),
          logs: boundedLogs(),
        };
        throw new Error("code-mode host-call argument limit exceeded");
      }
      const outcome = await host.call(config.passId, {
        namespace,
        method,
        argument: JSON.parse(argText),
      });
      if (outcome !== null && typeof outcome === "object" && outcome._tag === "CodeHostCallSuccess") {
        return outcome.value;
      }
      if (outcome !== null && typeof outcome === "object" && outcome._tag === "CodeHostCallFailure") {
        throw outcome.error;
      }
      fatal = fatal ?? { _tag: "protocol", message: "host returned an unrecognized outcome" };
      throw new Error("code-mode host protocol violation");
    };
    for (const namespace of config.namespaces) {
      const methods = {};
      for (const method of namespace.methods) {
        methods[method] = makeMethod(namespace.name, method);
      }
      globalThis[namespace.name] = methods;
    }

    // program.js is imported statically at the top of this module, so a
    // syntactically invalid program fails the whole harness at load (mapped
    // to a source error by the host). Using a static import keeps this module
    // free of dynamic-import expressions, which single-script Miniflare hosts
    // reject. The isolation boundary does NOT depend on the ordering of this
    // import versus the console/namespace shims installed below: the loaded
    // Worker has globalOutbound: null and no bindings, secrets, or env from
    // the Worker Loader config BEFORE any module in the graph evaluates, so
    // module-level program code has no ambient authority regardless. The
    // shims below are usability wrappers (bounded console, namespace globals),
    // and the accepted program is a single async-function expression whose
    // body runs only when invoked here — after the shims exist.
    const program = programDefault;
    if (typeof program !== "function") {
      return { _tag: "source-not-a-function", actual: typeof program };
    }
    try {
      const value = await program();
      if (fatal !== undefined) return fatal;
      let text;
      try {
        text = JSON.stringify(value);
      } catch {}
      if (text === undefined) {
        return {
          _tag: "program-failed",
          reason: "non-json-result",
          thrown: null,
          message: "The program must return a JSON value",
          logs: boundedLogs(),
        };
      }
      const resultBytes = utf8(text);
      if (resultBytes > limits.maxResultBytes) {
        return { _tag: "result-limit", observed: resultBytes, logs: boundedLogs() };
      }
      return {
        _tag: "completed",
        value: JSON.parse(text),
        logs: boundedLogs(),
        hostCalls,
        logBytes,
        resultBytes,
      };
    } catch (cause) {
      if (fatal !== undefined) return fatal;
      return {
        _tag: "program-failed",
        reason: cause instanceof Error ? "threw" : "rejected",
        thrown: safeJson(cause),
        message: safeText(cause),
        logs: boundedLogs(),
      };
    }
  }
}
`;

const BoundedLogs = Schema.Array(Schema.String.check(Schema.isMaxLength(16 * 1024))).check(
  Schema.isMaxLength(4_096),
);

const HarnessCompleted = Schema.Struct({
  _tag: Schema.Literal("completed"),
  value: Schema.Json,
  logs: BoundedLogs,
  hostCalls: Schema.Natural,
  logBytes: Schema.Natural,
  resultBytes: Schema.Natural,
});
const HarnessSourceInvalid = Schema.Struct({
  _tag: Schema.Literal("source-invalid"),
  message: Schema.String,
});
const HarnessNotAFunction = Schema.Struct({
  _tag: Schema.Literal("source-not-a-function"),
  actual: Schema.String,
});
const HarnessProgramFailed = Schema.Struct({
  _tag: Schema.Literal("program-failed"),
  reason: Schema.Literals(["threw", "rejected", "non-json-result"]),
  thrown: Schema.Json,
  message: Schema.String,
  logs: BoundedLogs,
});
const HarnessLogLimit = Schema.Struct({
  _tag: Schema.Literal("log-limit"),
  observed: Schema.Natural,
  logs: BoundedLogs,
});
const HarnessArgumentLimit = Schema.Struct({
  _tag: Schema.Literal("argument-limit"),
  observed: Schema.Natural,
  logs: BoundedLogs,
});
const HarnessResultLimit = Schema.Struct({
  _tag: Schema.Literal("result-limit"),
  observed: Schema.Natural,
  logs: BoundedLogs,
});
const HarnessHostCallLimit = Schema.Struct({
  _tag: Schema.Literal("host-call-limit"),
  logs: BoundedLogs,
});
const HarnessProtocol = Schema.Struct({
  _tag: Schema.Literal("protocol"),
  message: Schema.String,
});
const HarnessOutcome = Schema.Union([
  HarnessCompleted,
  HarnessSourceInvalid,
  HarnessNotAFunction,
  HarnessProgramFailed,
  HarnessLogLimit,
  HarnessArgumentLimit,
  HarnessResultLimit,
  HarnessHostCallLimit,
  HarnessProtocol,
]);

const decodeHarnessOutcome = (value: unknown) => {
  try {
    return Schema.decodeUnknownOption(HarnessOutcome)(value);
  } catch {
    return Option.none<typeof HarnessOutcome.Type>();
  }
};

const decodeHostCall = (value: unknown) => {
  try {
    return Schema.decodeUnknownOption(CodeHostCall)(value);
  } catch {
    return Option.none<CodeHostCall>();
  }
};

const decodeHostCallResult = (value: unknown) => {
  try {
    return Schema.decodeUnknownOption(CodeHostCallResult)(value);
  } catch {
    return Option.none<CodeHostCallResult>();
  }
};

/**
 * Project a host outcome to the plain JSON envelope the harness reads. A
 * `CodeExecutionHost` may return either real `CodeHostCallResult` instances
 * (the substitute and conformance kit) or plain-object equivalents (the Code
 * Mode capability's broker route), so this reads the shared fields rather than
 * `Schema.encodeSync`, which would reject a plain object.
 */
interface EncodedHostResultPayload {
  readonly encodedPayload: string;
  readonly resultBytes: number;
}

const encodeHostResultPayload = (
  outcome: CodeHostCallResult,
): EncodedHostResultPayload | undefined => {
  try {
    const payload = outcome._tag === "CodeHostCallSuccess" ? outcome.value : outcome.error;
    const encodedPayload = JSON.stringify(payload);
    if (encodedPayload === undefined) return undefined;
    return {
      encodedPayload,
      resultBytes: utf8ByteLength(encodedPayload),
    };
  } catch {
    return undefined;
  }
};

const utf8ByteLength = (value: string): number => {
  let total = 0;
  for (const character of value) {
    const codePoint = character.codePointAt(0) ?? 0;
    total += codePoint <= 0x7f ? 1 : codePoint <= 0x7ff ? 2 : codePoint <= 0xffff ? 3 : 4;
  }
  return total;
};

type HostDispatchFailure =
  | { readonly _tag: "host-call-limit" }
  | { readonly _tag: "host-call-result-limit"; readonly observed: number }
  | { readonly _tag: "host-call-protocol" }
  | { readonly _tag: "wall-clock-timeout" }
  | { readonly _tag: "host-call-defect"; readonly cause: Cause.Cause<never> };

interface QueuedHostCall {
  readonly call: CodeHostCall;
  readonly resolve: (value: unknown) => void;
  readonly reject: (reason: unknown) => void;
}

interface ActiveHostCall {
  readonly fiber: Fiber.Fiber<Record<string, unknown>, never>;
  readonly settlement: Promise<void>;
}

/** Reserved global names the harness owns inside the dynamic worker. */
const reservedHarnessGlobals = new Set(["console"]);

export interface DynamicWorkerCodeExecutorOptions {
  /** The `worker_loader` binding. */
  readonly loader: WorkerLoader;
  /**
   * A SAME-INSTANCE stub of `CodeModeHostEntrypoint`. In production create it
   * with `ctx.exports.CodeModeHostEntrypoint()`; a cross-instance stub would
   * dispatch host calls into an isolate without this pass's registry entry.
   */
  readonly hostStub: CodeModeHostStub;
  /** Compatibility date for dynamic workers; defaults to `2025-05-01`. */
  readonly compatibilityDate?: string | undefined;
}

const passCounterState = { next: 0 };

const makeExecute = (options: DynamicWorkerCodeExecutorOptions): CodeExecutorExecute =>
  Effect.fn("DynamicWorkerCodeExecutor.execute")(function* (request: CodeExecutionRequest) {
    if (request.network._tag !== "NetworkDisabled") {
      return yield* CodeExecutorUnsupportedError.make({
        implementation: dynamicWorkerImplementation,
        feature: "network",
        message:
          "The Dynamic Worker executor denies all egress with globalOutbound: null; an allowlist is not supported in the first slice",
      });
    }
    const sourceBytes = utf8ByteLength(request.source);
    if (sourceBytes > request.limits.maxSourceBytes) {
      return yield* CodeSourceError.make({
        implementation: dynamicWorkerImplementation,
        reason: "oversized",
        message: `Source is ${sourceBytes} bytes; the request allows ${request.limits.maxSourceBytes}`,
      });
    }
    for (const namespace of request.namespaces) {
      if (reservedHarnessGlobals.has(namespace.name)) {
        return yield* CodeExecutorUnsupportedError.make({
          implementation: dynamicWorkerImplementation,
          feature: "namespaces",
          message: `Namespace ${namespace.name} collides with a harness binding`,
        });
      }
    }

    const host = yield* CodeExecutionHost;
    passCounterState.next += 1;
    // The pass id is the only credential a loaded program presents to reach
    // its host authority, so it must be unguessable: a program cannot forge
    // another pass's id even if two passes were ever concurrent (the broker
    // keeps them sequential, but the id must not rely on that). The counter
    // prefix keeps ids debuggable; the random suffix makes them unforgeable.
    const passId = `code-mode-pass-${passCounterState.next}-${crypto.randomUUID()}`;

    const startedAt = performance.now();
    const passDeadline = startedAt + Duration.toMillis(request.limits.maxWallTime);
    const remainingPassWallTime = (): Duration.Duration =>
      Duration.millis(Math.max(0, passDeadline - performance.now()));
    let issuedHostCalls = 0;
    let passOpen = true;
    const queuedHostCalls: Array<QueuedHostCall> = [];
    let activeHostCall: ActiveHostCall | undefined;
    let hostDispatchFailure: HostDispatchFailure | undefined;
    let propagatedHostDispatchFailure: HostDispatchFailure | undefined;
    let signalHostDispatchFailure = (_failure: HostDispatchFailure): void => undefined;
    const hostDispatchFailureSignal = new Promise<HostDispatchFailure>((resolve) => {
      signalHostDispatchFailure = resolve;
    });
    const rejectQueuedHostCalls = (reason: Error): void => {
      for (const queued of queuedHostCalls.splice(0)) {
        queued.reject(reason);
      }
    };
    const recordHostDispatchFailure = (failure: HostDispatchFailure): void => {
      if (hostDispatchFailure !== undefined) return;
      hostDispatchFailure = failure;
      signalHostDispatchFailure(failure);
      rejectQueuedHostCalls(new Error("Code Mode pass failed"));
    };
    const failHostDispatch = (failure: HostDispatchFailure) => {
      switch (failure._tag) {
        case "host-call-limit":
          return Effect.fail(
            CodeHostCallLimitError.make({
              implementation: dynamicWorkerImplementation,
              limit: request.limits.maxHostCalls,
              logs: [],
            }),
          );
        case "host-call-result-limit":
          return Effect.fail(
            CodeOutputLimitError.make({
              implementation: dynamicWorkerImplementation,
              surface: "host-call-result",
              limit: request.limits.maxHostCallResultBytes,
              observed: failure.observed,
              logs: [],
            }),
          );
        case "host-call-protocol":
          return Effect.fail(
            CodeExecutionProtocolError.make({
              implementation: dynamicWorkerImplementation,
              message: "The execution host returned a value outside the CodeHostCallResult schema",
            }),
          );
        case "wall-clock-timeout":
          return Effect.fail(
            CodeExecutionTimeoutError.make({
              implementation: dynamicWorkerImplementation,
              kind: "wall-clock",
              maxWallTime: request.limits.maxWallTime,
              logs: [],
            }),
          );
        case "host-call-defect":
          return Effect.failCause(failure.cause);
      }
    };
    const propagateHostDispatchFailure = (failure: HostDispatchFailure) =>
      Effect.gen(function* () {
        propagatedHostDispatchFailure = failure;
        return yield* failHostDispatch(failure);
      });

    const startNextHostCall = (): void => {
      if (!passOpen || hostDispatchFailure !== undefined || activeHostCall !== undefined) return;
      const queued = queuedHostCalls.shift();
      if (queued === undefined) return;

      // A Dynamic Worker callback is a new Workers RPC into the loader isolate. Running the
      // complete host call on an independent root fiber breaks its dependency on the still-open
      // guest RPC. Retaining the handle and starting one call at a time preserves bounded,
      // serialized execution and lets pass teardown interrupt and await the active call.
      const fiber = Effect.runFork(
        Effect.yieldNow.pipe(
          Effect.andThen(host.call(queued.call)),
          Effect.timeoutOrElse({
            duration: remainingPassWallTime(),
            orElse: () =>
              Effect.sync(() => {
                recordHostDispatchFailure({ _tag: "wall-clock-timeout" });
                throw new Error("code-mode host call exceeded the pass wall-clock limit");
              }),
          }),
          Effect.map((outcome) => {
            const decoded = decodeHostCallResult(outcome);
            if (Option.isNone(decoded)) {
              recordHostDispatchFailure({ _tag: "host-call-protocol" });
              throw new Error("host-call protocol violation");
            }
            const encoded = encodeHostResultPayload(decoded.value);
            if (
              encoded === undefined ||
              encoded.resultBytes > request.limits.maxHostCallResultBytes
            ) {
              recordHostDispatchFailure({
                _tag: "host-call-result-limit",
                observed: encoded?.resultBytes ?? 0,
              });
              throw new Error("host-call result limit exceeded");
            }
            const normalizedPayload: unknown = JSON.parse(encoded.encodedPayload);
            return decoded.value._tag === "CodeHostCallSuccess"
              ? { _tag: "CodeHostCallSuccess", value: normalizedPayload }
              : { _tag: "CodeHostCallFailure", error: normalizedPayload };
          }),
        ),
      );
      const settlement = Effect.runPromise(Fiber.await(fiber))
        .then((exit) => {
          if (Exit.isSuccess(exit)) {
            queued.resolve(exit.value);
            return;
          }
          if (!Cause.hasInterruptsOnly(exit.cause)) {
            recordHostDispatchFailure({ _tag: "host-call-defect", cause: exit.cause });
          }
          queued.reject(new Error("Code Mode host call failed"));
        })
        .finally(() => {
          if (activeHostCall?.fiber === fiber) activeHostCall = undefined;
          startNextHostCall();
        });
      activeHostCall = { fiber, settlement };
    };

    const dispatch = (hostCall: unknown): Promise<unknown> => {
      if (!passOpen) {
        return Promise.reject(new Error("Code Mode pass is closing"));
      }
      issuedHostCalls += 1;
      if (issuedHostCalls > request.limits.maxHostCalls) {
        recordHostDispatchFailure({ _tag: "host-call-limit" });
        return Promise.reject(new Error("host-call limit exceeded"));
      }
      const decoded = decodeHostCall(hostCall);
      if (Option.isNone(decoded)) {
        return Promise.reject(new TypeError("host calls must match the CodeHostCall schema"));
      }
      return new Promise((resolve, reject) => {
        queuedHostCalls.push({ call: decoded.value, resolve, reject });
        startNextHostCall();
      });
    };

    const closeHostDispatch = Effect.gen(function* () {
      passOpen = false;
      passRegistry.delete(passId);
      rejectQueuedHostCalls(new Error("Code Mode pass is closing"));
      const active = activeHostCall;
      if (active !== undefined) {
        yield* Fiber.interrupt(active.fiber);
        yield* Effect.promise(() => active.settlement);
        if (activeHostCall === active) activeHostCall = undefined;
      }
      return hostDispatchFailure;
    });
    const stopHostDispatch = closeHostDispatch.pipe(
      Effect.flatMap((failure) =>
        failure !== undefined && propagatedHostDispatchFailure !== failure
          ? propagateHostDispatchFailure(failure)
          : Effect.void,
      ),
    );
    const releaseHostDispatch = closeHostDispatch.pipe(
      Effect.flatMap((failure) => {
        if (failure?._tag !== "host-call-defect" || propagatedHostDispatchFailure === failure) {
          return Effect.void;
        }
        propagatedHostDispatchFailure = failure;
        return Effect.failCause(failure.cause);
      }),
    );

    yield* Effect.acquireRelease(
      Effect.sync(() => {
        passRegistry.set(passId, { dispatch });
      }),
      () => releaseHostDispatch,
    );

    const workerCode = {
      compatibilityDate: options.compatibilityDate ?? "2025-05-01",
      allowExperimental: true,
      mainModule: "harness.js",
      modules: {
        "harness.js": HARNESS_MODULE,
        "program.js": `export default (\n${request.source}\n);`,
      },
      env: {
        CODE_MODE_HOST: options.hostStub,
        CODE_MODE_PASS: JSON.stringify({
          passId,
          namespaces: request.namespaces.map((namespace) => ({
            name: namespace.name,
            methods: namespace.methods,
          })),
          limits: {
            maxLogBytes: request.limits.maxLogBytes,
            maxResultBytes: request.limits.maxResultBytes,
            maxHostCalls: request.limits.maxHostCalls,
            maxHostCallArgumentBytes: request.limits.maxHostCallArgumentBytes,
          },
        }),
      },
      globalOutbound: null,
      ...(request.limits.cpuMillis === undefined
        ? {}
        : {
            limits: {
              cpuMs: request.limits.cpuMillis,
              subRequests: request.limits.maxHostCalls + 8,
            },
          }),
    };

    const worker = yield* Effect.acquireRelease(
      Effect.try({
        try: () => options.loader.load(workerCode as never),
        catch: (cause) => {
          const text = cause instanceof Error ? cause.message : String(cause);
          // Blame the program's source ONLY on a genuine compile diagnostic;
          // any other load rejection is an infrastructure start failure, not
          // the model's fault (see classifyWorkerFailure for the same split).
          if (/syntaxerror|failed to (compile|parse)/i.test(text)) {
            return CodeSourceError.make({
              implementation: dynamicWorkerImplementation,
              reason: "invalid",
              message: text.slice(0, 8_000),
            });
          }
          return CodeExecutorStartError.make({
            implementation: dynamicWorkerImplementation,
            message: `The Worker Loader rejected the pass: ${text}`.slice(0, 8_000),
            cause,
          });
        },
      }),
      (stub) =>
        Effect.sync(() => {
          (stub as Partial<Record<typeof Symbol.dispose, () => void>>)[Symbol.dispose]?.();
        }),
    );

    const rpc = Effect.tryPromise({
      try: async () => {
        const entrypoint = worker.getEntrypoint() as unknown as {
          run(): Promise<unknown>;
        };
        return await entrypoint.run();
      },
      catch: (cause) => classifyWorkerFailure(cause, request.limits.maxWallTime),
    });

    const raw = yield* Effect.raceFirst(
      rpc.pipe(
        Effect.timeoutOrElse({
          duration: remainingPassWallTime(),
          orElse: () =>
            CodeExecutionTimeoutError.make({
              implementation: dynamicWorkerImplementation,
              kind: "wall-clock",
              maxWallTime: request.limits.maxWallTime,
              logs: [],
            }),
        }),
      ),
      Effect.promise(() => hostDispatchFailureSignal).pipe(
        Effect.flatMap(propagateHostDispatchFailure),
      ),
    );
    yield* stopHostDispatch;
    const finishedAt = performance.now();

    if (hostDispatchFailure !== undefined) {
      return yield* propagateHostDispatchFailure(hostDispatchFailure);
    }

    const outcome = decodeHarnessOutcome(raw);
    if (Option.isNone(outcome)) {
      return yield* CodeExecutionProtocolError.make({
        implementation: dynamicWorkerImplementation,
        message: "The dynamic worker returned a value outside the harness envelope schema",
      });
    }
    switch (outcome.value._tag) {
      case "completed": {
        return CodeExecutionResult.make({
          implementation: dynamicWorkerImplementation,
          value: outcome.value.value,
          logs: outcome.value.logs,
          resourceUse: CodeExecutionResourceUse.make({
            wallTime: Duration.millis(Math.max(0, finishedAt - startedAt)),
            hostCalls: outcome.value.hostCalls,
            logBytes: outcome.value.logBytes,
            resultBytes: outcome.value.resultBytes,
          }),
        });
      }
      case "source-invalid": {
        return yield* CodeSourceError.make({
          implementation: dynamicWorkerImplementation,
          reason: "invalid",
          message: outcome.value.message.slice(0, 8_000),
        });
      }
      case "source-not-a-function": {
        return yield* CodeSourceError.make({
          implementation: dynamicWorkerImplementation,
          reason: "not-a-function",
          message: `The source expression evaluated to ${outcome.value.actual}; it must evaluate to one async function`,
        });
      }
      case "program-failed": {
        return yield* CodeProgramFailedError.make({
          implementation: dynamicWorkerImplementation,
          reason: outcome.value.reason,
          thrown: outcome.value.thrown,
          message: outcome.value.message.slice(0, 8_000),
          logs: outcome.value.logs,
        });
      }
      case "log-limit": {
        return yield* CodeOutputLimitError.make({
          implementation: dynamicWorkerImplementation,
          surface: "logs",
          limit: request.limits.maxLogBytes,
          observed: outcome.value.observed,
          logs: outcome.value.logs,
        });
      }
      case "argument-limit": {
        return yield* CodeOutputLimitError.make({
          implementation: dynamicWorkerImplementation,
          surface: "host-call-argument",
          limit: request.limits.maxHostCallArgumentBytes,
          observed: outcome.value.observed,
          logs: outcome.value.logs,
        });
      }
      case "result-limit": {
        return yield* CodeOutputLimitError.make({
          implementation: dynamicWorkerImplementation,
          surface: "result",
          limit: request.limits.maxResultBytes,
          observed: outcome.value.observed,
          logs: outcome.value.logs,
        });
      }
      case "host-call-limit": {
        return yield* CodeHostCallLimitError.make({
          implementation: dynamicWorkerImplementation,
          limit: request.limits.maxHostCalls,
          logs: outcome.value.logs,
        });
      }
      case "protocol": {
        return yield* CodeExecutionProtocolError.make({
          implementation: dynamicWorkerImplementation,
          message: outcome.value.message.slice(0, 8_000),
        });
      }
    }
  });

/**
 * Expected worker-level failures map into the typed union with bounded
 * diagnostics; anything unrecognized stays a start/termination error rather
 * than a fabricated program result.
 */
const classifyWorkerFailure = (
  cause: unknown,
  maxWallTime: Duration.Duration,
):
  | CodeExecutionTimeoutError
  | CodeExecutorTerminatedError
  | CodeExecutorStartError
  | CodeSourceError => {
  const text = (() => {
    try {
      return cause instanceof Error ? `${cause.name}: ${cause.message}` : String(cause);
    } catch {
      return "[unserializable worker failure]";
    }
  })();
  // `WorkerLoader.load()` is lazy, so a module-compile error in the generated
  // program surfaces here at first use. Blame the program's source ONLY on a
  // genuine compile diagnostic (a `SyntaxError` or an explicit compile
  // failure) — the fixed harness is valid, so the fault is in program.js. A
  // bare "failed to start Worker" without a compile diagnostic is an
  // infrastructure start failure, not the model's fault, so it must NOT be
  // misclassified as a source error.
  if (/syntaxerror|failed to (compile|parse)/i.test(text)) {
    return CodeSourceError.make({
      implementation: dynamicWorkerImplementation,
      reason: "invalid",
      message: text.slice(0, 8_000),
    });
  }
  if (/cpu/i.test(text)) {
    return CodeExecutionTimeoutError.make({
      implementation: dynamicWorkerImplementation,
      kind: "cpu",
      maxWallTime,
      logs: [],
    });
  }
  if (/failed to start worker/i.test(text)) {
    return CodeExecutorStartError.make({
      implementation: dynamicWorkerImplementation,
      message: text.slice(0, 8_000),
      cause,
    });
  }
  return CodeExecutorTerminatedError.make({
    implementation: dynamicWorkerImplementation,
    message: text.slice(0, 8_000),
  });
};

/** Layer building the Dynamic Worker `CodeExecutor` from resolved bindings. */
export const dynamicWorkerCodeExecutorLayer = (
  options: DynamicWorkerCodeExecutorOptions,
): Layer.Layer<CodeExecutor> =>
  Layer.succeed(CodeExecutor)(CodeExecutor.of({ execute: makeExecute(options) }));

import { DEFAULT_OWNERSHIP_LEASE_DURATION, DeploymentId } from "@effect-agent/session";
import { DEFAULT_MAX_STORED_VALUE_BYTES } from "@effect-agent/storage-cloudflare";
import { Context, Duration, Schema } from "effect";

/**
 * Schema-validated configuration for the Cloudflare durable runtime (deployment spec §4:
 * decoded once during Layer construction, exposed as a typed service; DEPLOY-003). Every
 * cadence is in milliseconds; every bound is finite and checked before any resource opens.
 */

const PositiveMillis = Schema.Int.check(Schema.isGreaterThan(0));
const NonNegativeMillis = Schema.Int.check(Schema.isGreaterThanOrEqualTo(0));

/** The supplied Cloudflare durable runtime configuration failed validation (DEPLOY-003). */
export class CloudflarePlatformConfigError extends Schema.TaggedError<CloudflarePlatformConfigError>()(
  "CloudflarePlatformConfigError",
  {
    message: Schema.String,
    cause: Schema.optionalKey(Schema.Defect()),
  },
) {}

/**
 * An admission was refused by a host resource limit BEFORE any ledger row existed
 * (deployment spec §8, DEPLOY-007: "Admission has explicit bounded quota and overload
 * behavior... a typed rejection"). This is the DC analogue of `NodeDurableHost`'s
 * `AdmissionClosed` host gate: the port surface stays untouched, the refusal happens in the
 * Conversation Object's submit entry point before `DurableAgentRuntime.submit` runs, and
 * nothing was admitted or written.
 */
export class AdmissionLimitExceeded extends Schema.TaggedError<AdmissionLimitExceeded>()(
  "AdmissionLimitExceeded",
  {
    limit: Schema.Literals(["queue-depth", "input-bytes", "database-bytes"]),
    actual: Schema.Int,
    maximum: Schema.Int,
  },
) {
  override get message() {
    return (
      `Admission refused before any ledger row existed: ${this.limit} ${this.actual} exceeds ` +
      `the configured maximum ${this.maximum}. Accepted work is unaffected; retry after the ` +
      "lane drains or raise the limit (DEPLOY-007)."
    );
  }
}

/** The platform's hard per-Object database cap (10 GB, developers.cloudflare.com limits). */
export const CLOUDFLARE_DATABASE_CAP_BYTES = 10_000_000_000;

/** Default database-size admission ceiling: a 1 GB safety margin under the platform cap. */
export const DEFAULT_MAX_DATABASE_BYTES = 9_000_000_000;

/**
 * Explicit bounded admission quotas checked by the Conversation Object BEFORE admission
 * (exit gate "resource limits are checked before admission").
 */
export class CloudflareAdmissionLimitsValue extends Schema.Class<CloudflareAdmissionLimitsValue>(
  "@effect-agent/platform-cloudflare/CloudflareAdmissionLimitsValue",
)({
  /** Maximum nonterminal Submissions per Conversation lane before new admissions refuse. */
  maxQueueDepthPerLane: Schema.Int.check(
    Schema.isGreaterThan(0),
    Schema.isLessThanOrEqualTo(100_000),
  ),
  /** Maximum encoded input bytes; never above the storage per-value bound. */
  maxInputBytes: Schema.Int.check(Schema.isGreaterThan(0), Schema.isLessThanOrEqualTo(2_000_000)),
  /** Maximum `ctx.storage.sql.databaseSize` at admission; stays under the 10 GB platform cap. */
  maxDatabaseBytes: Schema.Int.check(
    Schema.isGreaterThan(0),
    Schema.isLessThanOrEqualTo(CLOUDFLARE_DATABASE_CAP_BYTES),
  ),
}) {}

/**
 * Validated Cloudflare durable runtime configuration. The producer identity of one
 * Conversation Object is `{producerPrefix}:{conversationId}` — stable across incarnations of
 * the same deployment, distinct across deployments — and producer-epoch fencing (not the
 * producer name) remains the correctness authority (DUR-006).
 */
export class CloudflareDurableRuntimeConfigValue extends Schema.Class<CloudflareDurableRuntimeConfigValue>(
  "@effect-agent/platform-cloudflare/CloudflareDurableRuntimeConfigValue",
)({
  deploymentId: DeploymentId,
  /** Head of the minted producer identity `{producerPrefix}:{conversationId}`. */
  producerPrefix: Schema.NonEmptyString.check(Schema.isMaxLength(256)),
  /** Submission ownership lease duration (D5); fences work across Object incarnations. */
  ownershipLeaseDuration: PositiveMillis,
  /** Base delay of the alarm re-arm backoff when a pass makes no progress. */
  alarmBackoffBase: PositiveMillis,
  /** Ceiling of the alarm re-arm backoff. */
  alarmBackoffCap: PositiveMillis,
  /**
   * The maintenance-pass scan cadence and the ceiling of every re-arm delay: nonterminal
   * work is revisited at least this often (wake/scan pairing, persistence §14).
   */
  wakeScanInterval: PositiveMillis,
  /** `awaitSettlement` ledger re-check cadence when no wake arrives. */
  settlementPollInterval: PositiveMillis,
  /** Worker ownership-lease renewal cadence during an active Attempt. */
  leaseRenewalInterval: PositiveMillis,
  /** Active-Run abort-intent poll cadence. */
  abortPollInterval: PositiveMillis,
  /** Canonical observation poll cadence of the Durable Object store. */
  observationPollInterval: NonNegativeMillis,
  /** Per-value byte bound; must stay under the platform's 2 MB SQLite value limit. */
  maxStoredValueBytes: Schema.Int.check(
    Schema.isGreaterThan(0),
    Schema.isLessThanOrEqualTo(2_000_000),
  ),
  /** Opt-in full payload/digest-chain audit while opening the store. */
  verifyOnOpen: Schema.Boolean,
  limits: CloudflareAdmissionLimitsValue,
}) {}

/** Explicit configuration authority for the assembled Cloudflare durable runtime. */
export class CloudflareDurableRuntimeConfig extends Context.Service<
  CloudflareDurableRuntimeConfig,
  CloudflareDurableRuntimeConfigValue
>()("@effect-agent/platform-cloudflare/CloudflareDurableRuntimeConfig") {}

/** Documented production defaults applied by `CloudflareDurableRuntime.layer`. */
