        ledger.beginChildBudgetRelease(
          BeginChildBudgetReleaseRequest.make({
            reservationId,
            accounting: { consumed: { turns: 2 }, released: { turns: 2 } },
          }),
        ),
      );
      yield* ensure(
        divergentAfterRelease instanceof ChildReservationConflict &&
