      const childA = yield* admitReady(childLaneA, "child-wake-a", { child: "a" });
      const childB = yield* admitReady(childLaneB, "child-wake-b", { child: "b" });
      const parentClaim = yield* expectSome(
        "the parent claim",
        yield* claimLane(parentLane, PRODUCER_A),
