import { SqliteClient } from "@effect/sql-sqlite-do";
import { DurableObject } from "cloudflare:workers";
import { Context, Effect, Layer, Option, Schema } from "effect";
import * as SqlClient from "effect/unstable/sql/SqlClient";

/**
 * The warehouse Durable Object: a SQLite-backed store of curated invoice data
 * that generated Code Mode programs query through a read-only SQL Tool. Only a
 * single curated `invoice_summary` table is exposed, and every query goes
 * through the read-only ALLOWLIST scan (`scanReadOnly`) — Durable Object
 * SQLite cannot lock the connection with `PRAGMA query_only`, so the demo
 * permits only single read statements (see the README for the production
 * guidance). Nothing about the connection, credentials, or storage ever
 * reaches the isolated executor: generated code sees only the brokered
 * `warehouse.query` method and its Schema-bounded result.
 *
 * This is the demo's "SQLite DO db": one Durable Object per tenant name,
 * seeded once, then read-only.
 */

const MAX_ROWS = 200;
const MAX_RESULT_BYTES = 256 * 1024;

/** A read-only query outcome returned across the DO RPC boundary as plain JSON. */
export interface WarehouseQueryOutcome {
  readonly ok: boolean;
  readonly columns: ReadonlyArray<string>;
  readonly rows: ReadonlyArray<Record<string, unknown>>;
  readonly rowCount: number;
  readonly truncated: boolean;
  /** Present when `ok` is false: a stable denial/failure reason. */
  readonly reason?: string;
}

const seedRows: ReadonlyArray<{
  readonly customer: string;
  readonly region: string;
  readonly revenue: number;
  readonly createdAt: string;
}> = [
  { customer: "Stellar Freight", region: "emea", revenue: 48_200, createdAt: "2026-07-03" },
  { customer: "Nimbus Analytics", region: "amer", revenue: 12_800, createdAt: "2026-07-11" },
  { customer: "Copper Kettle Co", region: "amer", revenue: 730, createdAt: "2026-07-15" },
  { customer: "Harbor Lights Ltd", region: "apac", revenue: 9_400, createdAt: "2026-07-21" },
  { customer: "Vertex Robotics", region: "emea", revenue: 21_050, createdAt: "2026-07-24" },
];

const stripLiteralsAndComments = (sql: string): string => {
  let output = "";
  let index = 0;
  while (index < sql.length) {
    const char = sql[index];
    if (char === "'") {
      index += 1;
      while (index < sql.length) {
        if (sql[index] === "'" && sql[index + 1] === "'") {
          index += 2;
          continue;
        }
        if (sql[index] === "'") {
          index += 1;
          break;
        }
        index += 1;
      }
      output += " ";
      continue;
    }
    if (char === "-" && sql[index + 1] === "-") {
      while (index < sql.length && sql[index] !== "\n") index += 1;
      continue;
    }
    output += char;
    index += 1;
  }
  return output;
};

// Cloudflare Durable Object SQLite blocks `PRAGMA query_only` through its
// statement authorizer (SQLITE_AUTH), so — unlike the Node reference fixture,
// which locks the connection read-only and lets database authority deny every
// write (the primary boundary the plan §8.4 prescribes) — this demo enforces
// read-only in application code. Because a denylist of write keywords is
// bypassable (e.g. a `WITH … DELETE` common-table expression does not START
// with a write keyword), the scan is an ALLOWLIST: the statement must be a
// single read (`SELECT`, or a `WITH` whose body is a read) and must contain
// no write, DDL, or escape-hatch token ANYWHERE in the literal-stripped text.
// A production deployment should still back the warehouse with a read-only
// database identity or curated read-only views rather than a text scan.
const readOnlyPrefix = /^\s*(select|with)\b/i;
const disallowedTokens =
  /\b(insert|update|delete|replace|drop|create|alter|truncate|reindex|analyze|pragma|attach|detach|vacuum|load_extension|savepoint|release|begin|commit|rollback)\b/i;

const scanReadOnly = (sql: string): string | undefined => {
  const stripped = stripLiteralsAndComments(sql);
  const semicolon = stripped.indexOf(";");
  if (semicolon !== -1 && stripped.slice(semicolon + 1).trim().length > 0) {
    return "exactly one statement is allowed per call";
  }
  if (!readOnlyPrefix.test(stripped)) {
    return "only read-only SELECT statements are allowed";
  }
  const disallowed = disallowedTokens.exec(stripped);
  return disallowed === null
    ? undefined
    : `${disallowed[1].toUpperCase()} is not allowed in a read-only query`;
};

const utf8ByteLength = (value: string): number => new TextEncoder().encode(value).byteLength;

const decodeRow = Schema.decodeUnknownOption(Schema.Record(Schema.String, Schema.Json));

/**
 * Run one bounded read-only query over the DO's SQLite storage. The read-only
 * boundary is the ALLOWLIST scan (`scanReadOnly`) — Durable Object SQLite
 * cannot lock the connection with `PRAGMA query_only`, so this demo permits
 * only single read statements. The row and byte caps are enforced WHILE
 * draining the cursor (early break), so a query that would return a huge
 * result set never fully materializes.
 */
const runQuery = (
  storage: DurableObjectStorage,
  sql: string,
  parameters: ReadonlyArray<string | number | boolean | null>,
): Effect.Effect<WarehouseQueryOutcome> =>
  Effect.sync(() => {
    const denied = scanReadOnly(sql);
    if (denied !== undefined) {
      return { ok: false, columns: [], rows: [], rowCount: 0, truncated: false, reason: denied };
    }
    let cursor;
    try {
      cursor = storage.sql.exec(sql, ...parameters);
    } catch (cause) {
      return {
        ok: false,
        columns: [],
        rows: [],
        rowCount: 0,
        truncated: false,
        reason: `query failed: ${(cause instanceof Error ? cause.message : String(cause)).slice(0, 500)}`,
      };
    }
    const rows: Array<Record<string, unknown>> = [];
    let truncated = false;
    let usedBytes = 0;
    for (const raw of cursor) {
      if (rows.length >= MAX_ROWS) {
        truncated = true;
        break;
      }
      const decoded = decodeRow(raw as Record<string, unknown>);
      if (Option.isNone(decoded)) {
        return {
          ok: false,
          columns: [],
          rows: [],
          rowCount: 0,
          truncated: false,
          reason: "a result row contained a non-JSON value",
        };
      }
      const bytes = utf8ByteLength(JSON.stringify(decoded.value));
      if (usedBytes + bytes > MAX_RESULT_BYTES) {
        truncated = true;
        break;
      }
      usedBytes += bytes;
      rows.push(decoded.value);
    }
    return {
      ok: true,
      columns: rows.length === 0 ? [] : Object.keys(rows[0]),
      rows,
      rowCount: rows.length,
      truncated,
    };
  });

export class WarehouseObject extends DurableObject {
  #ready = false;

  async #ensureSeeded(): Promise<void> {
    if (this.#ready) return;
    await Effect.runPromise(
      Effect.gen(function* () {
        const sql = yield* SqlClient.SqlClient;
        yield* sql`CREATE TABLE IF NOT EXISTS invoice_summary (
          customer TEXT NOT NULL,
          region TEXT NOT NULL,
          revenue INTEGER NOT NULL,
          created_at TEXT NOT NULL
        )`;
        const existing = yield* sql`SELECT COUNT(*) AS n FROM invoice_summary`.pipe(
          Effect.map((rows) => Number((rows[0] as { n?: unknown }).n ?? 0)),
        );
        if (existing === 0) {
          for (const row of seedRows) {
            yield* sql`INSERT INTO invoice_summary ${sql.insert({
              customer: row.customer,
              region: row.region,
              revenue: row.revenue,
              created_at: row.createdAt,
            })}`;
          }
        }
      }).pipe(
        Effect.provide(SqliteClient.layer({ storage: this.ctx.storage })),
        Effect.orDie,
      ) as Effect.Effect<void>,
    );
    // On Durable Object SQLite the `PRAGMA query_only` lock is authorizer-
    // blocked (SQLITE_AUTH), so the read-only guarantee here is the
    // leading-keyword scan in `scanReadOnly`; the Node reference fixture in
    // `@effect-agent/testing` proves the stronger database-authority path.
    this.#ready = true;
  }

  /** The read-only query RPC the warehouse Tool calls (Workers RPC returns JSON). */
  async query(
    sql: string,
    parameters: ReadonlyArray<string | number | boolean | null>,
  ): Promise<WarehouseQueryOutcome> {
    await this.#ensureSeeded();
    return Effect.runPromise(runQuery(this.ctx.storage, sql, parameters));
  }
}

/** Effect service wrapping the warehouse DO namespace (host-side authority). */
export class Warehouse extends Context.Service<
  Warehouse,
  {
    readonly query: (
      sql: string,
      parameters: ReadonlyArray<string | number | boolean | null>,
    ) => Effect.Effect<WarehouseQueryOutcome>;
  }
>()("@effect-agent/example-code-mode-cloudflare/Warehouse") {}

/** A safe tenant name: the DO is addressed by this, so bound it tightly. */
export const isValidTenant = (tenant: string): boolean => /^[a-z0-9-]{1,32}$/.test(tenant);

/** Build the Warehouse service from a resolved DO namespace + tenant name. */
export const warehouseLayer = (
  namespace: DurableObjectNamespace<WarehouseObject>,
  tenant: string,
): Layer.Layer<Warehouse> =>
  Layer.succeed(Warehouse)({
    query: (sql, parameters) =>
      // A Durable Object RPC failure (transport, DO exception) is an EXPECTED
      // outcome the tool handler branches on, not a defect — surface it as a
      // typed denied outcome rather than dying the pass.
      Effect.tryPromise((): Promise<WarehouseQueryOutcome> => {
        const stub = namespace.get(namespace.idFromName(tenant));
        return stub.query(sql, [...parameters]) as Promise<WarehouseQueryOutcome>;
      }).pipe(
        Effect.catch((error) =>
          Effect.succeed<WarehouseQueryOutcome>({
            ok: false,
            columns: [],
            rows: [],
            rowCount: 0,
            truncated: false,
            reason: `warehouse unavailable: ${(error.cause instanceof Error
              ? error.cause.message
              : String(error.cause)
            ).slice(0, 300)}`,
          }),
        ),
      ),
  });

import { IdGenerator } from "@effect-agent/core";
import { AgentRuntime } from "@effect-agent/engine";
import {
  CodeModeHostEntrypoint,
  dynamicWorkerCodeExecutorLayer,
  dynamicWorkerImplementation,
  type CodeModeHostStub,
} from "@effect-agent/platform-cloudflare";
import { Effect, Layer, Stream } from "effect";

import { codeModeHandlersLayer } from "./agent.ts";
import { liveAgent, scriptedAgent, scriptedWriteProbeAgent } from "./profiles.ts";
import { isValidTenant, Warehouse, WarehouseObject, warehouseLayer } from "./warehouse-object.ts";

/**
 * The demo Worker: it answers a natural-language question about the invoice
 * warehouse by running a Code Mode Agent. The model writes one JavaScript
 * program; the program executes in an isolated Cloudflare Dynamic Worker
 * (`globalOutbound: null`, no ambient authority) and reaches the warehouse
 * only through the brokered `warehouse.query` method, which runs a read-only
 * SQL query against a SQLite-backed Durable Object. Deployment class E: the
 * Agent runs ephemerally; the Durable Object is the warehouse data store, not
 * a Conversation store.
 *
 * `WarehouseObject` and `CodeModeHostEntrypoint` are exported for the Worker
 * runtime; the host entrypoint is bound to itself as `CODE_MODE_HOST` (see
 * wrangler.jsonc), matching the production `ctx.exports.CodeModeHostEntrypoint()`
 * seam.
 */
export { WarehouseObject, CodeModeHostEntrypoint };

interface WorkerEnv {
  readonly WAREHOUSE: DurableObjectNamespace<WarehouseObject>;
  readonly LOADER: WorkerLoader;
  readonly CODE_MODE_HOST: CodeModeHostStub;
  readonly OPENAI_API_KEY?: string;
  /**
   * Optional shared secret. When set, `/ask` requires a matching
   * `Authorization: Bearer <token>` header — set it whenever `OPENAI_API_KEY`
   * is deployed so the paid live endpoint cannot be driven anonymously.
   */
  readonly DEMO_AUTH_TOKEN?: string;
}

interface AskResult {
  readonly answer: string;
  /**
   * Evidence that the answer came from Code Mode: the tool the model called,
   * how many times, the JavaScript program it actually wrote, and the isolated
   * executor that ran it — plus the program's returned value and console logs.
   */
  readonly codeMode: {
    readonly used: boolean;
    readonly tool: string;
    readonly executor: string;
    readonly calls: number;
    readonly program?: string;
    readonly result?: unknown;
    readonly logs?: ReadonlyArray<unknown>;
  };
  readonly profile: "scripted" | "openai";
}

/**
 * Both profiles' bindings share one definition and both models resolve to a
 * bare `LanguageModel` with no residual requirements, so they are the same
 * runtime binding shape; the live binding is cast to the scripted one to
 * avoid threading two Model types through one function (a known type trap).
 */
type DemoBinding = typeof scriptedAgent;

/**
 * A `run_javascript` tool call's parameters are UNTRUSTED model output
 * (`Schema.Json` — possibly `null`, a primitive, or an array), so extract the
 * program source defensively rather than dereferencing a cast. Returning
 * `undefined` on anything unexpected keeps the observer from turning a
 * malformed declaration into a defect that aborts the request; the engine
 * still handles the actual (in)valid tool call through its typed channel.
 *
 * This reads the raw declared parameters for a display-only evidence field. No
 * engine event currently carries the DECODED tool input (`ToolCallStarted`
 * has none; `ToolCallDeclared` is raw), and the Code Mode input schema applies
 * no transform (raw `code` === executed source), so the raw value is faithful
 * here. A fully general "executed program" would need the engine to surface
 * the decoded input as an event.
 */
const programSourceOf = (parameters: unknown): string | undefined => {
  if (typeof parameters === "object" && parameters !== null && "code" in parameters) {
    const code = (parameters as Record<string, unknown>).code;
    return typeof code === "string" ? code : undefined;
  }
  return undefined;
};

/** The `run_javascript` success value is `{ result, logs }` — read it safely. */
const successOutcomeOf = (
  value: unknown,
): { readonly result: unknown; readonly logs: ReadonlyArray<unknown> } => {
  if (typeof value === "object" && value !== null) {
    const record = value as Record<string, unknown>;
    return { result: record.result, logs: Array.isArray(record.logs) ? record.logs : [] };
  }
  return { result: undefined, logs: [] };
};

/** Run one bound agent to an `AskResult`. */
const runBound = (
  env: WorkerEnv,
  agent: DemoBinding,
  question: string,
  tenant: string,
  profile: AskResult["profile"],
): Effect.Effect<AskResult> => {
  // The Code Mode handler needs the warehouse service and the executor
  // provided INTO it (its handler runs with the captured construction
  // context); the Run additionally needs IdGenerator.
  const layers = Layer.mergeAll(
    codeModeHandlersLayer.pipe(
      Layer.provide(warehouseLayer(env.WAREHOUSE, tenant)),
      Layer.provide(
        dynamicWorkerCodeExecutorLayer({ loader: env.LOADER, hostStub: env.CODE_MODE_HOST }),
      ),
    ),
    IdGenerator.layer,
  );
  return Effect.gen(function* () {
    // Stream the Run and correlate each `run_javascript` call's declared
    // program with the SAME call's success BY tool-call id, so the reported
    // program always matches the execution that produced the reported result
    // (a multi-call model can otherwise interleave a failed declaration with an
    // earlier call's result). `used` reflects a real successful execution, not
    // merely a declaration.
    const declaredPrograms = new Map<string, string | undefined>();
    const successes = new Map<string, { result: unknown; logs: ReadonlyArray<unknown> }>();
    let answer = "";
    let completed = false;
    // Expected Run failures become defects at this HTTP boundary: `runPromise`
    // rejects and the fetch handler answers 500 instead of fabricating a 200.
    yield* AgentRuntime.stream(agent, { question }).pipe(
      Stream.runForEach((event) =>
        Effect.sync(() => {
          if (event._tag === "ToolCallDeclared" && event.toolName === "run_javascript") {
            declaredPrograms.set(event.toolCallId, programSourceOf(event.parameters));
          }
          if (event._tag === "ToolCallSucceeded" && event.toolName === "run_javascript") {
            successes.set(event.toolCallId, successOutcomeOf(event.result));
          }
          if (event._tag === "RunCompleted") {
            completed = true;
            const output = event.output as { readonly answer?: unknown };
            if (typeof output.answer === "string") {
              answer = output.answer;
            }
          }
        }),
      ),
      Effect.provide(layers),
      Effect.scoped,
      Effect.orDie,
    );
    // A Run that ended without emitting RunCompleted (e.g. it hit a policy
    // limit) is NOT a success — surface it as a defect so `runPromise` rejects
    // and the fetch handler returns 500, rather than a 200 with an empty answer.
    if (!completed) {
      return yield* Effect.die(new Error("the agent run did not complete"));
    }
    // Claim a single program/result ONLY when exactly one run_javascript call
    // succeeded (with a matching declaration) — never arbitrarily pick among
    // several, and never assert provenance for a run that used zero or multiple
    // calls. `used` and `calls` stay honest either way; ambiguous runs simply
    // do not attach a single program/result to the answer.
    const successIds = [...successes.keys()];
    const soleId =
      successIds.length === 1 && declaredPrograms.has(successIds[0]) ? successIds[0] : undefined;
    const executed = soleId === undefined ? undefined : successes.get(soleId);
    return {
      answer,
      codeMode: {
        used: successes.size > 0,
        tool: "run_javascript",
        executor: dynamicWorkerImplementation.identity,
        calls: declaredPrograms.size,
        program: soleId === undefined ? undefined : declaredPrograms.get(soleId),
        result: executed?.result,
        logs: executed?.logs,
      },
      profile,
    };
  });
};

const runAsk = (
  env: WorkerEnv,
  question: string,
  tenant: string,
  probe: string | null,
): Effect.Effect<AskResult> => {
  if (env.OPENAI_API_KEY !== undefined && env.OPENAI_API_KEY.length > 0) {
    return runBound(
      env,
      liveAgent(env.OPENAI_API_KEY) as unknown as DemoBinding,
      question,
      tenant,
      "openai",
    );
  }
  const agent = probe === "write" ? scriptedWriteProbeAgent : scriptedAgent;
  return runBound(env, agent, question, tenant, "scripted");
};

export default {
  async fetch(request: Request, env: WorkerEnv): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname !== "/ask") {
      return new Response(
        "POST /ask { question } — Code Mode over a SQLite Durable Object warehouse",
        { status: url.pathname === "/" ? 200 : 404 },
      );
    }
    if (request.method !== "POST") {
      return Response.json({ error: "POST required" }, { status: 405 });
    }
    const liveMode = env.OPENAI_API_KEY !== undefined && env.OPENAI_API_KEY.length > 0;
    const authToken = env.DEMO_AUTH_TOKEN;
    const hasAuthToken = authToken !== undefined && authToken.length > 0;
    // Fail CLOSED on the paid path: if the live model is enabled but no shared
    // secret is configured, refuse rather than serve paid inference to
    // anonymous callers. The offline scripted default needs no secret.
    if (liveMode && !hasAuthToken) {
      return Response.json(
        { error: "server misconfigured: DEMO_AUTH_TOKEN must be set when OPENAI_API_KEY is" },
        { status: 503 },
      );
    }
    // When a shared secret is configured, require a matching bearer token.
    if (hasAuthToken && request.headers.get("authorization") !== `Bearer ${authToken}`) {
      return Response.json({ error: "unauthorized" }, { status: 401 });
    }
    let question = "Which customers have more than $10,000 in revenue?";
    try {
      const body = (await request.json()) as { readonly question?: unknown };
      if (typeof body.question === "string" && body.question.trim().length > 0) {
        // Bound the question so an oversized body cannot drive an unbounded prompt.
        question = body.question.slice(0, 2_000);
      }
    } catch {
      // fall back to the default question
    }
    // The tenant addresses a Durable Object, so reject anything that is not a
    // short, safe identifier rather than minting an arbitrary Object.
    const tenant = url.searchParams.get("tenant") ?? "acme";
    if (!isValidTenant(tenant)) {
      return Response.json({ error: "tenant must match /^[a-z0-9-]{1,32}$/" }, { status: 400 });
    }
    try {
      const result = await Effect.runPromise(
        runAsk(env, question, tenant, url.searchParams.get("probe")),
      );
      return Response.json(result);
    } catch (cause) {
      return Response.json(
        { error: cause instanceof Error ? cause.message : String(cause) },
        { status: 500 },
      );
    }
  },
};

// Re-exported so a consumer can compose the warehouse service directly.
export { Warehouse };

import { join } from "node:path";

import { build } from "esbuild";
import { Miniflare, kCurrentWorker } from "miniflare";
import { afterAll, beforeAll, describe, expect, it } from "vite-plus/test";

/**
 * The demo end to end in a real workerd runtime (programmatic Miniflare): a
 * Code Mode Agent answers a question by running one JavaScript program in an
 * isolated Cloudflare Dynamic Worker, and that program queries a real
 * SQLite-backed Durable Object warehouse through the brokered read-only SQL
 * tool. The scripted profile makes the run deterministic and credential-free;
 * the same Worker runs the live OpenAI profile when the secret is set.
 */

const workerEntry = join(import.meta.dirname, "..", "src", "worker.ts");

let workerScript = "";

const openRuntime = (): Miniflare =>
  new Miniflare({
    modules: true,
    script: workerScript,
    modulesRoot: "/",
    compatibilityDate: "2025-05-01",
    compatibilityFlags: ["nodejs_compat", "experimental"],
    durableObjects: {
      WAREHOUSE: { className: "WarehouseObject", useSQLite: true },
    },
    workerLoaders: { LOADER: {} },
    serviceBindings: {
      CODE_MODE_HOST: { name: kCurrentWorker, entrypoint: "CodeModeHostEntrypoint" },
    },
  });

interface AskResult {
  readonly answer: string;
  readonly codeMode: {
    readonly used: boolean;
    readonly tool: string;
    readonly executor: string;
    readonly calls: number;
    readonly program?: string;
    readonly result?: { readonly topCustomers: ReadonlyArray<string>; readonly count: number };
    readonly logs?: ReadonlyArray<string>;
  };
  readonly profile: string;
}

describe("Code Mode over a SQLite Durable Object warehouse", () => {
  const cleanups: Array<() => Promise<void>> = [];
  let runtime: Miniflare;

  beforeAll(async () => {
    const bundled = await build({
      entryPoints: [workerEntry],
      bundle: true,
      write: false,
      format: "esm",
      target: "es2022",
      platform: "browser",
      conditions: ["workerd", "worker", "browser"],
      external: ["cloudflare:*", "node:*"],
      logLevel: "silent",
    });
    const output = bundled.outputFiles[0];
    if (output === undefined) {
      throw new Error("esbuild produced no worker bundle");
    }
    // A transitive dependency ships a dead-code `import(<computed>)` that
    // single-script Miniflare's static module locator rejects even though it
    // never runs on the demo's path. Neutralize the dynamic-import
    // expressions in the HOST bundle (the fixed dynamic-worker harness uses a
    // static program import, so it carries none), mirroring the repository's
    // Miniflare restart lane.
    const disabled =
      'const __disabledDynamicImport = () => Promise.reject(new Error("dynamic import is disabled in the demo bundle"));\n';
    workerScript = `${disabled}${output.text.replaceAll(/\bimport\s*\(/g, "__disabledDynamicImport(")}`;
    runtime = openRuntime();
    cleanups.push(() => runtime.dispose());
  }, 120_000);

  afterAll(async () => {
    for (const cleanup of cleanups.reverse()) {
      await cleanup();
    }
  });

  it("runs a generated program in a Dynamic Worker that queries the SQLite DO warehouse", async () => {
    const response = await runtime.dispatchFetch("http://demo/ask", {
      method: "POST",
      body: JSON.stringify({ question: "Which customers have more than $10,000 in revenue?" }),
    });
    const rawBody = await response.text();
    expect(response.ok, `unexpected status ${response.status}: ${rawBody}`).toBe(true);
    const result = JSON.parse(rawBody) as AskResult;

    // The deterministic profile ran (no credential in the test env).
    expect(result.profile).toBe("scripted");
    // The final model answer came back.
    expect(result.answer).toContain("Stellar Freight");

    // Code Mode usage is surfaced explicitly: the tool, the isolated executor,
    // and the actual JavaScript the program was.
    expect(result.codeMode.used).toBe(true);
    expect(result.codeMode.tool).toBe("run_javascript");
    expect(result.codeMode.executor).toBe("cloudflare-dynamic-worker");
    expect(result.codeMode.calls).toBe(1);
    expect(result.codeMode.program).toContain("warehouse.query");

    // The evidence that matters: the isolated program queried the REAL
    // Durable Object SQLite and returned the computed result. The seed has
    // exactly three customers above $10k, highest revenue first.
    expect(result.codeMode.result).toEqual({
      topCustomers: ["Stellar Freight", "Vertex Robotics", "Nimbus Analytics"],
      count: 3,
    });
    expect(result.codeMode.logs).toContain("scanned 5 customers, kept 3");
  }, 120_000);

  it("denies a write-attempting program through the read-only allowlist", async () => {
    // The `?probe=write` program attempts an UPDATE inside the isolated
    // Dynamic Worker; the read-only allowlist denies it and the program
    // catches the typed WarehouseQueryDenied envelope.
    const response = await runtime.dispatchFetch("http://demo/ask?probe=write", {
      method: "POST",
      body: JSON.stringify({ question: "try to zero out revenue" }),
    });
    const rawBody = await response.text();
    expect(response.ok, `unexpected status ${response.status}: ${rawBody}`).toBe(true);
    const result = JSON.parse(rawBody) as {
      readonly codeMode: { readonly result?: { readonly writeDenied: boolean } };
    };
    expect(result.codeMode.result?.writeDenied).toBe(true);
  });

  it("rejects a CTE-prefixed write that a leading-keyword denylist would miss", async () => {
    // Direct-to-DO evidence that the allowlist is not bypassable by a
    // statement that merely does not START with a write keyword. The row
    // count is unchanged afterward.
    const warehouse = await runtime.getDurableObjectNamespace("WAREHOUSE");
    const stub = warehouse.get(warehouse.idFromName("acme")) as unknown as {
      query: (
        sql: string,
        parameters: ReadonlyArray<string | number | boolean | null>,
      ) => Promise<{
        readonly ok: boolean;
        readonly rows: ReadonlyArray<Record<string, unknown>>;
        readonly reason?: string;
      }>;
    };

    // Seed and confirm the baseline read works.
    const before = await stub.query("SELECT COUNT(*) AS n FROM invoice_summary", []);
    expect(before.ok).toBe(true);
    expect(before.rows[0]?.n).toBe(5);

    // A denylist keyed on the leading token would let this through; the
    // allowlist rejects it because DELETE appears anywhere in the statement.
    const bypass = await stub.query(
      "WITH doomed AS (SELECT customer FROM invoice_summary) DELETE FROM invoice_summary",
      [],
    );
    expect(bypass.ok).toBe(false);
    expect(bypass.reason).toMatch(/DELETE|read-only/i);

    const after = await stub.query("SELECT COUNT(*) AS n FROM invoice_summary", []);
    expect(after.ok).toBe(true);
    expect(after.rows[0]?.n).toBe(5);
  });
});

