import { OpenAiClient } from "@effect/ai-openai";
import { NodeRuntime, NodeServices } from "@effect/platform-node";
import { Config, Console, Effect, FileSystem, Layer, Option, Schema } from "effect";
import { BudgetExceeded, IdGenerator } from "effect-agent";
import { SubagentReservationsMemoryLive } from "effect-agent";
import { Command as CliCommand, Flag } from "effect/unstable/cli";
import { FetchHttpClient } from "effect/unstable/http";

import { makeOpenAiFanOutReviewer } from "./fan-out-profiles.ts";
import {
  FanOutCoordinatorToolkitLayer,
  fanOutHandlersLayer,
  FileReviewToolkitLayer,
} from "./fan-out-review-agent.ts";
import {
  GitHubReviewTarget,
  gitHubPullRequestSourceLayer,
  gitHubReviewPublisherLayer,
} from "./github.ts";
import { DEFAULT_REVIEW_MODEL, makeOpenAiReviewer } from "./profiles.ts";
import { ReviewPublicationPlan } from "./render.ts";
import { ReviewToolkitLayer } from "./review-agent.ts";
import { executeReview, fanOutReviewBudgetLimits, type ReviewRunOutcome } from "./run-review.ts";

// ---------------------------------------------------------------------------
// The GitHub Action entrypoint: resolve which pull request to review (flags
// first, then the Actions event payload), run one bounded ephemeral review,
// and either print the validated publication plan (default: dry run) or post
// it as a pull-request review (--post).
// ---------------------------------------------------------------------------

/** The pull request could not be resolved from flags or the environment. */
class ReviewCliError extends Schema.TaggedErrorClass<ReviewCliError>()("ReviewCliError", {
  reason: Schema.String,
}) {
  override get message() {
    return this.reason;
  }
}

/** The slice of a GitHub Actions event payload this CLI understands. */
const GitHubEventWire = Schema.Struct({
  pull_request: Schema.optionalKey(Schema.Struct({ number: Schema.Int })),
  repository: Schema.optionalKey(Schema.Struct({ full_name: Schema.String })),
});
const decodeEvent = Schema.decodeUnknownEffect(Schema.fromJsonString(GitHubEventWire));

const repoFlag = Flag.string("repo").pipe(
  Flag.optional,
  Flag.withDescription("Repository as owner/name; defaults to GITHUB_REPOSITORY."),
);
const prFlag = Flag.integer("pr").pipe(
  Flag.optional,
  Flag.withDescription("Pull request number; defaults to the GITHUB_EVENT_PATH payload."),
);
const modelFlag = Flag.string("model").pipe(
  Flag.withDefault(DEFAULT_REVIEW_MODEL),
  Flag.withDescription(`OpenAI model id (default ${DEFAULT_REVIEW_MODEL}).`),
);
const postFlag = Flag.boolean("post").pipe(
  Flag.withDescription("Post the review to GitHub; without it the plan prints to stdout."),
);
const applyVerdictFlag = Flag.boolean("apply-verdict").pipe(
  Flag.withDescription(
    "Map the model verdict onto APPROVE/REQUEST_CHANGES instead of always COMMENT.",
  ),
);
const fanOutFlag = Flag.boolean("fan-out").pipe(
  Flag.withDescription(
    "Fan the review out to bounded per-unit subagent reviewers (S1 attached delegation) instead of one flat reviewer.",
  ),
);

const resolveTarget = Effect.fn("resolveTarget")(function* (flags: {
  readonly repo: Option.Option<string>;
  readonly pr: Option.Option<number>;
}) {
  let repository = Option.getOrElse(flags.repo, () => "");
  if (repository === "") {
    repository = yield* Config.string("GITHUB_REPOSITORY").pipe(Config.withDefault(""));
  }
  let number = Option.getOrUndefined(flags.pr);
  if (number === undefined || repository === "") {
    const eventPath = yield* Config.string("GITHUB_EVENT_PATH").pipe(Config.withDefault(""));
    if (eventPath !== "") {
      const fs = yield* FileSystem.FileSystem;
      const raw = yield* fs
        .readFileString(eventPath)
        .pipe(
          Effect.mapError((error) =>
            ReviewCliError.make({ reason: `Cannot read event payload: ${error.message}` }),
          ),
        );
      const event = yield* decodeEvent(raw).pipe(
        Effect.mapError((error) =>
          ReviewCliError.make({ reason: `Cannot decode event payload: ${error.message}` }),
        ),
      );
      number ??= event.pull_request?.number;
      if (repository === "") repository = event.repository?.full_name ?? "";
    }
  }
  if (repository === "" || number === undefined) {
    return yield* ReviewCliError.make({
      reason:
        "No pull request to review: pass --repo owner/name and --pr <number>, or run inside a GitHub Actions pull_request event.",
    });
  }
  return { repository, number };
});

const command = CliCommand.make(
  "pr-review",
  {
    repo: repoFlag,
    pr: prFlag,
    model: modelFlag,
    post: postFlag,
    applyVerdict: applyVerdictFlag,
    fanOut: fanOutFlag,
  },
  (flags) =>
    Effect.gen(function* () {
      const { repository, number } = yield* resolveTarget(flags);
      const apiUrl = yield* Config.string("GITHUB_API_URL").pipe(
        Config.withDefault("https://api.github.com"),
      );
      const token = yield* Config.option(Config.redacted("GITHUB_TOKEN"));

      const targetLayer = GitHubReviewTarget.layer({ apiUrl, repository, number, token });
      const githubDeps = Layer.merge(targetLayer, FetchHttpClient.layer);
      const sourceLayer = gitHubPullRequestSourceLayer.pipe(Layer.provide(githubDeps));
      const publisherLayer = gitHubReviewPublisherLayer.pipe(Layer.provide(githubDeps));
      const openAiLayer = OpenAiClient.layerConfig({
        apiKey: Config.redacted("OPENAI_API_KEY"),
      }).pipe(Layer.provide(FetchHttpClient.layer));

      yield* Console.log(
        `Reviewing ${repository}#${number} with ${flags.model} (${flags.post ? "posting" : "dry run"}${flags.fanOut ? ", fan-out" : ""})...`,
      );

      const runOptions = { post: flags.post, applyVerdict: flags.applyVerdict };
      let outcome: ReviewRunOutcome;
      if (flags.fanOut) {
        const { parent, child } = makeOpenAiFanOutReviewer(flags.model);
        // The delegation handler Layer captures the child's complete runtime
        // needs at construction: its toolkit over the same source, the OpenAI
        // client, identifiers, and the in-memory delegation reservations.
        const childSupportLayer = Layer.mergeAll(
          FileReviewToolkitLayer,
          SubagentReservationsMemoryLive,
          IdGenerator.layer,
          openAiLayer,
        ).pipe(Layer.provideMerge(sourceLayer));
        outcome = yield* executeReview(parent, {
          ...runOptions,
          limits: fanOutReviewBudgetLimits,
        }).pipe(
          Effect.provide(
            Layer.mergeAll(
              FanOutCoordinatorToolkitLayer.pipe(Layer.provideMerge(sourceLayer)),
              fanOutHandlersLayer(child).pipe(Layer.provide(childSupportLayer)),
              publisherLayer,
              openAiLayer,
              IdGenerator.layer,
            ),
          ),
          Effect.scoped,
        );
      } else {
        outcome = yield* executeReview(makeOpenAiReviewer(flags.model), runOptions).pipe(
          Effect.provide(
            Layer.mergeAll(
              ReviewToolkitLayer.pipe(Layer.provideMerge(sourceLayer)),
              publisherLayer,
              openAiLayer,
              IdGenerator.layer,
            ),
          ),
          Effect.scoped,
        );
      }

      yield* Console.log(
        `Review finished in ${outcome.turns} turn(s): verdict ${outcome.review.verdict}, ` +
          `${outcome.plan.comments.length} inline comment(s), ${outcome.plan.demoted.length} demoted finding(s).`,
      );
      if (outcome.published !== undefined) {
        yield* Console.log(`Posted ${outcome.published.event} review: ${outcome.published.url}`);
      } else {
        const encodedPlan = yield* Schema.encodeEffect(ReviewPublicationPlan)(outcome.plan);
        yield* Console.log(JSON.stringify(encodedPlan, null, 2));
      }
    }),
).pipe(
  CliCommand.withDescription(
    "Review one GitHub pull request with an effect-agent reviewer and post the validated result as a pull-request review.",
  ),
);

const program = CliCommand.run(command, { version: "0.0.0" }).pipe(
  Effect.tapError((error) =>
    Console.error(
      Schema.is(BudgetExceeded)(error)
        ? `Budget exceeded: ${error.limit} observed ${error.observedValue}, limit ${error.limitValue}.`
        : String(error),
    ),
  ),
  Effect.scoped,
  Effect.provide(NodeServices.layer),
);

NodeRuntime.runMain(program, { disableErrorReporting: true });

import { Schema } from "effect";

// ---------------------------------------------------------------------------
// Changed-file and unified-diff primitives shared by the tool surface, the
// publication planner, and the GitHub adapter. The parser is deterministic
// and bounded; it never throws on malformed hunks — unparseable patch text
// simply yields no commentable lines, which fails findings closed.
// ---------------------------------------------------------------------------

/** A repository-relative file path as transported values carry it. */
export const ChangedPath = Schema.NonEmptyString.check(Schema.isMaxLength(512));

/** GitHub's changed-file status vocabulary, kept verbatim. */
export const ChangedFileStatus = Schema.Literals([
  "added",
  "removed",
  "modified",
  "renamed",
  "copied",
  "changed",
  "unchanged",
]);

/** One file changed by the pull request, with its optional textual patch. */
export class ChangedFile extends Schema.Class<ChangedFile>(
  "@effect-agent/example-pr-review/ChangedFile",
)({
  path: ChangedPath,
  status: ChangedFileStatus,
  additions: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  deletions: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)),
  /** Present for renames/copies: the path the file previously had. */
  previousPath: Schema.optionalKey(ChangedPath),
  /** Unified-diff hunks; absent for binary or oversized files. */
  patch: Schema.optionalKey(Schema.String),
}) {}

/** One parsed line of a unified diff, with both coordinate systems. */
export interface PatchLine {
  readonly kind: "context" | "add" | "del";
  readonly oldLine: number | undefined;
  readonly newLine: number | undefined;
  readonly text: string;
}

const HUNK_HEADER = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/;

/**
 * Parse unified-diff hunk text into coordinate-tagged lines. Lines outside a
 * recognized hunk header are ignored rather than guessed at.
 */
export const parsePatch = (patch: string): ReadonlyArray<PatchLine> => {
  const lines: Array<PatchLine> = [];
  let oldLine = 0;
  let newLine = 0;
  let inHunk = false;
  for (const raw of patch.split("\n")) {
    const header = HUNK_HEADER.exec(raw);
    if (header !== null) {
      oldLine = Number(header[1]);
      newLine = Number(header[2]);
      inHunk = true;
      continue;
    }
    if (!inHunk) continue;
    if (raw.startsWith("+")) {
      lines.push({ kind: "add", oldLine: undefined, newLine, text: raw.slice(1) });
      newLine += 1;
    } else if (raw.startsWith("-")) {
      lines.push({ kind: "del", oldLine, newLine: undefined, text: raw.slice(1) });
      oldLine += 1;
    } else if (raw.startsWith(" ") || raw === "") {
      lines.push({ kind: "context", oldLine, newLine, text: raw.slice(1) });
      oldLine += 1;
      newLine += 1;
    } else if (raw.startsWith("\\")) {
      // "\ No newline at end of file" — metadata, not a diff line.
    } else {
      // Unrecognized content ends the current hunk conservatively.
      inHunk = false;
    }
  }
  return lines;
};

/**
 * The new-file line numbers a GitHub review comment may anchor to on the
 * RIGHT side: every added or context line that appears in the diff.
 */
export const commentableLines = (patch: string): ReadonlySet<number> => {
  const lines = new Set<number>();
  for (const line of parsePatch(patch)) {
    if (line.newLine !== undefined) lines.add(line.newLine);
  }
  return lines;
};

/**
 * Render a patch with explicit RIGHT-side line numbers so the model can
 * anchor findings without arithmetic. `R<n>` marks a line that exists in the
 * new version of the file (`+` added, blank context); deleted lines keep a
 * bare `-` marker and no number.
 */
export const annotatePatch = (patch: string): string => {
  const output: Array<string> = [];
  let oldLine = 0;
  let newLine = 0;
  let inHunk = false;
  for (const raw of patch.split("\n")) {
    const header = HUNK_HEADER.exec(raw);
    if (header !== null) {
      oldLine = Number(header[1]);
      newLine = Number(header[2]);
      inHunk = true;
      output.push(raw);
      continue;
    }
    if (!inHunk) continue;
    if (raw.startsWith("+")) {
      output.push(`R${newLine} + ${raw.slice(1)}`);
      newLine += 1;
    } else if (raw.startsWith("-")) {
      output.push(`      - ${raw.slice(1)}`);
      oldLine += 1;
    } else if (raw.startsWith(" ") || raw === "") {
      output.push(`R${newLine}   ${raw.slice(1)}`);
      oldLine += 1;
      newLine += 1;
    } else if (raw.startsWith("\\")) {
      output.push(`        ${raw}`);
    } else {
      inHunk = false;
    }
  }
  return output.join("\n");
};

import { OpenAiLanguageModel } from "@effect/ai-openai";
import { Effect, Layer, Ref, Schema, Stream } from "effect";
import { Agent } from "effect-agent";
import { LanguageModel, Model, type Response } from "effect/unstable/ai";

import { FanOutReviewer, FileReviewer, FileReviewReport } from "./fan-out-review-agent.ts";
import { DEFAULT_REVIEW_MODEL } from "./profiles.ts";
import { CodeReview } from "./review-agent.ts";

// ---------------------------------------------------------------------------
// The fan-out reviewer's two profiles, mirroring profiles.ts: a deterministic
// offline profile with prompt-keyed scripted models for BOTH the coordinator
// and the file-reviewer children, and an opt-in live profile binding the same
// two definitions to a real OpenAI model behind the same environment gate.
// ---------------------------------------------------------------------------

/** The fan-out reviewer's committed capability claim, schema-first. */
export class FanOutReviewerProfile extends Schema.Class<FanOutReviewerProfile>(
  "@effect-agent/example-pr-review/FanOutReviewerProfile",
)({
  /** Ephemeral runtime: one bounded AgentRuntime.run per invocation. */
  deploymentClass: Schema.Literal("E"),
  /** Every model-callable tool — parent and child — is a read; none mutate. */
  readOnlyToolSurface: Schema.Literal(true),
  /** The review is posted by the host AFTER the run settles, never by a tool. */
  publicationOutsideAgentLoop: Schema.Literal(true),
  /** Child findings are untrusted; anchors are validated against the parsed diff. */
  anchorsValidatedBeforePublication: Schema.Literal(true),
  /** S1 attached ephemeral delegation at depth 1; nested delegation is rejected. */
  attachedEphemeralDelegation: Schema.Literal(true),
  /** A failed unit surfaces to the coordinator as a typed failed result, never retried. */
  failedUnitsReportedNotRetried: Schema.Literal(true),
  /** The live profile is env-gated out of every ordinary test gate. */
  liveProfileOptIn: Schema.Literal(true),
  /** Never claimed at any phase (DUR-003). */
  exactlyOnceExternalEffects: Schema.Literal(false),
}) {}

export const fanOutReviewerProfile = FanOutReviewerProfile.make({
  deploymentClass: "E",
  readOnlyToolSurface: true,
  publicationOutsideAgentLoop: true,
  anchorsValidatedBeforePublication: true,
  attachedEphemeralDelegation: true,
  failedUnitsReportedNotRetried: true,
  liveProfileOptIn: true,
  exactlyOnceExternalEffects: false,
});

// ---------------------------------------------------------------------------
// Live profile: one caller-selected OpenAI model bound to both definitions.
// The OpenAI client Layer stays application-supplied (D-027).
// ---------------------------------------------------------------------------

export const makeOpenAiFanOutReviewer = (model?: string) => {
  const languageModel = OpenAiLanguageModel.model(model ?? DEFAULT_REVIEW_MODEL, {
    max_output_tokens: 8_000,
    store: false,
    strictJsonSchema: true,
  });
  return {
    parent: Agent.withModel(FanOutReviewer, languageModel),
    child: Agent.withModel(FileReviewer, languageModel),
  };
};

// ---------------------------------------------------------------------------
// Deterministic offline profile. Both scripted models key every decision on
// committed history in the prompt (tool-call ids and briefed unit ids), never
// on call order, so concurrent children and replays stay honest.
// ---------------------------------------------------------------------------

export const OFFLINE_UNITS_CALL_ID = "units-1";

/** The delegation Tool Call id the scripted coordinator uses for one unit. */
export const offlineUnitCallId = (unitId: string): string => `delegate-${unitId}`;

/** The diff Tool Call id the scripted child uses for one unit. */
export const offlineChildDiffCallId = (unitId: string): string => `fanout-diff-${unitId}`;

const scriptedUsage = { inputTokens: { total: 64 }, outputTokens: { total: 48 } };

const toolTurn = (
  ...calls: ReadonlyArray<Response.StreamPartEncoded>
): ReadonlyArray<Response.StreamPartEncoded> => [
  ...calls,
  { type: "finish", reason: "tool-calls", usage: scriptedUsage },
];

const finalParts = (text: string): ReadonlyArray<Response.StreamPartEncoded> => [
  { type: "text-start", id: "fan-out-final" },
  { type: "text-delta", id: "fan-out-final", delta: text },
  { type: "text-end", id: "fan-out-final" },
  { type: "finish", reason: "stop", usage: scriptedUsage },
];

/** One scripted delegation the offline coordinator declares. */
export interface OfflineUnitCall {
  readonly unitId: string;
  readonly paths: ReadonlyArray<string>;
}

/**
 * Build the offline scripted coordinator model. Turn 1 lists the review
 * units, Turn 2 declares one delegation Tool Call per scripted unit in one
 * batch, Turn 3 returns the scripted merged review JSON. Decisions key on
 * tool-call ids already committed to the prompt.
 */
export const makeOfflineFanOutCoordinatorModel = (script: {
  readonly unitCalls: ReadonlyArray<OfflineUnitCall>;
  readonly review: CodeReview;
}) =>
  Effect.gen(function* () {
    const calls = yield* Ref.make(0);
    const prompts = yield* Ref.make<ReadonlyArray<string>>([]);
    const firstUnitCallId = offlineUnitCallId(script.unitCalls[0]?.unitId ?? "unit-none");
    const decide = (promptJson: string): ReadonlyArray<Response.StreamPartEncoded> => {
      if (promptJson.includes(firstUnitCallId)) {
        return finalParts(JSON.stringify(Schema.encodeSync(CodeReview)(script.review)));
      }
      if (promptJson.includes(OFFLINE_UNITS_CALL_ID)) {
        return toolTurn(
          ...script.unitCalls.map(
            (unit): Response.StreamPartEncoded => ({
              type: "tool-call",
              id: offlineUnitCallId(unit.unitId),
              name: "delegate_file_review",
              params: { unitId: unit.unitId, paths: unit.paths },
              providerExecuted: false,
            }),
          ),
        );
      }
      return toolTurn({
        type: "tool-call",
        id: OFFLINE_UNITS_CALL_ID,
        name: "list_review_units",
        params: { scope: "all" },
        providerExecuted: false,
      });
    };
    const model = Model.make(
      "scripted",
      "pr-fanout-coordinator-offline",
      Layer.effect(
        LanguageModel.LanguageModel,
        LanguageModel.make({
          generateText: () => Effect.succeed([]),
          streamText: (request) =>
            Stream.unwrap(
              Effect.gen(function* () {
                yield* Ref.update(calls, (value) => value + 1);
                const promptJson = JSON.stringify(request.prompt);
                yield* Ref.update(prompts, (previous) => [...previous, promptJson]);
                return Stream.fromIterable(decide(promptJson));
              }),
            ),
        }),
      ),
    );
    return { model, calls: Ref.get(calls), prompts: Ref.get(prompts) };
  });

/** How one scripted child behaves for its briefed unit. */
export type OfflineUnitOutcome =
  /** Read one diff, then return the scripted report. */
  | { readonly _tag: "findings"; readonly report: FileReviewReport }
  /** Read one diff, then return non-JSON — the child fails typed (AgentOutputError). */
  | { readonly _tag: "malformed-output" }
  /**
   * Declare more Tool Calls than the child's AgentPolicy allows in one turn —
   * the child fails typed (AgentPolicyError "tool-calls") before any executes.
   */
  | { readonly _tag: "budget-runaway"; readonly declaredCalls: number };

export interface OfflineUnitScript {
  readonly unitId: string;
  /** The one file the scripted child reads the diff of. */
  readonly diffPath: string;
  readonly outcome: OfflineUnitOutcome;
}

/**
 * Build the offline scripted file-reviewer model shared by every delegated
 * child. Each child Run builds the Model Layer inside its own scope; the
 * script entry is selected by the briefed unitId present in the child's OWN
 * prompt, and the turn is selected by whether that unit's diff Tool Call id
 * is already committed there — content-keyed on both axes, so concurrent
 * children never interfere. First-turn child prompts are recorded for
 * context-isolation assertions.
 */
export const makeOfflineFileReviewerModel = (scripts: ReadonlyArray<OfflineUnitScript>) =>
  Effect.gen(function* () {
    const calls = yield* Ref.make(0);
    const prompts = yield* Ref.make<ReadonlyArray<string>>([]);
    const decide = (promptJson: string): ReadonlyArray<Response.StreamPartEncoded> | undefined => {
      const script = scripts.find((candidate) => promptJson.includes(candidate.unitId));
      if (script === undefined) return undefined;
      switch (script.outcome._tag) {
        case "budget-runaway": {
          return toolTurn(
            ...Array.from(
              { length: script.outcome.declaredCalls },
              (_, index): Response.StreamPartEncoded => ({
                type: "tool-call",
                id: `runaway-${script.unitId}-${index + 1}`,
                name: "read_file_diff",
                params: { path: script.diffPath },
                providerExecuted: false,
              }),
            ),
          );
        }
        case "malformed-output":
        case "findings": {
          if (promptJson.includes(offlineChildDiffCallId(script.unitId))) {
            return finalParts(
              script.outcome._tag === "findings"
                ? JSON.stringify(Schema.encodeSync(FileReviewReport)(script.outcome.report))
                : "this is not the JSON you are looking for",
            );
          }
          return toolTurn({
            type: "tool-call",
            id: offlineChildDiffCallId(script.unitId),
            name: "read_file_diff",
            params: { path: script.diffPath },
            providerExecuted: false,
          });
        }
      }
    };
    const model = Model.make(
      "scripted",
      "pr-fanout-file-reviewer-offline",
      Layer.effect(
        LanguageModel.LanguageModel,
        LanguageModel.make({
          generateText: () => Effect.succeed([]),
          streamText: (request) =>
            Stream.unwrap(
              Effect.gen(function* () {
                yield* Ref.update(calls, (value) => value + 1);
                const promptJson = JSON.stringify(request.prompt);
                yield* Ref.update(prompts, (previous) => [...previous, promptJson]);
                const parts = decide(promptJson);
                if (parts === undefined) {
                  return yield* Effect.die(
                    new Error("The child prompt names no scripted review unit"),
                  );
                }
                return Stream.fromIterable(parts);
              }),
            ),
        }),
      ),
    );
    return { model, calls: Ref.get(calls), prompts: Ref.get(prompts) };
  });

import { Effect, Schema } from "effect";
import {
  Agent,
  AgentPolicy,
  AgentSpawner,
  IdGenerator,
  RunEventSink,
  Subagent,
  SubagentBudgetExhausted,
  SubagentDurability,
  SubagentDurabilityError,
  SubagentExecutionFailure,
  SubagentPolicy,
  SubagentPrestartDenied,
  SubagentProjectionFailure,
  SubagentRuntime,
  ToolCallWaiting,
  ToolExecutionClass,
  type RuntimeBinding,
} from "effect-agent";
import { Tool, Toolkit } from "effect/unstable/ai";

import { ChangedPath } from "./diff.ts";
import {
  CodeReview,
  ReadFile,
  ReadFileDiff,
  readFileDiffHandler,
  readFileHandler,
  ReviewFinding,
  ReviewMission,
} from "./review-agent.ts";
import {
  MAX_REVIEW_UNITS,
  MAX_UNIT_FILES,
  planReviewUnits,
  ReviewUnitId,
  ReviewUnitPlan,
} from "./review-units.ts";
import { PullRequestSource, PullRequestSourceFailure } from "./source.ts";

// ---------------------------------------------------------------------------
// The fan-out reviewer: the same review contract as the flat reviewer, but
// the diff reading happens in bounded delegated children (S1 attached
// ephemeral delegation) so no single context window has to hold every diff.
// A coordinator lists the changeset as deterministic review units, delegates
// one `delegate_file_review` call per unit, then merges the children's
// bounded findings into one `CodeReview`. Publication and anchor validation
// are unchanged: child output is untrusted input like everything else and
// crosses to the host only through the same fail-closed planPublication path.
// ---------------------------------------------------------------------------

/** One child returns at most this many findings; the merge caps the total. */
export const MAX_CHILD_FINDINGS = 8;

// ---------------------------------------------------------------------------
// The child: a file reviewer over one unit. Its toolkit is intentionally
// smaller than the flat reviewer's — diff and head-file reads only, no
// changeset listing — so a child can never roam beyond its briefed unit's
// observation surface being the whole changeset port.
// ---------------------------------------------------------------------------

export const FileReviewToolkit = Toolkit.make(ReadFileDiff, ReadFile);

export const FileReviewToolkitLayer = FileReviewToolkit.toLayer({
  read_file_diff: readFileDiffHandler,
  read_file: readFileHandler,
});

const UnitPaths = Schema.Array(ChangedPath)
  .check(Schema.isMinLength(1))
  .check(Schema.isMaxLength(MAX_UNIT_FILES));

/** The child Agent input: one briefed unit of the changeset. */
export class FileReviewBrief extends Schema.Class<FileReviewBrief>(
  "@effect-agent/example-pr-review/FileReviewBrief",
)({
  unitId: ReviewUnitId,
  paths: UnitPaths,
  focus: Schema.NonEmptyString.check(Schema.isMaxLength(200)),
}) {}

/** The child Agent output: the briefed unit's bounded findings. */
export class FileReviewReport extends Schema.Class<FileReviewReport>(
  "@effect-agent/example-pr-review/FileReviewReport",
)({
  unitId: ReviewUnitId,
  findings: Schema.Array(ReviewFinding).check(Schema.isMaxLength(MAX_CHILD_FINDINGS)),
}) {}

export const fileReviewerInstructions = (brief: FileReviewBrief): string =>
  [
    `You are a code reviewer for one unit of a pull request: unit ${brief.unitId}, covering exactly these changed files: ${brief.paths.join(", ")}. Focus: ${brief.focus}.`,
    "Work in this order:",
    "1. Call read_file_diff for every file in your unit. In its output, only lines marked R<number> exist in the new version; those numbers are the only valid values for startLine and endLine. Never anchor a finding to a removed (-) line.",
    "2. Call read_file when you need surrounding context the diff does not show. Only changed files are readable.",
    "3. Review for real defects first: correctness, security, concurrency, resource leaks, error handling, API misuse. Style nits are least important. Do not praise; do not restate the diff.",
    `4. Then return ONLY a JSON object — no Markdown fences, no prose before or after — exactly this shape: {"unitId": ${JSON.stringify(brief.unitId)}, "findings": [{"path": <string, a file in your unit>, "startLine": <integer, an R-marked new-file line>, "endLine": <integer, >= startLine, same file, R-marked>, "severity": <"blocking" | "important" | "nit">, "title": <string, <= 120 chars>, "body": <string, why it matters and what to do>, "suggestion": <string, OPTIONAL: replacement text for exactly lines startLine..endLine, ready to commit>}]}.`,
    `Report at most ${MAX_CHILD_FINDINGS} findings; prefer the most important ones. An empty findings array is a valid report. Never report on files outside your unit. Line anchors you invent will be discarded, so copy R-numbers from read_file_diff output.`,
  ].join("\n");

/**
 * The child Agent Definition. Bounds are tight and per-unit: a unit that
 * cannot be reviewed inside them fails typed and is reported by the
 * coordinator, never silently absorbed or retried.
 */
export const FileReviewer = Agent.define("pr-file-reviewer", {
  input: FileReviewBrief,
  output: FileReviewReport,
  instructions: fileReviewerInstructions,
  toolkit: FileReviewToolkit,
  policy: AgentPolicy.make({
    maxTurns: 8,
    maxToolCalls: 16,
    maxDuration: "4 minutes",
    toolConcurrency: 2,
    tokenBudget: 200_000,
  }),
  description:
    "Review one bounded unit of a pull request's changeset read-only and return line-anchored findings for exactly those files.",
  metadata: { deploymentClass: "E", surface: "read-only" },
});

// ---------------------------------------------------------------------------
// The delegation: one Effect AI Tool per review unit, with explicit
// projections and finite bounds (SUB-009). `projectResult` is the
// declassification boundary — the parent sees the child's bounded findings,
// never its transcript or the diffs it read.
// ---------------------------------------------------------------------------

/** The model-decoded delegation parameters: which unit to review. */
export class FileReviewRequest extends Schema.Class<FileReviewRequest>(
  "@effect-agent/example-pr-review/FileReviewRequest",
)({
  unitId: ReviewUnitId,
  paths: UnitPaths,
}) {}

/** The bounded parent-visible result of one delegated unit review. */
export class FileReviewUnitResult extends Schema.Class<FileReviewUnitResult>(
  "@effect-agent/example-pr-review/FileReviewUnitResult",
)({
  unitId: ReviewUnitId,
  findings: Schema.Array(ReviewFinding).check(Schema.isMaxLength(MAX_CHILD_FINDINGS)),
}) {}

/**
 * One unit's review failed: the child Run ended in a typed failure (policy
 * bound, output violation, model fault). The marker is bounded and carries no
 * child transcript content beyond the failure tag and message.
 */
export class FileReviewUnitFailed extends Schema.TaggedErrorClass<FileReviewUnitFailed>()(
  "FileReviewUnitFailed",
  {
    childErrorTag: Schema.NonEmptyString.check(Schema.isMaxLength(256)),
    message: Schema.String.check(Schema.isMaxLength(400)),
  },
) {}

/**
 * Finite per-invocation bounds (SUB-009), aligned with the child's own
 * AgentPolicy: the child's policy is the limit that trips typed; the
 * reservation mirrors it so parent-side accounting stays honest.
 */
export const fileReviewPolicy = SubagentPolicy.make({
  maxChildren: MAX_REVIEW_UNITS,
  maxConcurrency: 3,
  maxTurns: 8,
  maxToolCalls: 16,
  maxDuration: "4 minutes",
});

const delegationDescription =
  "Delegate the review of one planned unit to a bounded file-reviewer child and return its line-anchored findings. Call it exactly once per unit from list_review_units; never retry a failed unit.";

export const fileReviewDelegation = Subagent.define("delegate_file_review", {
  description: delegationDescription,
  target: FileReviewer,
  parameters: FileReviewRequest,
  success: FileReviewUnitResult,
  failure: FileReviewUnitFailed,
  prepareInput: (request) =>
    Effect.succeed(
      FileReviewBrief.make({
        unitId: request.unitId,
        paths: request.paths,
        focus: "defects-first: correctness, security, concurrency, resources, error handling",
      }),
    ),
  // The explicit declassification boundary (SUB-015): exactly the bounded
  // findings cross to the parent. Whether they may anchor anywhere is decided
  // host-side by planPublication against the real diff, not here.
  projectResult: (report) =>
    Effect.succeed(
      FileReviewUnitResult.make({
        unitId: report.unitId,
        findings: report.findings,
      }),
    ),
  policy: fileReviewPolicy,
});

/**
 * Total mapping from every expected child Run failure to the declared unit
 * failure (SUB-028): the tag plus a bounded message, nothing else crosses.
 */
export const mapFileReviewChildFailure = (failure: {
  readonly _tag: string;
  readonly message?: string;
}): FileReviewUnitFailed =>
  FileReviewUnitFailed.make({
    childErrorTag: failure._tag,
    message: (failure.message ?? "").slice(0, 400),
  });

/** Runtime wiring: the immutable delegation plus one explicit child Binding. */
export const fanOutHandlersLayer = <Provider, ModelProvides, ModelRequires>(
  childBinding: RuntimeBinding<
    typeof FileReviewBrief,
    typeof FileReviewReport,
    typeof fileReviewerInstructions,
    Toolkit.Tools<typeof FileReviewToolkit>,
    Provider,
    ModelProvides,
    ModelRequires
  >,
) =>
  SubagentRuntime.layer(fileReviewDelegation, childBinding, {
    mapChildFailure: mapFileReviewChildFailure,
  });

// ---------------------------------------------------------------------------
// The parent-facing view of the delegation Tool.
//
// `Subagent.define` fixes `failureMode: "error"`, so a failed child would
// fail the WHOLE parent Run typed — one unreviewable unit would abort the
// entire fan-out review. This coordinator wants partial results with honest
// reporting instead, so its Toolkit carries a same-name Tool value with the
// identical parameter/success/failure Schemas but `failureMode: "return"`:
// Effect AI resolves handlers by Tool NAME, so the real S1 delegation handler
// from `SubagentRuntime.layer` still executes, and a typed unit failure
// reaches the model as a failed tool result (bounded, encoded through the
// declared failure union) instead of aborting the Run. Recorded as authoring
// friction: `Subagent.define` should accept a containment policy directly.
// ---------------------------------------------------------------------------

/** Exactly the failure union `Subagent.define` declares for this delegation. */
export const FileReviewDelegationFailure = Schema.Union([
  FileReviewUnitFailed,
  SubagentPrestartDenied,
  SubagentBudgetExhausted,
  SubagentProjectionFailure,
  SubagentExecutionFailure,
  ToolCallWaiting,
  SubagentDurabilityError,
]);

export const DelegateFileReview = Tool.make("delegate_file_review", {
  description: delegationDescription,
  parameters: FileReviewRequest,
  success: FileReviewUnitResult,
  failure: FileReviewDelegationFailure,
  failureMode: "return",
})
  .addDependency(AgentSpawner)
  .addDependency(RunEventSink)
  .addDependency(SubagentDurability)
  .addDependency(IdGenerator)
  // The delegated child's whole tool surface is read-only.
  .annotate(ToolExecutionClass, "readonly");

// ---------------------------------------------------------------------------
// The coordinator's own tool: the deterministic unit plan over the changeset.
// Grouping is host code (review-units.ts), not model prose, so fan-out shape
// and budget honesty stay pinnable in tests.
// ---------------------------------------------------------------------------

export class ListReviewUnitsQuery extends Schema.Class<ListReviewUnitsQuery>(
  "@effect-agent/example-pr-review/ListReviewUnitsQuery",
)({
  /** Explicit constant keeps the zero-choice operation compatible with strict provider schemas. */
  scope: Schema.Literal("all"),
}) {}

export const ListReviewUnits = Tool.make("list_review_units", {
  description:
    "List this pull request's changeset grouped into bounded review units (size-budgeted, directory-affine), plus the files no unit can cover.",
  parameters: ListReviewUnitsQuery,
  success: ReviewUnitPlan,
  failure: PullRequestSourceFailure,
  failureMode: "error",
  dependencies: [PullRequestSource],
}).annotate(ToolExecutionClass, "readonly");

export const FanOutCoordinatorToolkit = Toolkit.make(ListReviewUnits);

export const FanOutCoordinatorToolkitLayer = FanOutCoordinatorToolkit.toLayer({
  list_review_units: () =>
    Effect.gen(function* () {
      const source = yield* PullRequestSource;
      const files = yield* source.changedFiles;
      const metadata = yield* source.metadata;
      return planReviewUnits(files, { totalChangedFiles: metadata.totalChangedFiles });
    }),
});

// ---------------------------------------------------------------------------
// The coordinator Agent Definition: same mission input and CodeReview output
// contract as the flat reviewer, so planPublication and anchor validation
// apply unchanged.
// ---------------------------------------------------------------------------

export const FanOutReviewToolkit = Toolkit.make(ListReviewUnits, DelegateFileReview);

export const fanOutReviewInstructions = (mission: ReviewMission): string =>
  [
    `You coordinate the review of pull request #${mission.number} ("${mission.title}") in ${mission.repository}, merging ${mission.headRef} into ${mission.baseRef}. It changes ${mission.changedFileCount} file(s).`,
    mission.body.length > 0
      ? `Author description:\n${mission.body}`
      : "The author provided no description.",
    "Work in this order:",
    "1. Call list_review_units once to get the planned review units.",
    "2. Call delegate_file_review EXACTLY once per unit, passing each unit's unitId and paths verbatim. Prefer declaring all delegation calls in one batch. Never review files yourself and never invent units.",
    '3. A delegation result with "_tag" is a FAILED unit. Never retry it; instead your summary MUST name it honestly, e.g. "unit-002 unreviewed: AgentPolicyError". The plan\'s undiffablePaths and unassignedPaths must also be named as not reviewed when present.',
    "4. Merge the successful units' findings: drop duplicates sharing the same path and line range keeping the most severe, rank blocking > important > nit, and keep at most 20 findings.",
    '5. Then return ONLY a JSON object — no Markdown fences, no prose before or after — exactly this shape: {"summary": <string, 1-3 paragraphs of overall assessment, including every unreviewed unit or file>, "verdict": <"approve" | "comment" | "request-changes">, "findings": [{"path": <string>, "startLine": <integer>, "endLine": <integer>, "severity": <"blocking" | "important" | "nit">, "title": <string, <= 120 chars>, "body": <string>, "suggestion": <string, OPTIONAL>}]}. Copy findings verbatim from the delegation results; never invent or edit anchors.',
    'Use verdict "request-changes" only when at least one finding is "blocking". An empty findings array with verdict "approve" is a valid review when every unit succeeded and found nothing.',
  ].join("\n");

export const FanOutReviewer = Agent.define("pr-fanout-reviewer", {
  input: ReviewMission,
  output: CodeReview,
  instructions: fanOutReviewInstructions,
  toolkit: FanOutReviewToolkit,
  policy: AgentPolicy.make({
    maxTurns: 6,
    maxToolCalls: 1 + MAX_REVIEW_UNITS,
    maxDuration: "15 minutes",
    toolConcurrency: 3,
    tokenBudget: 300_000,
  }),
  description:
    "Coordinate one pull-request review by fanning bounded per-unit file reviews out to delegated children and merging their findings into one structured review.",
  metadata: { deploymentClass: "E", surface: "read-only", delegation: "S1-attached" },
});

